window.POEM_DB=window.POEM_DB||{};POEM_DB["yuan_004"]={"n":"元好问","dyn":"元","poems":[{"t":"元鲁县琴台","f":"五言古诗","c":["荒城草木合，破屋风雨侵。","千年一琴台，眷焉涕盈襟。","遗爱食县社，公宁不堪任。","此台即甘棠，忍使无馀阴。","旁舍高以华，大豪日捐金。","苍云玄武暮，鬼物凭阴岑。","尚德抑玄虚，坠典谁当寻？","我兴荐寒泉，百拜公来临。","公来不能知，落日下饥禽。","怀哉空山里，鹤飞猿与吟。","当年于蔿歌，补衮一何深。","承平示得意，独能正哇淫。","君相此一时，又复悟良箴。","谀臣坐废黜，盍亦起幽沈。","蒲轮竟颓毂，香草空深林。","寂寞授书室，孤甥举遗衾。","生平谅已然，薄俗矧来今。","千山为公台，万籁为公琴。","夔旷不并世，月露为知音。","人间蹄涔耳，已矣非公心。"]},{"t":"古意二首 其一","f":"五言古诗","c":["七岁入小学，十五学时文。","二十学业成，随计入咸秦。","秦中多贵游，几与书生亲。","年年抱关吏，空笑西来频。","在昔学语初，父兄已卜邻。","跛鳖不量力，强欲缘青云。","四十有牧豕，五十有负薪。","寂寥抱玉献，贱薄倡优陈。","青衫亦区区，何时画麒麟。","遇合仅一二，饥寒几何人。","谁留章甫冠，万古徒悲辛。"]},{"t":"古意二首 其二","f":"曲","c":["桃李弄娇娆，梨花澹丰容。","盈盈两无语，??争春风。","春风何许来，草木谁青红。","天公亦老矣，何意夸儿童。","昨朝花正开，今朝花已空。","川流不肯驻，并与繁华东。","楩楠千岁姿，肮脏空谷中。","阳和不择地，亦复难为功。","本无儿女心，安用尤天公。"]},{"t":"赠答刘御史云卿","f":"五言古诗","c":["学道有通蔽，今人乃其尤。","温柔与敦厚，扫灭不复留。","高蹇当父师，排击剧寇雠。","真是未可必，自私有足羞。","古人相异同，宁复操戈矛。","春风入万物，枯蘖将和柔。","克己未有加，归仁亦何由。","先儒骨已腐，百骂不汝酬。","胡为文字间，刮垢搜瘢疣。","吾道非申韩，哀哉涉其流。","大儒不知道，此论信以不。","我观唐以还，斯文有伊周。","开云揭日月，不独程张俦。","圣途同一归，论功果谁优？","户牖徒自辟，胶漆本易投。","九原如可作，吾欲起韩欧。"]},{"t":"送钦叔内翰并寄刘达卿郎中白文举编修二首 其一","f":"五言古诗","c":["君性我所谙，我心君所知。","凡我之所短，君亦时有之。","谋事恨太锐，临断恨太迟。","持论恨太高，徇俗恨太卑。","人道自近始，贫富理不齐。","君自不得饱，欲疗何人饥。","乞醯乞诸邻，圣哲有明讥。","被发救乡人，智者所不为。","且如与人交，交有非所宜。","白黑不复择，豁豁倾心脾。","汎爱岂不可，后悔终自贻。","又如与人言，宁复无失辞。","刺口论成败，白眼谈歌诗。","世故彀黄閒，能不发其机。","闻君作损斋，似觉豪华非。","惩忿与窒欲，百年有良规。","与子各努力，岁晚以为期。"]},{"t":"送钦叔内翰并寄刘达卿郎中白文举编修二首 其二","f":"五言古诗","c":["古人遥相望，每恨不同时。","同时得古人，欢乐良在兹。","君归岂不佳，交游满京师。","门前车马来，笑言慰所思。","细话洛阳事，高咏嵩山诗。","宫壶发新篘，宫梅耿幽姿。","故应刘与白，亦复念微之。"]},{"t":"山居杂诗六首 其三","f":"五言绝句","c":["树合秋声满，村荒暮景閒。","虹收仍白雨，云动忽青山。"]},{"t":"前高山杂诗 天池","f":"七言绝句","c":["天池一雨洗氛埃，全晋堂堂四望开。","不上朝元峰北顶，真成不到此山来。"]},{"t":"台山杂吟","f":"七言绝句","c":["山云吞吐翠微中，淡绿深青一万重。","此景只应天上有，岂知身在妙高峰。"]},{"t":"台山杂咏五首 其一","f":"七言绝句","c":["西北天低五顶高，茫茫松海露灵鳌。","太行直上犹千里，井底残山枉叫号。"]},{"t":"台山杂吟","f":"七言绝句","c":["万壑千岩位置雄，偶从天巧见神功。","湍溪已作风雷恶，更在云山气象中。"]},{"t":"台山杂吟","f":"七言绝句","c":["颠风作力扫阴霾，白日青天四望开。","好个台山真面目，争教坡老不曾来？"]},{"t":"同儿辈赋未开海棠二首 其二","f":"七言绝句","c":["枝间新绿一重重，小蕾深藏数点红。","爱惜芳心莫轻吐，且教桃李闹春风。"]},{"t":"论诗三十首 其四","f":"七言绝句","c":["一语天然万古新，豪华落尽见真淳。","南窗白日羲皇上，未害渊明是晋人。"]},{"t":"论诗三十首 其十","f":"七言绝句","c":["排比铺张特一途，藩篱如此亦区区。","少陵自有连城璧，争奈微之识珷玞。"]},{"t":"论诗三十首 其二十二","f":"七言绝句","c":["奇外无奇更出奇，一波才动万波随。","只知诗到苏黄尽，沧海横流却是谁？"]},{"t":"论诗三十首 其十一","f":"七言绝句","c":["眼处心生句自神，暗中摸索总非真。","画图临出秦川景，亲到长安有几人？"]},{"t":"论诗三十首 其二十七","f":"七言绝句","c":["百年才觉古风回，元祐诸人次第来。","讳学金陵犹有说，竟将何罪废欧梅？"]},{"t":"论诗三十首 其二十五","f":"七言绝句","c":["乱后玄都失故基，看花诗在只堪悲。","刘郎也是人间客，枉向春风怨兔葵。"]},{"t":"论诗三十首 其六","f":"七言绝句","c":["心画心声总失真，文章宁复见为人。","高情千古《閒居赋》，争信安仁拜路尘。"]},{"t":"论诗三十首 其三","f":"七言绝句","c":["邺下风流在晋多，壮怀犹见缺壶歌。","风云若恨张华少，温李新声奈尔何。"]},{"t":"论诗三十首 其二十一","f":"七言绝句","c":["窘步相仍死不前，唱酬无复见前贤。","纵横正有凌云笔，俯仰随人亦可怜。"]},{"t":"论诗三十首 其八","f":"七言绝句","c":["沈宋横驰翰墨场，风流初不废齐梁。","论功若准平吴例，合著黄金铸子昂。"]},{"t":"论诗三十首 其十八","f":"七言绝句","c":["东野穷愁死不休，高天厚地一诗囚。","江山万古潮阳笔，合在元龙百尺楼。"]},{"t":"论诗三十首 其二十八","f":"七言绝句","c":["古雅难将子美亲，精纯全失义山真。","论诗宁下涪翁拜，未作江西社里人。"]},{"t":"论诗三十首 其十五","f":"七言绝句","c":["笔底银河落九天，何曾憔悴饭山前。","世间东抹西涂手，枉著书生待鲁连。"]},{"t":"论诗三十首 其三十","f":"七言绝句","c":["撼树蚍蜉自觉狂，书生技痒爱论量。","老来留得诗千首，却被何人较短长。"]},{"t":"论诗三十首 其十二","f":"七言绝句","c":["望帝春心托杜鹃，佳人锦瑟怨华年。","诗家总爱西昆好，独恨无人作郑笺。"]},{"t":"论诗三十首 其二十九","f":"七言绝句","c":["池塘春草谢家春，万古千秋五字新。","传语闭门陈正字，可怜无补费精神。"]},{"t":"论诗三十首 其九","f":"七言绝句","c":["斗靡誇多费览观，陆文犹恨冗于潘。","心声只要传心了，布谷澜翻可是难。"]},{"t":"论诗三十首 其十四","f":"七言绝句","c":["出处殊涂听所安，山林何得贱衣冠。","华歆一掷金随重，大是渠侬被眼谩。"]},{"t":"论诗三十首 其二十三","f":"七言绝句","c":["曲学虚荒小说欺，俳谐怒骂岂宜时。","今人合笑古人拙，除却雅言都不知。"]},{"t":"论诗三十首 其二十四","f":"七言绝句","c":["有情芍药含春泪，无力蔷薇卧晚枝。","拈出退之山石句，始知渠是女郎诗。"]},{"t":"论诗三十首 其五","f":"七言绝句","c":["纵横诗笔见高情，何物能浇磈磊平。","老阮不狂谁会得？","出门一笑大江横。"]},{"t":"论诗三十首 其二","f":"七言绝句","c":["曹刘坐啸虎生风，四海无人角两雄。","可惜并州刘越石，不教横槊建安中。"]},{"t":"论诗三十首 其二十六","f":"七言绝句","c":["金入洪炉不厌频，精真那计受纤尘。","苏门果有忠臣在，肯放坡诗百态新。"]},{"t":"论诗三十首 其十七","f":"七言绝句","c":["切响浮声发巧深，研磨虽苦果何心？","浪翁水乐无宫徵，自是云山韶濩音。"]},{"t":"杨柳","f":"七言绝句","c":["杨柳青青沟水流，莺儿调舌弄娇柔。","桃花记得题诗客，斜倚春风笑不休。"]},{"t":"癸巳五月三日北渡三首","f":"七言绝句","c":["白骨纵横似乱麻，几年桑梓变龙沙。","只知河朔生灵尽，破屋疏烟却数家！"]},{"t":"癸巳五月三日北渡三首","f":"七言绝句","c":["道旁僵卧满累囚，过去旃车似水流。","红粉哭随回鹘马，为谁一步一回头？"]},{"t":"梁县道中","f":"七言绝句","c":["青山簇簇树重重，人在春云浩荡中。","也是杏花无意况，一枝临水卧残红。"]},{"t":"俳体雪香亭杂咏十二首 其二","f":"七言绝句","c":["落日青山一片愁，大河东注不还流。","若为长得熙春在，时上高层望宋州。"]},{"t":"壬辰十二月车驾东狩后即事五首 其二","f":"七言律诗","c":["惨澹龙蛇日斗争，干戈真欲尽生灵。","高原水出山河改，战地风来草木腥。","精卫有冤填瀚海，包胥无泪哭秦庭。","并州豪杰知谁在？","莫拟分军下井陉。"]},{"t":"壬辰十二月车驾东狩后即事五首 其四","f":"七言律诗","c":["万里荆襄入战尘，汴州门外即荆榛。","蛟龙岂是池中物，虮虱空悲地上臣。","乔木他年怀故国，野烟何处望行人？","秋风不用吹华发，沧海横流要此身。"]},{"t":"甲午除夜","f":"七言律诗","c":["暗中人事忽推迁，坐守寒灰望复燃。","已恨太官余曲饼，争教汉水入胶船？","神功圣德三千牍，大定明昌五十年。","甲子两周今日尽，空将衰泪洒吴天。"]},{"t":"石门","f":"七言律诗","c":["两崖悬绝倚山垠，草径低迷劣可分。","潭影乍从明处见，竹香偏向静中闻。","石林万古不知暑，茅屋四邻惟有云。","曳杖行歌羡樵叟，此生何计得随君。"]},{"t":"过诗人李长源故居","f":"七言律诗","c":["楚些招魂自往年，明珠真见抵深渊。","巨鳌有铒虽堪钓，怒虎无情可重编。","千丈豪气天也妒，七言诗好世空传。","伤心鹦鹉洲边泪，却望西山一泫然。"]},{"t":"别程女","f":"七言律诗","c":["芸斋淅淅掩霜寒，别酒青灯语夜阑。","生女便知聊寄托，中年尤觉感悲欢。","松间小草栽培稳，掌上明珠弃掷难。","明日缑山东畔路，野夫怀抱若为宽？"]},{"t":"岐阳三首 其二","f":"七言律诗","c":["百二关河草木横，十年戎马暗秦京。","岐阳西望无来信，陇水东流闻哭声。","野蔓有情萦战骨，残阳何意照空城。","从谁细向苍苍问，争遣蚩尤作五兵。"]},{"t":"昆阳二首 其一","f":"七言律诗","c":["古木荒烟集暮鸦，高城落日隐悲笳。","并州倦客初投迹，楚泽寒梅又过花。","满眼旌旗惊世路，闭门风雪羡山家。","忘忧只有清尊在，暂为红尘拂鬓华。"]},{"t":"洛阳","f":"七言律诗","c":["千年河岳控喉襟，一日神州见陆沈。","已为操琴感衰涕，更须同辇梦秋衾。","城头大匠论蒸土，地底中郎待摸金。","拟就天公问翻复，蒿莱丹碧果何心。"]},{"t":"咏怀","f":"七言律诗","c":["凉叶萧萧散雨声，虚堂淅淅掩霜清。","黄华自与西风约，白发先从远客生。","吟似候虫秋更苦，梦和寒鹊夜频惊。","何时石岭关头路？","一望家山眼暂明。"]},{"t":"晋溪","f":"七言律诗","c":["石蹬云松著色屏，岸花汀草展江亭。","青瑶叠甃通悬瓮，白玉双龙掣迅霆。","地脉何尝间今昔，尾闾真解泄沧溟。","乾坤一雨兵尘了，好就川妃问乞灵。"]},{"t":"眼中","f":"七言律诗","c":["眼中时事益纷然，拥被寒窗夜不眠。","骨肉他乡各异县，衣冠今日是何年？","枯槐聚蚁无多地，秋水鸣蛙自一天。","何处青山隔尘土？","一庵吾欲送华颠。"]},{"t":"雁门关外","f":"七言律诗","c":["四海于今正一家，生民何处不桑麻。","重关独居千寻岭，深夏犹飞六出花。","云暗白杨连马邑，天围青冢渺龙沙。","凭高吊古情无尽，空对西风数去鸦。"]},{"t":"横波亭为青口帅赋","f":"七言律诗","c":["孤亭突兀插飞流，气压元龙百尺楼。","万里风涛接瀛海，千年豪杰壮山丘。","疏星澹月鱼龙夜，老木清霜鸿雁秋。","倚剑长歌一杯酒，浮云西北是神州。"]},{"t":"出都二首 其二","f":"七言律诗","c":["历历兴亡败局棋，登临疑梦复疑非。","断霞落日天无尽，老树遗台秋更悲。","沧海忽惊龙穴露，广寒犹想凤笙归。","从教尽刬琼华了，留在西山尽泪垂。"]},{"t":"外家南寺","f":"七言律诗","c":["郁郁楸梧动晚烟，一庭风露觉秋偏。","眼中高岸移深谷，愁里残阳更乱蝉。","去国衣冠有今日，外家梨栗记当年。","白头来往人间遍，依旧僧窗借榻眠。"]},{"t":"过晋阳故城书事","f":"曲","c":["惠远祠前晋溪水，翠叶银花清见底。","水上西山如卧屏，郁郁苍苍三百里。","中原北门形势雄，想见城阙云烟中。","望川亭上阅今古，但有麦浪摇春风。","君不见系舟山头龙角秃，白塔一摧城覆没。","薛王出降民不降，屋瓦乱飞如箭镞。","汾流决入大夏门，府治移著唐明村。","只从巨屏失光彩，河洛几度风烟昏。","东阙苍龙西玉虎，金雀觚棱上云雨。","不论民居与官府，仙佛所庐馀百所。","鬼役天财千万古，争教一炬成焦土。","至今父老哭向天，死恨河南往来苦。","南人鬼巫好禨祥，万夫畚锸开连冈。","官街十字改丁字，钉破并州渠亦亡。","几时却到承平了，重看官家筑晋阳。"]},{"t":"涌金亭示同游诸君","f":"曲","c":["太行元气老不死，上与左界分山河。","有如巨鳌昂头西入海，突兀已过馀坡陀。","我从汾晋来，山之面目腹背皆经过。","济源盘谷非不佳，烟景独觉苏门多。","涌金亭下百泉水，海眼万古留山阿。","觱沸泺水源，奫沦晋溪波。","云雷涵鬼物，窟宅深蛟鼍。","水妃簸弄明月玑，地藏发泄天不诃。","平湖油油碧于酒，云锦十里翻风荷。","我来适与风雨会，世界三日漫兜罗。","山行不得山，北望空长哦。","今朝一扫众峰出，千鬟万髻高峨峨。","空青断石壁，微茫散烟萝。","山阳十月未摇落，翠蕤云旓相荡摩。","云烟故为出浓淡，鱼鸟似欲留婆娑。","石间仙人迹，石烂迹不磨。","仙人去不返，六龙忽蹉跎。","江山如此不一醉，拊掌笑杀孙公和。","长安城头乌尾讹，并州少年夜枕戈。","举杯为问谢安石，苍生今亦如卿何，元子乐矣君其歌。"]},{"t":"续小娘歌十首 其六","f":"七言绝句","c":["雁雁相送过河来，人歌人哭雁声哀。","雁到秋来却南去，南人北渡几时回。"]},{"t":"续小娘歌十首 其三","f":"七言绝句","c":["山无洞穴水无船，单骑驱人动数千。","直使今年留得在，更教何处避明年。"]},{"t":"游天坛杂诗五首 其四","f":"七言绝句","c":["湍声汹汹落悬崖，见说蛟龙擘石开。","安得天瓢一翻倒，蹑云平下看风雷。"]},{"t":"登恒山","f":"七言律诗","c":["大茂维岳古帝孙，太朴未散真巧存。","乾坤自有灵境在，奠位岂合他山尊。","椒原旌旗白日跃，山界楼观苍烟屯。","谁能借我两黄鹄，长袖一拂元都门。"]},{"t":"颍亭","f":"七言律诗","c":["颍上风烟天地回，颍亭孤赏亦悠哉。","春风碧水双鸥静，落日青山万马来。","胜概销沈几今昔，中年登览足悲哀。","远游拟续骚人赋，所惜匆匆无酒杯。"]},{"t":"水调歌头 赋三门津","f":"曲","c":["黄河九天上，人鬼瞰重关。","长风怒卷高浪，飞洒日光寒。","峻似吕梁千仞，壮似钱塘八月，直下洗尘寰。","万象入横溃，依旧一峰闲。","仰危巢，双鹄过，杳难攀。","人间此险何用，万古秘神奸。","不用燃犀下照，未必佽飞强射，有力障狂澜，唤取骑鲸客，挝鼓过银山。"]},{"t":"摸鱼儿","f":"曲","c":["问人间、情是何物，直教生死相许。","天南地北双飞客，老翅几回寒暑。","欢乐趣。","离别苦。","是中更有痴儿女。","君应有语。","渺万里层云，千山暮景，只影为谁去。","横汾路。","寂寞当年箫鼓。","荒烟依旧平楚。","招魂楚些何嗟及，山鬼自啼风雨。","天也妒。","未信与、莺儿燕子俱黄土。","千秋万古。","为留待骚人，狂歌痛饮，来访雁丘处。"]},{"t":"鹧鸪天","f":"曲","c":["只近浮名不近情。","且看不饮更何成。","三杯渐觉纷华远，一斗都浇块磊平。","醒复醉，醉还醒。","灵均憔悴可怜生。","离骚读杀浑无味，好个诗家阮步兵。"]},{"t":"骤雨打新荷","f":"曲","c":["绿叶阴浓，遍池亭水阁，偏趁凉多。","海榴初绽，朵朵簇红罗。","乳燕雏莺弄语，有高柳鸣蟑相和。","骤雨过，珍珠乱撒，打遍新荷。","人生百年有几，念良辰美景，休放虚过。","穷通前定，何用苦张罗。","命友邀宾玩赏，对芳尊浅酌低歌。","且酩酊，任他两轮日月，来往如梭。"]},{"t":"饮酒五首 其一","f":"五言律诗","c":["西郊一亩宅，闭门秋草深。","床头有新酿，意惬成孤斟。","举杯谢明月，蓬荜肯相临。","愿将万古色，照我万古心。"]},{"t":"山居杂诗六首 其六","f":"五言绝句","c":["鹭影兼秋静，蝉声带晚凉。","陂长留积水，川阔尽斜阳。"]},{"t":"山居杂诗六首 其一","f":"五言绝句","c":["瘦竹藤斜挂，丛花草乱生。","林高风有态，苔滑水无声。"]},{"t":"山居杂诗六首 其四","f":"五言绝句","c":["川迥枫林散，山深竹港幽。","疏烟沈去鸟，落日送归牛。"]},{"t":"同儿辈赋未开海棠二首 其一","f":"七言绝句","c":["翠叶轻笼豆颗匀，胭脂浓抹蜡痕新。","殷勤留著花梢露，滴下生红可惜春。"]},{"t":"论诗三十首 其十九","f":"七言绝句","c":["万古幽人在涧阿，百年孤愤竟如何？","无人说与天随子，春草输赢校几多。"]},{"t":"论诗三十首 其十三","f":"七言绝句","c":["万古文章有坦途，纵横谁似玉川卢。","真书不入今人眼，儿辈从教鬼画符。"]},{"t":"论诗三十首 其一","f":"七言绝句","c":["汉谣魏什久纷纭，正体无人与细论。","谁是诗中疏凿手，暂教泾渭各清浑。"]},{"t":"论诗三十首 其七","f":"七言绝句","c":["慷慨歌谣绝不传，穹庐一曲本天然。","中州万古英雄气，也到阴山敕勒川。"]},{"t":"论诗三十首 其十六","f":"七言绝句","c":["切切秋虫万古情，灯前山鬼泪纵横。","鉴湖春好无人赋，夹岸桃花锦浪生。"]},{"t":"论诗三十首 其二十","f":"七言绝句","c":["谢客风容映古今，发源谁似柳州深？","朱弦一拂遗音在，却是当年寂寞心。"]},{"t":"杏花杂诗八首 其一","f":"七言绝句","c":["杏花墙外一枝横，半面宫妆出晓晴。","看尽春风不回首，宝儿元自太憨生。"]},{"t":"杏花杂诗八首 其三","f":"七言绝句","c":["袅袅纤条映酒船，绿娇红小不胜怜。","长年自笑情缘在，犹要春风慰眼前。"]},{"t":"榆社硖口村早发","f":"七言绝句","c":["瘦马长途懒著鞭，客怀牢落五更天。","几时不属鸡声管，睡彻东窗日影偏。"]},{"t":"乙卯十一月往镇州","f":"五言律诗","c":["村静鸟声乐，山低雁影遥。","野阴时滉朗，冷雨只飘萧。","涉远心先倦，冲寒酒易消。","红尘忘南北，渺渺见长桥。"]},{"t":"九月晦日王村道中","f":"五言律诗","c":["水涸沙仍湿，霜馀草更幽。","烟光藏落景，山骨露清秋。","坐食知何益，行吟只自愁。","随阳见鸿雁，三叹惜淹留。"]},{"t":"八月并州雁","f":"五言律诗","c":["八月并州雁，清汾照旅群。","一声惊晚笛，数点入秋云。","灭没楼中见，哀劳枕畔闻。","南来还北去，无计得随君。"]},{"t":"少室南原","f":"五言律诗","c":["地僻人烟断，山深鸟语哗。","清溪鸣石齿，暖日长藤芽。","绿映高低树，红迷远近花。","林间见鸡犬，直拟是仙家。"]},{"t":"出都二首 其一","f":"七言律诗","c":["汉宫曾动伯鸾歌，事去英雄可奈何。","但见觚棱上金爵，岂知荆棘卧铜驼。","神仙不到秋风客，富贵空悲春梦婆。","行过卢沟重回首，凤城平日五云多。"]},{"t":"送樊顺之","f":"七言律诗","c":["弓刀十驿岳莲州，渭水秦山得意秋。","王粲从军正年少，庾郎入幕更风流。","寒乡况味真鸡肋，清镜功名属虎头。","寄谢溪风亭上月，老夫乘兴欲西游。"]},{"t":"被檄夜赴邓州幕府","f":"七言律诗","c":["幕府文书鸟羽轻，敝裘羸马月三更。","未能免俗私自笑，岂不怀归官有程。","十里陂塘春鸭闹，一川桑柘晚烟平。","此生只合田间老，谁遣春官识姓名。"]},{"t":"寄刘继先","f":"七言律诗","c":["清霜茅屋耿无眠，坐忆分携一慨然。","楚客登临动归兴，谢公哀乐感中年。","凄凉古驿人烟外，迤逦荒山雪意边。","千树春风水杨柳，待君同系晋溪船。"]},{"t":"天门引","f":"七言古诗","c":["秦王宫中不得近，从破衡成欲谁信。","白头游客困咸阳，憔悴黄金百斤尽。","海中仙人黄鹤举，大笑人间争腐鼠。","丈夫何意作苏秦，六印才堪警儿女。","古来多为虚名老，不见阿房净如扫。","千年虎豹守天门，一日牛羊卧秋草。"]},{"t":"少林","f":"五言律诗","c":["云林入清深，禅房坐萧爽。","澄泉洁馀习，高鸟唤长往。","我无玄豹姿，谩有紫霞想。","回首山中云，灵芝日应长。"]},{"t":"王右丞雪霁捕鱼图","f":"七言律诗","c":["江云滉滉阴晴半，沙雪离离点江岸。","画中不信有天机，细向树林枯处看。","渔浦移家愧未能，扁舟萧散亦何曾。","白头岁月黄尘底，笑杀高人王右丞。"]},{"t":"出京","f":"五言古诗","c":["从宦非所堪，长告欣得请。","驱马出国门，白日触隆景。","半生无根著，飘转如断梗。","一昨随牒来，六月阻归省。","城居苦湫隘，群动日蛙黾。","惭愧山中人，团茅遂幽屏。","尘泥久相浣，梦寐见清颍。","矫首孤飞云，西南路何永。"]},{"t":"龙门杂诗","f":"五言古诗","c":["石楼绕清伊，尘土天所限。","人言无僧久，草满不复刬。","滩声激悲壮，山意出高蹇。","当年香山老，挂冠遂忘返。","高情留诗轴，清话入禅版。","谁言海山去？","萧散仍在眼。","溪寒不可涉，倚杖西林晚。"]},{"t":"光武台","f":"五言古诗","c":["东南地上游，荆楚兵四冲。","游子十月来，登高送长鸿。","当年赤帝孙，提剑起蒿蓬。","一顾滍水断，再顾新都空。","雷霆万万古，青天看飞龙。","岿然此遗台，落日荒烟重。","谁见经纶初，指挥走群雄。","白水日夜东，石麟几秋风。","空馀广武叹，无复云台功。"]},{"t":"刘曲龙潭","f":"五言古诗","c":["层冰积浩荡，陵谷低吞吐。","窈窕转幽壑，突兀开净宇。","回头山水县，亦复堕尘土。","孤云铁梁北，宇宙一仰俯。","风景初不殊，川涂忽修阻。","寒潭海眼净，黕黑自太古。","蛰龙何年卧？","万国待霖雨。","谁能裂苍崖，雷风看掀举。"]},{"t":"西楼曲","f":"七言古诗","c":["游丝落絮春漫漫，西楼晓晴花作团。","楼中少妇弄瑶瑟，一曲未终坐长叹。","去年与郎西入关，春风浩荡随金鞍。","今年匹马妾东还，零落芙蓉秋水寒。","并刀不剪东流水，湘竹年年泪痕紫。","海枯石烂两鸳鸯，只合双飞便双死。","重城车马红尘起，乾鹊无端为谁喜。","镜中独语人不知，欲插花枝泪如洗。"]},{"t":"泛舟大明湖","f":"曲","c":["长白山前绣江水，展放荷花三十里。","看山水底山更佳，一堆苍烟收不起。","山从阳丘西来青一弯，天公掷下半玉环。","大明湖上一杯酒，昨日绣江眉睫间。","晚凉一棹东城渡，水暗荷深若无路。","江妃不惜水芝香，狼藉秋风与秋露。","兰襟郁郁散芳泽，罗袜盈盈见微步。","晚晴一赋画不成，枉著风标誇白鹭。","我时骖鸾追散仙，但见金支翠蕤相后先。","眼花耳热不称意，高唱吴歌叩两舷。","唤取樊川摇醉笔，风流聊与付他年。"]},{"t":"晓发石门渡湍水道中","f":"五言古诗","c":["疏星澹秋明，阴霞绚朝映。","积雨成坐愁，晨光动幽兴。","石门归驭引，湍浦渔舠并。","旷荡万景新，归藏四山静。","平湖风漪绿，远岸秋沙净。","洋洋游鱼逝，汎汎轻鸥泳。","隐显乖夙心，感遇见真性。","倦游时自悼，违己将安竟。","忧端从中来，茫茫发孤咏。"]},{"t":"望云谣","f":"曲","c":["涉江采芙蓉，芙蓉待秋风。","登山采兰苕，兰苕霜早彫。","美人亭亭在云霄，郁摇行歌不可招。","湘弦沈沈写幽怨，愁心历乱如曳茧。","金支翠蕤纷在眼，春草迢迢春波远。"]},{"t":"望归吟","f":"七言古诗","c":["塞云一抹平如截，塞草离离卧榆叶。","长城窟深战骨寒，万古牛羊饮冤血。","少年锦带佩吴钩，独骑匹马觅封侯。","去时只道从军乐，不道关山空白头。","北风吹沙杂飞雪，弓弦有声冻欲折。","寒衣昨夜洛阳来，肠断空闺捣秋月。","年年岁岁望还家，此日归期转未涯。","谁与南州问消息，几时重拜李轻车。"]},{"t":"游黄华山","f":"七言古诗","c":["黄华水帘天下绝，我初闻之雪溪翁。","丹霞翠壁高欢宫，银河下濯青芙蓉。","昨朝一游亦偶尔，更觉摹写难为功。","是时气节已三月，山木赤立无春容。","湍声汹汹转绝壑，雪气凛凛随阴风。","悬流千丈忽当眼，芥蒂一洗平生胸。","雷公怒击散飞雹，日脚倒射垂长虹。","骊珠百斛供一泻，海藏翻倒愁龙公。","轻明圆转不相碍，变见融结谁为雄？","归来心魄为动荡，晓梦月落春山空。","手中仙人九节杖，每恨胜景不得穷。","携壶重来岩下宿，道人已约山樱红。"]},{"t":"湘夫人咏","f":"七言律诗","c":["木兰芙蓉满芳洲，白云飞来北渚游。","千秋万岁帝乡远，云来云去空悠悠。","秋风秋月沅江渡，波上寒烟引轻素。","九疑山高猿夜啼，竹枝无声堕残露。"]},{"t":"缑山置酒","f":"五言古诗","c":["灵宫肃清晓，细柏含古春。","人言王子乔，鹤驭此上宾。","白云山苍苍，平田木欣欣。","登高览元化，浩荡融心神。","西望洛阳城，大路通平津。","行人细如蚁，扰扰争红尘。","蓬莱风涛深，鬓毛日夜新。","殷勤一杯酒，愧尔云间人。"]},{"t":"颍亭留别","f":"五言古诗","c":["故人重分携，临流驻归驾。","乾坤展清眺，万景若相借。","北风三日雪，太素秉元化。","九山郁峥嵘，了不受陵跨。","寒波淡淡起，白鸟悠悠下。","怀归人自急，物态本閒暇。","壶觞负吟啸，尘土足悲咤。","回首亭中人，平林澹如画。"]},{"t":"箕山","f":"五言古诗","c":["幽林转阴崖，鸟道人迹绝。","许君栖隐地，唯有太古雪。","人间黄屋贵，物外秖自洁。","尚厌一瓢喧，重负宁所屑。","降衷均义禀，汩利忘智决。","得陇又望蜀，有齐安用薛。","干戈几蛮触，宇宙日流血。","鲁连蹈东海，夷齐采薇蕨。","至今阳城山，衡华两丘垤。","古人不可作，百念肝肺热。","浩歌北风前，悠悠送孤月。"]},{"t":"㶏亭","f":"五言古诗","c":["春物已清美，客怀自幽独。","危亭一徘徊，翛然若新沐。","宿云淡野川，元气浮草木。","微茫尽楚尾，平远疑杜曲。","生平远游赋，吟讽心自足。","朅来著世网，抑抑就边幅。","人生要适情，无荣复何辱。","乾坤入望眼，容我谢羁束。","一笑白鸥前，春波动新绿。"]},{"t":"一井金","f":"曲","c":["绿阴清昼。","雨茸梅子黄时候。","华堂金兽。","香润炉烟透。","舞燕回轻袖。","歌凤翻新奏。","院静人稀，永日迟迟花漏。","一杯为寿。","笑捧处自传纤手。","钗头花有。","瑞草宜男□。","不愿金盈甃。","不愿珠盈斗。","惟愿董风，岁岁人长久。"]},{"t":"人月圆","f":"曲","c":["玄都观里桃千树，花落水空流。","凭君莫问，清泾浊渭，去马来牛。","谢公扶病，羊昙挥涕，一醉都休。","古今几度，生存华屋，零落山丘。"]},{"t":"人月圆 卜居外家东园","f":"曲","c":["重风已隔红尘断，村落更年丰。","移居要就，窗中远岫，舍后长松。","十年种木。","一年种谷，都付儿童。","老夫唯有，醉来明月，醉后清风。"]},{"t":"八声甘州","f":"曲","c":["玉京岩、龙香海南来，霓裳月中传。","有六朝图画，朝朝琼树，步步金莲。","明灭重帘画烛，几处锁婵娟。","尘暗秦王女，秋扇年年。","一枕繁华梦觉，问故家桃李，何许争妍。","便牛羊丘陇，百草动荒烟。","更谁知、昭阳旧事，似天教、通德见伶玄。","春风老、拥鬟颦黛，寂寞灯前。"]},{"t":"八声甘州","f":"曲","c":["许君祠、层崖上峥嵘，幽林入清深。","坐嵩丘少室，风烟浓澹，百态变晴阴。","山下一溪流水，不受是非侵。","寂寞悬瓢地，黄屋无心。","木杪巑岏石冢，见人闲几度，夕鼎朝鍖。","问五兵谁作，天地更生金。","百年来、神州万里，望浮云、西北泪沾襟。","青山好、一尊未尽，且共登临。"]},{"t":"八声甘州","f":"曲","c":["半仙亭篮舆雪中回，黄绸日高眠。","儿婚女嫁，奴耕婢织，共有住山缘。","梦里松腴酿熟，竹港咽冰泉。","万古霜空月，此夜清妍。","不爱朝台暮省，爱渼陂鱼艇，杜曲山田。","更昭阳遗稿，有意续伶玄。","定谁共、旧家研削，要徘徊、观顾影烛花前。","西归好、春风未老，留待明年。"]},{"t":"卜算子","f":"曲","c":["寿酒不论杯，乐奏呈歌舞。","先□中元七日生，风露凉如许。","好待月婵娟，好与姮娥语。","分付诸郎桂一枝，更觅月中兔。"]},{"t":"三奠子 同国器帅良佐仲泽置酒南阳故城","f":"曲","c":["上高城置酒，遥望舂陵。","兴与废，两虚名。","江山埋玉气，草木动威灵。","中原鹿，千年后，尽人争。","风云寤寐，鞍马生平。","钟鼎上，几书生。","军门高密策，田亩卧龙耕。","南阳道，西山色，古今情。"]},{"t":"三奠子 离南阳后作","f":"曲","c":["怅韶华流转，无计留连。","行乐地，一凄然。","笙歌寒食后，桃李恶风前。","连环玉，回文锦，两缠绵。","芳尘未远，幽意谁传。","千古恨，再生缘。","闲衾香易冷，孤枕梦难圆。","西窗雨，南楼月，夜如年。"]},{"t":"千秋岁","f":"曲","c":["玳筵晨启。","家庆堪图绘。","新杨弄暖帘栊邃。","捧觞罗补袖窄，叠板喉脆。","香云里，轻裘小帽仙翁喜。","簪玉宾亲至。","舞彩儿孙戏。","开口笑，扶头醉。","□□金穴富，岂在貂蝉贵。","只恁地，团栾共乐千秋岁。"]},{"t":"千秋岁","f":"曲","c":["双纹彩袖。","乍舞霓裳后。","香雾暖，□琼甃。","绿鬟蝉影动，小摺湘裙皱。","歌声断，彤云尽日□晴昼。","冰丝轻雪藕。","细酌鹅儿酒。","任醉拥，佳人手。","彩衣行乐事，莫惜杯如斗。","千万寿，愿如明月天边久。"]},{"t":"小重山","f":"曲","c":["醉尽春风意未阑。","缠头双凤锦、觅端端。","多情胡蝶送归鞍。","扬州梦，芍药荐金盘。","罗幌酒醒寒。","灯前朱麝浅、翠螺残。","一春心事苎衣宽。","青鸾客，楼外日三竿。"]},{"t":"小重山","f":"曲","c":["酒冷灯青夜不眠。","寸肠千缕、两相牵。","鸳鸯秋雨半池莲。","分飞苦，红泪晓风前。","天远雁翩翩。","雁来人北去、远如天。","安排心事待明年。","无情月，看待几时圆。"]},{"t":"凤凰台上忆吹箫","f":"曲","c":["宝靥留香，锦书封泪，要教恼乱愁肠。","恨镜鸾双舞，辜负欢狂。","日日东城望眼，但暮云、烟树微茫。","人何处，浓阴静院，明月幽窗。","东风万红千紫，算只有寒梅，瘦得何郎。","想淡妆无语，孤影昏黄。","好在蓝桥旧路，也便。"]},{"t":"天仙子","f":"曲","c":["水曲桥平双燕语。","密密层阴围绣幕。","梅姿不受暑光侵，携玉斧。","迎仙女。","为问乘鸾何处所。","杯酒流行无尽处。","绕膝花花前后舞。","笙歌移□下蓬壶，天付与。","凌云侣。","京兆近来眉更妩。"]},{"t":"太常引","f":"曲","c":["十年流水共行云。","相见重情亲。","沧海坐扬尘。","便疑是、前身后身。","风台月榭，舞裙歌扇，乐事几回新。","莫话洛阳春。","更谁似、金銮故人。"]},{"t":"太常引","f":"曲","c":["渚莲寂寞倚秋烟。","发幽思、入哀弦。","高树记离筵。","似昨日、邮亭道边。","白头青鬓，旧游新梦，相对两凄然。","骄马弄金鞭。","也曾是、长安少年。"]},{"t":"太常引","f":"曲","c":["东园歌管日相娱。","佳酿出兵厨。","陶写在桑榆。","便鹤到、扬州未如。","欹红浓露，绿阴清吹，长□下楼居。","高枕即吾庐。","更何待、将宫报书。"]},{"t":"太常引","f":"曲","c":["五云楼观日华东。","看天上、建章宫。","人海混渔龙。","比自古、中原更雄。","紫垣星月，禁阶灯火，朝马闹晨钟。","一梦转头空。","恍犹在、邯郸道中。"]},{"t":"太常引","f":"曲","c":["水光林影入凭阑。","花柳占春宽。","三月锦成团。","为洗尽、山阴暮寒。","玉峰诗老，为君吟啸，不醉有余欢。","人物后来看。","□画作、临流幼安。"]},{"t":"太常引","f":"曲","c":["衣冠人物渺翩翩。","天地一臞仙。","来自范公泉。","管家在、三山洞天。","一簪华发，一篇秋水，得意已忘言。","图画看他年。","与松上、幽人并传。"]},{"t":"太常引","f":"曲","c":["官街杨柳絮飞忙。","鞍马送年芳。","诗兴更教狂。","算能醉、花前几场。","满城桃李，一枝香雪，不属富家郎。","风雨没商量。","快来与、梨化洗妆。"]},{"t":"太常引","f":"曲","c":["田园松菊自由身。","鞍马老红尘。","鹅鸭恼比邻。","算未羡、凌烟写真。","花时风雨，长年哀乐，白发为谁新。","休唱渭城春。","怕忆着、西州故人。"]},{"t":"木兰花慢","f":"曲","c":["流年春梦过，记书剑，入西州。","对得意江山，十千沽酒，著处欢游。","兴亡事，天也老，尽消沈、不尽古今愁。","落日霸陵原上，野烟凝碧池头。","风声习气想风流。","终拟觅菟裘。","待射虎南山，短衣匹马，腾踏清秋。","黄尘道，何时了，料故人、应也怪迟留。","只问寒沙过雁，几番王粲登楼。"]},{"t":"木兰花慢","f":"曲","c":["渺漳流东下，流不尽，古今情。","记海上三山，云中双阙，当日南城。","黄星。","几年飞去，澹春阴、平野草青青。","冰井犹残石甃，露盘已失金茎。","风流千古短歌行。","慷慨缺壶声。","想酾酒临江，赋诗鞍马，词气纵横。","飘零。","旧家王粲，似南飞、乌鹊月三更。","笑杀西园赋客，壮怀无复平生。"]},{"t":"木兰花慢","f":"曲","c":["赋招魂九辩，一尊酒，与谁同。","对零落栖迟，兴亡离合，此意何穷。","匆匆。","百年世事，意功名、多在黑头公。","乔木萧萧故国，孤鸿澹澹长空。","门前花柳又春风。","醉眼眩青红。","问造物何心，村箫社鼓，奔走儿童。","天东。","故人好在，莫生平、豪气减元龙。","梦到琅邪台上，依然湖海沈雄。"]},{"t":"木兰花慢","f":"曲","c":["对西山摇落，又匹马，过并州。","恨秋雁年年，长空澹澹，事往情留。","白头。","几回南北，竟何人、谈笑得封侯。","愁里狂歌浊酒，梦中锦带吴钩。","岩城笳鼓动高秋。","万灶拥貔貅。","觉全晋山河，风声习气，未减风流。","风流。","故家人物，慨中宵、拊枕忆同游。","不用闻鸡起舞，且须乘月登楼。"]},{"t":"木兰花慢","f":"曲","c":["拥都六冠盖，瑶圃秀，转春晖。","怅华屋生存，丘山零落，事往人非。","追随。","旧家谁在，但千年、辽鹤去还归。","系马凤凰柱，倚弓玉女窗扉。","江头花落乱莺飞。","南望重依依。","渺天际归舟，云间汀树，水绕山围。","相期。","更当何处，算古来、相接眼中稀。","寄与兰成新赋，也应为我沾衣。"]},{"t":"木兰花慢 送取新归隐山阳兼简玉川同社","f":"曲","c":["澹西园暮景，对别酒，惜临分。","爱襆被中台，挂冠神武，谁得如君。","纷纷道途鞍马，甚当时、王粲也从军。","处处惊乌夜月，年年落雁横汾。","菟裘老计在耕耘。","风□出尘氛。","记沁北丹东，松枯石润，菊秀兰薰。","林泉竟轮先手，漫回头、惭愧玉山云。","寄谢鸡豚社客，草堂未要移文。"]},{"t":"木兰花慢 送亲家丈问梦纲","f":"曲","c":["又东门送客，侧身西望长嗟。","算万里功名，几番风雨，何限云沙。","相看已过半百，甚年年、各在一天涯。","秋气偏催过雁，疏烟细点归鸦。","旌旗未卷鬓先华。","清泪落悲笳。","问蜀道登天，锦城虽好，得似还家。","关心老来婚嫁，要与余、邻屋共烟霞。","到□征西车马，轮他杜曲桑麻。"]},{"t":"木兰花慢 游三台二首","f":"曲","c":["拥岧岧双阙，龙虎气，郁峥嵘。","想暮雨珠帘，秋香桂树，指顾台城。","台城。","为谁西望，但哀弦、凄断似平生。","只道江山如画，争教天地无情。","风云奔走十年兵。","惨澹入经营。","问对酒当歌，曹侯墓上，何用虚名。","青青。","故都乔木，怅西陵、遗恨几时平。","安得参军健笔，为君重赋芜城。"]},{"t":"木兰花慢 赠吹觱篥者张嘴儿暨乃妇田氏合曲赋此","f":"曲","c":["要新声陶写，奈声外有声何。","怆银字安清，珠绳莹滑，怨感相和。","风流故家人物，记诸郎、吹管念奴歌。","落日邯郸老树，秋风太液沧波。","十年燕市重经过。","鞍马宴鸣珂。","趁饥凤微吟，娇莺巧啭，红卷钿螺。","缠头断肠诗句，似邻舟、一听惜蹉跎。","休唱贞元旧曲，向来朝士无多。"]},{"t":"水龙吟","f":"曲","c":["汉家金粟堆空，玉花惊见天池种。","并州画角，回肠凄断，清霜晓弄。","世事浮云，白衣苍狗，知谁搏空。","恨北平老守，南山夜猎，风雨暗，貂裘重。","总道烟霄失路，意平生、依然飞动。","高城置酒，汾流澹澹，无言目送。","宝剑千金，尽堪倾倒，玻璃春瓮。","问波神剩借，横江组练，挽青丝梦。"]},{"t":"水龙吟","f":"曲","c":["玉梅含腊传香，瑞萱秀茁开三四。","莲花沈漏，熊罴占应，洛阳名世。","岁比甘罗，□□□□，累棋观志。","向修文寓直，仙楼侍宴，梁王宝，真难俪。","多少襟怀未试，暂超然、壶中游戏。","试看献策，归瞻旒□，太常勋纪。","歌遇巫云，舞回邹莞，金钗扶醉。","有阴功仙赐，丹砂十纪，寿祺全畀。"]},{"t":"水龙吟","f":"曲","c":["少年射虎名豪，等闲赤羽千夫膳。","金铃锦领，平原千骑，星流电转。","路断飞潜，雾随腾沸，长围高卷。","看川空谷静，旌旗动色，得意似，平生战。","城月迢迢鼓角，夜如何、军中高宴。","江淮草木，中原孤兔，先声自远。","盖世韩彭，可能只办，寻常鹰犬。","问元戎早晚，鸣鞭径去，解天山箭。"]},{"t":"水龙吟","f":"曲","c":["旧家八月池台，露华凉冷金波涨。","宁王玉笛，霓裳仙谱，凉州新酿。","一枕开元，梦恍犹记，华清天上。","对昆明火冷，蓬莱水浅，新亭泪，空相向。","烂漫东原此夕，夜如何、高秋空旷。","一杯径醉，凭君莫问，今来古往。","万里孤光，五湖高兴，百年清赏。","倩何人唤取，飞琼佐酒，作穿云唱。"]},{"t":"水龙吟","f":"曲","c":["素丸何处飞来，照人只是承平旧。","兵尘万里，家书三月，无言搔首。","几许光阴，几回欢聚，长教分手。","料婆娑桂树，多应笑我，憔悴似，金城柳。","不爱竹西歌吹，爱空山、玉壶清昼。","寻常梦里，膏车盘谷，拿舟枋口。","不负人生，古来惟有，中秋重九。","愿年年此夕，团栾儿女，醉山中酒。"]},{"t":"水龙吟","f":"曲","c":["百年同是行人，酒乡独有归休地。","此心安处，良辰美景，般般称遂。","力士铛头，舒州杓畔，不妨游戏。","算为狂为隐，非狂非隐，人谁解，先生意。","莫笑糊涂老眼，几回看、红轮西坠。","一杯到手，人间万事，俱然少味。","范蠡张良，尽他惊怪，陈抟贪睡。","且陶陶兀兀，今朝醉了，更明朝醉。"]},{"t":"水龙吟 东园醉后","f":"曲","c":["两年金凤城边，等闲又见东风菜。","侯门惯客，东园高宴，青云飞盖。","水上幽亭，恍然真似，兰舟同载。","望红楼翠壁，青田白鹭，谁信是，山阴塞。","郁郁林梢紫动，便安排、春来天外。","醉魂摇荡，尊前何恨，狂香浩态。","高枕吾庐，倒衣命驾，心期长在。","为使君料理，潘郎老鬓，尽花枝戴。"]},{"t":"水龙吟 同德秀游盘谷","f":"曲","c":["接云千丈层崖，古来此地风烟好。","青山得意，十分浓秀，都将倾倒。","可恨孤峰，几回空见，松筠枯槁。","自都门送别，膏车秣马，谁更问，盘中道。","我爱陂塘南畔，小川平、横冈回抱。","野麋山鹿，平生心在，长林丰草。","婢织奴耕，岁时供我，酒船花灶。","把人间万事，从头放下，只山中老。"]},{"t":"水调歌头","f":"曲","c":["山家酿初熟，取醉不论钱。","清溪留饮三日，鱼鸟亦欣然。","见说玉华诗老，袖有忘忧萱草，牛背稳于船。","铁笛久埋没，雅曲竟谁传。","坐苍苔，敧乱石，耿不眠。","长松夜半悲啸，笙鹤下遥天。","天上金堂玉室，地下石城琼壁，别有一山川。","把酒问明月，今夕是何年。"]},{"t":"水调歌头","f":"曲","c":["相思一尊酒，今日尽君欢。","长歌一写孤愤，西北望长安。","郁郁阊门轩盖，浩浩龙津车马，风雪一家寒。","钟鼓催人老，天地为谁宽。","丈夫儿，倚天剑，切云冠。","可能封塞包□，驱去复来还。","清庙千金康瓠，短褐连城双璧，行路古来难。","枯柏在南涧，留待百年看。"]},{"t":"水调歌头","f":"曲","c":["云山有宫阙，浩荡玉华秋。","何年鸾鷟同侣，清梦入真游。","细看诗中元鼎，似道区区东井，冠带事昆丘。","坏壁涴风雨，醉墨失蛟虬。","问诗仙，缘底事，愧幽州。","知音定在何许，此语为谁留。","世外青天明月，世上红尘白日，我亦压嚣湫。","一笑拂衣去，嵩顶坐垂钩。"]},{"t":"水调歌头","f":"曲","c":["空蒙玉华晓，潇洒石淙秋。","嵩高大有佳处，元在玉溪头。","翠壁丹崖千丈，古木寒滕两岸，村落带林丘。","今日好风色，可以放吾舟。","百年来，算惟有，此翁游。","山川邂逅佳客，猿鸟亦相留。","父老鸡豚乡社，儿女篮舆竹几，来往亦风流。","万事已华发，吾道付沧洲。"]},{"t":"水调歌头 与李长源游龙门","f":"曲","c":["滩声荡高壁，秋气静云林。","回头洛阳城阙，尘土一何深。","前日神光牛背，今日春风马耳，因见古人心。","一笑青山底，未受二毛侵。","问龙门，何所似，似山阴。","平生梦想佳处，留眼更登临。","我有一卮芳酒，唤取山花山鸟，伴我醉时吟。","何必丝与竹，山水有清音。"]},{"t":"水调歌头 长寿新斋","f":"曲","c":["苍烟百年木，春雨一溪花。","移居白鹿东崦，家具满樵车。","旧有黄牛十角，分得山田一曲，凉薄了生涯。","一笑顾儿女，今日是山家。","簿书丛，铃夜掣，鼓晨挝。","人生一枕春梦，辛苦趁蜂衙。","竹里蓝田山下，草阁百花潭上，千古占烟霞。","更看商于路，别有故侯瓜。"]},{"t":"水调歌头 史馆夜直","f":"曲","c":["形神自相语，咄诺汝来前。","天公生汝何意，宁独有畸偏。","万事粗疏潦倒，半世栖迟零落，甘受众人怜。","许汜卧床下，赵壹倚门边。","五车书，都不博，一囊钱。","长安自古歧路，难似上青天。","鸡黍年年乡社，桃李家家春酒，平地有神仙。","归去不归去，鼻孔欲谁穿。"]},{"t":"水调歌头 汜水故城登眺","f":"曲","c":["牛羊散平楚，落日汉家营。","龙拿虎掷何处，野蔓罥荒城。","遥想朱旗回指、万里风云奔走，惨澹五年兵。","天地入鞭箠，毛发懔威灵。","一千年，成皋路，几人经。","长河浩浩东注，不尽古今情。","谁谓麻池小竖，偶解东门长啸，取次论韩彭。","慷慨一尊酒，胸次若为平。"]},{"t":"水调歌头 缑山夜歌","f":"曲","c":["石坛洗秋露，乔木拥苍烟。","缑山七月笙鹤，曾此上宾天。","为问云间嵩少，老眼无穷今古，夜乐几人传。","宇宙一丘土，城郭又千年。","一襟风，一片月，酒尊前。","王乔为汝轰饮，留看醉时颠。","杳杳白云青嶂，荡荡银河碧落，长袖得回旋。","举手谢浮世，我是饮中仙。"]},{"t":"乐府乌衣怨","f":"曲","c":["绣佛长斋，半生枉伴蒲团过。","酒垆横卧。","一蹴虚空破。","颇笑张颠，自谓无人和。","还知么。","醉乡天大。","少个神仙我。"]},{"t":"乐府乌衣怨 旧名点绛唇","f":"曲","c":["香冷云兜，后期红线知何许。","谢家儿女。","解得辞巢语。","画栋珠帘，恨不经年住。","匆匆去。","岸花汀树。","寂寞潇湘雨。"]},{"t":"古乌夜啼 玉簪","f":"曲","c":["花中闲远风流。","一枝秋。","只枉十分清瘦不禁愁。","人欲去。","花无语。","更迟留。","记得玉人遗下玉搔头。"]},{"t":"永遇乐","f":"曲","c":["绝壁孤云，冷泉高竹，茅舍相忘。","留滞三年，相思千里，归梦风烟上。","天公老大，依然儿戏，困我世间羁鞅。","此身似、扁舟一叶，浩浩拍天风浪。","中台黄散，官仓红腐，换得尘容俗状。","枕上哦诗，梦中得句，笑了还惆怅。","可怜满镜，星星白发，中有利名千丈。","问何时、有酒如川，自歌自放。"]},{"t":"永遇乐","f":"曲","c":["龙阁先分，凤毛荣继，当世英妙。","山岳储灵，长庚应梦，还订佳辰到。","黄花浥露，碧瓦凝霜，香馥郡斋清晓。","忆当年、青云平步，共喜骤跻华要。","阴功厚德，玉函金篆，锡与世间难老。","注意方浓，分符屡请，雅志人□少。","棠阴□讼，乐府新教，正好醉山频倒。","有谁似、莱衣游戏，萱堂寿考。"]},{"t":"玉楼春","f":"七言律诗","c":["惊沙猎猎风成阵。","白雁一声霜有信。","琵琶肠断塞门秋，却望紫台知远近。","深宫桃李无人问。","旧爱玉颜今自恨。","明妃留在两眉愁，万古春山颦不尽。"]},{"t":"玉楼春","f":"七言律诗","c":["烟炉不断胜金兽。","香雾入帘波影皱。","秋堂锦度艳群仙，不惜醉□□舞袖。","繁弦脆管春风□。","娇媚如花轻似絮。","劝君须尽眼前欢，酌酒十分千百岁。"]},{"t":"玉楼春","f":"七言律诗","c":["吹台萧瑟行云暮。","一带雨声连禁树。","正当潘岳感秋时，又到杜陵怀古处。","百年同是红尘路。","行近醉乡差有趣。","坐中谁是独醒人，我醉欲眠卿可去。"]},{"t":"玉楼春","f":"曲","c":["风穿绣幕红波皱。","月照宝帘花影透。","酒凝脸醉红桃，喜入蛾眉舒翠柳。","琼英檀晕花裁就。","烟喷兽炉香满袖。","金枝元是玉皇孙，遐算愿同王母寿。"]},{"t":"玉楼春","f":"七言律诗","c":["惜花长被花枝恼，一夜落红纷不扫。","绿云为幄绣为裀，不惜春衫还藉草。","尊前莫恨春归早，来岁花开应更好。","丁宁双燕促春还，向道惜花人未老。"]},{"t":"玉楼春","f":"七言律诗","c":["秋灯连夜寒生晕。","书砚朝来龙尾润。","胧胧窗□暗移时，槭槭檐声还一阵。","黄花白酒登高近。","意外阴晴谁处问。","青山只管恋行云，忙杀晚风吹不尽。"]},{"t":"玉楼春","f":"七言古诗","c":["流光不受长绳系，乐事且须论早计。","丹成鸡犬亦登仙，运去英雄空掩涕。","花留酒笑宁无意，酒藉花香尤有味。","由来夷蹠不多争，唤向花间同一醉。","秋风茅屋浮云巘，汗漫招来嵇与阮。","尽从鹤背更腰金，独恨骑曹余手板。","酒中最好藏疏懒，深注红螺容细卷。","世间只没□闲人，举步有闲渠自远。"]},{"t":"玉楼春","f":"七言律诗","c":["人间鬓发随秋换。","天上月明秋又半。","月边仍有女乘鸾，万古与谁期汗漫。","天翁苦被闲人管。","月好却嫌秋夜短。","如何能得夜年长，月也长如今夜满。"]},{"t":"玉漏迟","f":"曲","c":["淅江归路杳。","西南仰羡，投林高鸟。","升斗微官，世累苦相萦绕。","不入麒麟画里，又不与、巢由同调。","时自笑。","虚名负我，平生吟啸。","扰扰马足车尘，被岁月无情，暗消年少。","钟鼎山林，一事几时曾了。","四壁秋虫夜语，更一点、残灯斜照。","青镜晓。","白发又添多少。"]},{"t":"石州慢","f":"曲","c":["击筑行歌，鞍马赋诗，年少豪举。","从渠里社浮沈，枉笑人间儿女。","生平王粲，而今憔悴登楼，江山信美非吾土。","天地一飞鸿，渺翩翩何许。","羁旅。","山中父老相逢，应念此行良苦。","几许虚名，误却东家鸡黍。","漫漫长路，萧萧两鬓黄尘，骑驴漫与行人语。","诗句欲成时，满西山风雨。"]},{"t":"石州慢","f":"曲","c":["儿女篮舆，田舍老盆，随意林壑。","三重屋上黄茅，赖是秋风留著。","旧家年少，也曾东抹西涂，鬓毛争信星星却。","岁暮日斜时，尽栖迟零落。","如昨。","青云飞盖追随，倾动故都城郭。","叠鼓凝笳，几处银屏珠箔。","梦中身世，只知鸡犬新丰，西园胜赏惊还觉。","霜叶晚萧萧，满疏林寒雀。"]},{"t":"好事近 冬夜有怀","f":"曲","c":["梦里十年心，情味梦回犹恶。","枕上数行清泪，被惊乌啼落。","西窗瓶水夜深寒，梅花瘦如削。","只有一枝春在，问东君留著。"]},{"t":"江月晃重山 初到嵩山时作","f":"曲","c":["塞上秋风鼓角，城头落日旌旗。","少年鞍马适相宜。","从军乐，莫问所从谁。","候骑才通蓟北，先声已动辽西。","归期犹及柳依依。","春闺月，红袖不须啼。"]},{"t":"江城子","f":"曲","c":["行云冉冉度关山。","别时难。","见时难。","怅望南风，早晚送云还。","心事情缘千万劫，无计解，玉连环。","夕阳人影小楼间。","曲阑干。","晚风寒。","料得而今，前后望归鞍。","寂寞梨花枝上雨，人不见，与谁弹。"]},{"t":"江城子","f":"曲","c":["草堂潇洒淅江头。","傍林丘。","买扁舟。","隔岸红尘，无路近沙鸥。","枕上有书尊有酒，身外事，更何求。","暮云归鸟仲宣楼。","敝貂裘。","为谁留。","千古书生，那得尽封侯。","好在半山亭下路，闻未老，去来休。"]},{"t":"江城子","f":"曲","c":["姚家池馆魏家邻。","上番春。","姓名新。","倾国倾城，为雨复为云。","水北水南无别物，金屑粉，麝香尘。","折枝图上看精神。","见来频。","画来真。","办作黄徐，无负百年身。","也待不来花下醉，嫌笑杀，洛阳人。"]},{"t":"江城子","f":"曲","c":["江山诗笔仲宣楼。","弊貂裘。","尽风流。","独恨烟花，三月出东州。","爱煞津亭亭□□，无一语，只相留。","来鸿去雁两悠悠。","别离愁。","几时休。","得似孤城，春水一沙鸥。","寄谢西湖追送客，分手地，莫回头。"]},{"t":"江城子","f":"曲","c":["醉来长袖舞鸡鸣。","短歌行。","壮心惊。","西北神州，依旧一新亭。","三十六峰长剑在，星斗气，郁峥嵘。","古来豪侠数幽并。","鬓星星。","竟何成。","他日封侯，编简为谁青。","一掬钓鱼坛上泪，风浩浩，雨冥冥。"]},{"t":"江城子","f":"曲","c":["来鸿去燕十年间。","镜中看。","各衰颜。","恰待蒙泉，东畔买青山。","梦里邻村新酿熟，携竹杖，款柴关。","人生谁得老来闲。","记清欢。","见君难。","长路悠悠，回首暮云还。","断岭不遮南望眼，时为我，一凭阑。"]},{"t":"江城子","f":"曲","c":["杏花开过雪成团。","惜朱颜。","负清欢。","只道今年，春意已阑珊。","却是地偏芳信晚，红数点，小溪湾。","碧壶香供挽春还。","一枝闲。","淡相看。","月落山空，谁与护朝寒。","传语春风留客好，莫容易，便吹残。"]},{"t":"江城子","f":"曲","c":["河堤烟树渺云沙。","七香车。","更天涯。","万古千秋，幽恨入琵琶。","想到都门南下望，金缕暗，玉钗斜。","津桥春水浸红霞。","上阳花。","落谁家。","独恨经年，培养牡丹芽。","寒雁归时凭寄语，莫容易，损容华。"]},{"t":"江城子","f":"曲","c":["二更轰饮四更回。","宴繁台。","尽邹枚。","谁念梁园，回首便成灰。","今古废兴浑一梦，凭底的，寄悲哀。","青天荡荡镜奁开。","月光来。","且徘徊。","何用东生，西没苦相催。","世事悠悠吾老矣，歌一曲，尽馀杯。"]},{"t":"江城子","f":"曲","c":["纤条袅袅雪葱笼。","翠阴重。","暖香融。","想是春工，满意与薰醲。","百畹种兰千亩蕙，都办作，一帘风。","花间人似玉芙蓉。","月明中。","下瑶宫。","只恐行云，归去卷花空。","剩著琼杯斟晓露，留少住，莫匆匆。"]},{"t":"江城子","f":"曲","c":["梅梅柳柳闹新晴。","趁清明。","凤山行。","画出灵泉，三月晋兰亭。","细马金鞍红袖客，能从我，出重城。","赏心乐事古难并。","玉双瓶。","为冠倾。","一曲清歌，休作断肠声。","头上花枝如解语，应笑我，未忘情。"]},{"t":"江城子 观别","f":"曲","c":["旗亭谁唱渭城诗。","酒盈卮。","两相思。","万古垂杨，都是折残枝。","旧见青山青似染，缘底事，澹无姿。","情缘不到木肠儿。","鬓成丝。","更须辞。","只恨芙蓉，秋露洗胭脂。","为问世间离别泪，何日是，滴休时。"]},{"t":"江城子 效花间体咏海棠","f":"曲","c":["蜀禽啼血染冰蕤。","趁花期。","占芳菲。","翠袖盈盈，凝笑弄晴晖。","比尽世间谁似得，飞燕瘦，玉环肥。","一番风雨未应稀。","怨春迟。","怕春归。","恨不高张，红锦百重围。","多载酒来连夜看，嫌化作，彩云飞。"]},{"t":"江城子 绣香奁曲","f":"曲","c":["吐尖绒缕湿胭脂。","淡红滋。","艳金丝。","画出春风，人面小桃枝。","看做香奁元未尽，挥一首，断肠诗。","仙家说有瑞云枝。","瑞云枝。","似琼儿。","向道相思，无路莫相思。","枉绣合欢花样子，何日是，合欢时。"]},{"t":"江城子 寄德新丈","f":"曲","c":["春风花柳日相催。","淅江梅。","腊前开。","开遍山桃，恰到野酴醾。","商岭东来三百里，红作阵，绿成堆。","半山亭下钓鱼台。","拂层崖。","坐苍苔。","林影湖光，佳处两三杯。","寄语玉溪王老子，因个甚，不同来。"]},{"t":"江城子 梦德新丈因及钦叔旧游","f":"曲","c":["河山亭上酒如川。","玉堂仙。","重留连。","犹恨春风，桃李负芳年。","长记莺啼花落处，歌扇后，舞衫前。","旧游风月梦相牵。","路三千。","去无缘。","灭没飞鸿，一线入秋烟。","白发故人今健否，西北望，一潸然。"]},{"t":"江城子 赋芍药杨州红","f":"曲","c":["司花著意压春魁。","绿云堆。","拥香来。","冉冉红鸾，十步一徘徊。","花到扬州佳丽种，金作屋，玉为阶。","门前腰鼓揭春雷。","倚妆台。","尽人催。","莺语丁宁，空绕百十回。","不道惜花人欲去，看直待，几时开。"]},{"t":"江城子 嵩山中作","f":"曲","c":["众人皆醉屈原醒。","笑刘伶。","酒为名。","不道刘伶，久矣笑螟蛉。","死葬糟丘珠不恶，缘底事，赴清泠。","醉乡千古一升平。","物忘情。","我忘形。","相去羲皇，不到一牛鸣。","若见三闾凭寄语，尊有酒，可同倾。"]},{"t":"江梅引","f":"曲","c":["墙头红杏粉光匀。","宋东邻。","见郎频。","肠断城南，消息未全真。","拾得杨花双泪落，江水阔，年年燕语新。","见说金娘埋恨处。","蒺藜沙，草不尽，离魂一只鸳鸯去，寂寞谁亲。","惟有因风，委露托清尘。","月下哀歌宫殿古，暮云合，遥山入翠颦。"]},{"t":"行香子","f":"曲","c":["漫漫晴波，澹澹云罗。","傍春江、是处经过。","桃花解笑，杨柳能歌。","尽百年身，千古意，两蹉跎。","酒恶无聊，诗苦成魔。","只闲情、不易消磨。","几人樵径，何处山阿。","恨夕阳迟，芳草远，落红多。"]},{"t":"西江月","f":"曲","c":["物外神仙风骨，人间富贵功名。","眉长新有秀毫生。","荡座酒光花影。","清暑玉壶昼永，少年金印身轻。","他年旌节看归荣。","笑傲五湖烟景。"]},{"t":"西江月","f":"曲","c":["骨相匿犀秀发，精神耸鹤孤高。","少年事业富伊皋。","便向中书书考。","肘后不传丹诀，眉间新长修毛。","一壶春色宴蟠桃。","□介归荣忠孝。"]},{"t":"西江月","f":"曲","c":["悬玉微风度曲，薰炉熟水留香。","相思夜夜郁金堂。","两点春山枕上。","杨柳宜春别院，杏花宋玉邻墙。","天涯春色断人肠。","更是高城晚望。"]},{"t":"阮郎归","f":"曲","c":["峥嵘秋气动千崖。","川平晚照回。","小桥流水送吟鞋。","无人觉往来。","欹乱石，坐苍苔。","一杯复一杯。","田家次第有新醅。","黄花细细开。"]},{"t":"阮郎归","f":"曲","c":["谩郎活计拙于鸠。","闲中又过秋。","枕书眠了却登楼。","贫来颇自由。","书咄咄，赋休休。","西窗晚更幽。","诗家贫杀也风流。","家人不用愁。"]},{"t":"阮郎归 为李长源赋","f":"曲","c":["帝城西下望西山。","城居岁又残。","万家风雪一家寒。","青灯语夜阑。","人鲊瓮，鬼门关。","无穷人往还。","求官莫要近长安。","长安行路难。"]},{"t":"阮郎归 独木桥体","f":"曲","c":["别郎容易见郎难。","千山复万山。","杨花帘幕晚风间。","愁眉澹澹山。","光禄塞，雁门关。","望夫元有山。","当时只合锁雕鞍。","山头不放山。"]},{"t":"声声慢","f":"曲","c":["香浮椒柏，暖入酴酥，瑞气晓生帘幕。","绛阙真人，来自五云楼阁。","青霄路歧游偏，挂冠归、水晶□□。","逍散处，有壶中日月，放□龟鹤。","好是朱颜难□，嬉游处不减，少年行乐。","正好寻春，莫负燕期莺约。","沈沈洞天向晚，按宫商、重调音乐。","愿岁岁，听新声、笙歌院落。"]},{"t":"声声慢 内乡淅江上作","f":"曲","c":["林间鸡犬，江上村墟，扁舟处处经过。","袖里新诗，买断古木苍波。","山中一花一草，也留教、老子婆娑。","任人笑，甚风云气少，儿女情多。","不待求田问舍。","被朝吟暮醉，惯得蹉跎。","百尺高楼，更问平地如何。","朝来斜风细雨，喜红尘、不到渔蓑。","一尊酒，唤元龙、来听浩歌。"]},{"t":"折丹桂","f":"曲","c":["秋风秋露清秋节。","秋雨过，秋香初发。","二仙生日好秋天，气节与、秋霜争裂。","秋宵开宴群仙列。","秋娘唱、秋云低遏。","寿杯双劝祝千秋，镇长似、中秋皓月。"]},{"t":"沁园春","f":"曲","c":["再见新正，去岁逐贫，今年逐穷。","算公田二顷，谁如元亮，吴牛十角，未比龟蒙。","面目堪憎，语言无味，五鬼行来此病同。","齑盐里，似扬雄寂寞，韩愈龙钟。","何人炮凤烹龙。","且莫笑、先生饭甑空。","便看来朝镜，都无勋业，拈将诗笔，犹有神通。","花柳横陈，江山呈露，尽入经营惨澹中。","闲身在，看薄批明月，细切清风。"]},{"t":"沁园春 除夕二首","f":"曲","c":["腐朽神奇，梦幻吞侵，朝昏变迁。","怅残灯旧岁，鸡声竞早，春风归兴，雁影相先。","南渡崩奔，东屯留滞，世事悠悠白发边。","虚名误，遍人间浪走，恰到求田。","青红花柳争妍。","意醉眼、天公也放颠。","更云雷怒卷，颓波一注，冰霜冷看，老桧千年。","园令家居，陶潜官罢，无酒令人意缺然。","从教去，付青山枕上，明月尊前。"]},{"t":"诉衷情令","f":"曲","c":["行斋活计五车书。","真欲釜生鱼。","天公也相料理，新得掌中珠。","看骥子，弄鹓雏。","最怜渠。","青衫竹马，后日迎门，好个高闾。"]},{"t":"诉衷情令","f":"曲","c":["升平责望富民侯。","愁损抱官囚。","自家本元烦恼，闹处要钻头。","山崦寺，水心楼。","去来休。","醉扶归路，鼓吹鸣蛙，部曲黄牛。"]},{"t":"诉衷情令","f":"曲","c":["万人如海一身藏。","随例大家忙。","东华软红尘土，俗损谢三郎。","兰若寺，玉溪庄。","两茅堂。","鸡豚乡社，鹅鸭比邻，好个嵩阳。"]},{"t":"定风波","f":"曲","c":["离合悲欢酒一壶。","白头红颊醉相扶。","见说德星今又聚。","何处。","范家亭上会周吴。","造物有情留此老。","人道。","洛西清燕百年无。","六客不争前与后。","好□。","龙眠老笔画新图。"]},{"t":"定风波","f":"曲","c":["熊耳东原汉故宫。","登临犹记往年同。","底事爱君诗句好。","解道。","河山浮动酒杯中。","存没悠悠三十载。","谁会。","白头孤客坐书空。","黄土英雄何处在。","须待。","醉寻萧寺哭春风。"]},{"t":"定风波","f":"曲","c":["白水青田万顷秋。","风烟平楚散羊牛。","莫放相公黄阁去。","留取。","笑谈尊俎也风流。","华表仙人人不识。","今夕。","鹿车也到百花洲。","好把襄江都酿酒，为寿。","寿星光彩动南州。"]},{"t":"定风波","f":"曲","c":["小□香来醉梦中。","梦回幽赏惜匆匆。","只道南枝开未半。","谁唤。","等闲都逐晚云空。","潇洒小溪新雪后。","唯有。","萧萧霜叶卧残红。","几欲问花应有恨。","休问。","争教不肯嫁春风。"]},{"t":"定风波","f":"曲","c":["何处如今更有诗。","争教风鬓见横枝。","诗到梅边谁最似。","除是。","玉颜寂寞酒清时。","为向云间公子道。","闻早。","安排欢赏惜幽姿。","十日留花花未遇。","容我。","醉围红袖写鸟丝。"]},{"t":"定风波 儿子中中百晬日作","f":"曲","c":["五色莲盆玉雪肌。","青搽红抹总相宜。","且道生男何足爱。","争奈。","隆颅犀角眼中稀。","六十平头年运好。","投老。","大儿都解把锄犁。","醉眼看花驴背上。","豪放。","阿龄扶路阿中随。"]},{"t":"念奴娇","f":"曲","c":["小山招饮，恨还丹、不至人间豪杰。","南渡衣冠多励集，萧洒兰亭三月。","陶冶襟灵，留连光景，觞咏今无复。","黄垆虽近，老怀空感存殁。","谁办八表神游，古来登览，此日俱湮没。","天景云光摇醉眼，兴在珠宫瑶阙。","布席崧台，脱巾石壁，散我萧萧发。","短歌悲慨，海涛响振林樾。"]},{"t":"念奴娇","f":"曲","c":["金神按节，先下弦、一夕分明秋色。","银汉光浮天绀滑，星彩遥瞻南极。","阿母分桃，桂娥馈药，称庆于今夕。","解颜微笑，卷帘初识姑射。","翛翛沆瀣横空，待高承仙掌，□调精液。","金鼎丸光十丈，一咽龟龄千亿。","绿发堂中，彩衣庭下，瑞绕仙□宅。","机云欢舞，雅歌声动瑶席。"]},{"t":"念奴娇","f":"曲","c":["云间太华，笑苍然尘世，真成何物。","玉井莲开花十丈，独立苍龙绝壁。","九点齐州，一杯沧海，半落天山雪。","中原逐鹿，定知谁是雄杰。","我梦黄鹤移书，洪崖招隐，逸兴尊中发。","箭筈天门飞不到，落日旌旗明灭。","华屋生存，丘山零落，几换青青发。","人间休问，浩歌且醉明月。"]},{"t":"念奴娇","f":"曲","c":["一年好处，是西风、乡出东篱寒菊。","蝶舞蜂狂谁便道，今夕清香不足。","令尹风流，年年春事，小雨一犁新绿。","园扉人静，抱琴时弄幽独。","闻道野老相呼，幽寻仙洞，乞与长生箓。","鹤发单颜须待得，王母蟠桃初熟。","只恐相将，日边催去，凤沼鸣环玉。","娉婷一笑，为渠且尽醽醁。"]},{"t":"念奴娇","f":"曲","c":["严陵台畔，枕清江、仙府□重金碧。","玉轴牙签三万卷，环列人间东壁。","名世高风，□遵遗训，继踵皆豪逸。","联翩簪组，满门辉映金璧。","谈笑稳步青霄，扶摇九万里，垂天横翼。","大纛高牙三授钺，凛凛威行南国。","月满三山，春回八部，宴寝凝香席。","祈公难老，凤池长醉春色。"]},{"t":"画堂春","f":"曲","c":["月娥来自广寒宫。","步摇环佩丁东。","戏鸾双舞驾天风。","云满虚空。","一剪玉梅花小，九霞琼醴杯浓。","凤箫千载莫匆匆。","且醉壶中。"]},{"t":"采桑子","f":"曲","c":["儿家门户重掩，郎住墙东。","枉破春工。","万紫千红一夜风。","伯劳分背西飞燕，何日相逢。","纵得相逢。","海阔天高处处同。"]},{"t":"金菊对芙蓉","f":"曲","c":["银烛摇红，兽烟喷翠，正小春时候，爱日和融。","玉□法日生英杰，天付与、道骨仙风。","文章冠世，词倾峡水，笔扫秋虹。","更□福寿无穷。","喜克家有子，孙又英雄。","算人问何物，可以形容。","除非后夜团圆月，年年共、皎洁相同。","捧卮□寿，殷勤□□，满泛金钟。"]},{"t":"青玉案","f":"曲","c":["虾须帘上铜钩小。","玳瑁□，轻寒绕。","红叶微香侵语笑。","金钗珠履，凤箫鼓，疑是蓬莱岛。","萱堂日日春生貌。","嫩绿依然鬓边好。","赋□修龄应不少。","年年长见，画堂□宴，楼外青袍草。"]},{"t":"青玉案","f":"曲","c":["落红吹满沙头路。","似总为、春将去。","花落花开春几度。","多情惟有，画梁双燕，知道春归处。","镜中冉冉韶华暮。","欲写幽怀恨无句。","九十花期能几许。","一卮芳酒，一襟清泪，寂寞西窗雨。"]},{"t":"青玉案","f":"曲","c":["熙春台下花无数。","红紫映桃溪路。","蝶往蜂来知几许。","翠筠亭外，绿杨堤畔，时听娇莺语。","绮筵罗列开尊俎。","总是神仙侣。","竟举笙歌驰玉醑。","介公眉寿，年年此日，长与花为主。"]},{"t":"青玉案 代赠钦叔所亲乐府郓生","f":"曲","c":["苎萝坊里青骢驻。","爱鹦鹉、垂帘语。","一捻娇春能几许。","寒梅欲动，小桃初放，恰是关心处。","西城流水东城雨。","绿叶成阴惯相误。","只恐韶华容易去。","一声金缕，一卮芳酒，且为花枝住。"]},{"t":"临江仙","f":"曲","c":["自笑此身无定在，风蓬易转孤根。","羡君归意满离尊。","眼中茅屋兴，稚子已迎门。","回首对床灯火处，万山深裹孤村。","故人天末赋招魂。","新诗凭寄取，憔悴不须论。"]},{"t":"临江仙","f":"曲","c":["连日湖亭风色好，今朝赏遍东城。","主人留客过清明。","小桃如欲语，杨柳更多情。","为爱暮云芳草句，一杯聊听新声。","水流花落叹浮生。","故园春更晚，时节已啼莺。"]},{"t":"临江仙","f":"曲","c":["试上古城城上望，水光天影相涵。","都将形胜入高谈。","河山君与我，独恨少髯参。","造化戏人儿女剧，狙公暮四朝三。","百年都合付薰酣。","人家谁有酒，吾与典春衫。"]},{"t":"临江仙","f":"曲","c":["荷叶荷花何处好，大明湖上新秋。","红妆翠盖木兰舟。","江山如画里，人物更风流。","千里故人千里月，三年孤负欢游。","一尊白酒寄离愁。","殷勤桥下水、几日到东州。"]},{"t":"临江仙","f":"曲","c":["醉眼纷纷桃李过，雄蜂雌蝶同时。","一生心事杏花诗。","小桥春寂寞，风雨鬓成丝。","天上鸾胶寻不得，直教吹散胭脂。","月明千里少姨祠。","山中开较晚，应有北阴枝。"]},{"t":"临江仙","f":"曲","c":["世事悠悠天不管，春风花柳争妍。","人家寒食尽藏烟。","不知何处火，来就客心然。","千里故乡千里梦，高城泪眼遥天。","时光流转雁飞边。","今春看又过，何日是归年。"]},{"t":"临江仙","f":"曲","c":["谁唤提壶沽美酒，浮生多负欢游。","窗明窗暗百年休。","凉风催雁过，春水带花流。","仰视浮云空自诳，往还岁月悠悠。","三山那有凤麟洲。","一杯齐物论，千古醉乡侯。"]},{"t":"临江仙","f":"曲","c":["明月清风无尽藏，平生老子南楼。","阎闾谈笑说封侯。","谁能知许事，一笑去来休。","旧见辋川图画里，十年孤负欢游。","百金早晚得菟裘。","与君成二老，来往亦风流。"]},{"t":"临江仙","f":"曲","c":["一段江山英秀气，风流天上星郎。","烟花故国五云乡。","只知心事在，争问鬓毛苍。","千古西陵歌舞地，兴来忘却悲凉。","相逢一醉莫停觞。","东山看老去，湖海永相忘。"]},{"t":"临江仙","f":"曲","c":["清晓千门开寿宴，绮罗香绕芳丛。","红娇绿软媚芳丛。","绣屏金翡翠，锦帐玉芙蓉。","珠履争持添岁酒，葡萄酒饮金钟。","人生福寿古难逢。","好将家庆事，□□□□□。"]},{"t":"临江仙","f":"曲","c":["杨柳池塘桃李径，华堂寿宴初开。","围春翠幕舞风回。","东山携妓女，北海整尊罍。","玉笋轻敲红象板，金荷潋滟传杯。","笙歌缭绕宴春台。","华山闲日月，□野醉蓬莱。"]},{"t":"临江仙","f":"曲","c":["世故迫人无好况，酒杯今日初拈。","昆阳城下酹苍蟾。","乾坤悲永夜，笳鼓觉秋严。","梦寐玉溪溪上路，竹枝斜出青帘。","故人白发未应添。","浩歌风露下，相望一掀髯。"]},{"t":"临江仙 与钦叔饮二首 其一","f":"曲","c":["邂逅一尊文字饮，春风为洗愁颜。","花枝入鬓笑诗班。","登临千古意，天澹夕阳间。","南去北来行老矣，人生茅屋三间。","何人得似谢东山。","紫箫明月底，高竹倚风鬟。"]},{"t":"临江仙 内乡北山","f":"曲","c":["夏馆秋林山水窟，家家林影湖光。","三年间为一官忙。","簿书愁里过，笋蕨梦中香。","父老书来招我隐，临流已盖茅堂。","白头兄弟共论量。","山田寻二顷，他日作桐乡。"]},{"t":"临江仙 内乡寄嵩前故人","f":"曲","c":["昨夜半山亭下醉，洼尊今日留题。","放船直到淅江西。","冰壶天上下，云锦树高低。","世上红尘争白日，山中太古熙熙。","外人初到故应迷。","桃花三百里，浑是武陵溪。"]},{"t":"临江仙 对花怀洛阳旧游","f":"曲","c":["紫玉双华相照映，锦儿仍是琼儿。","天边谁与慰相思。","洗妆无别物，只有断肠诗。","水北水南浑一梦，眼中红袖乌丝。","春风同是可怜枝。","争教歌酒兴，不似洛阳时。"]},{"t":"临江仙 自洛阳往孟津道中作","f":"曲","c":["今古北邙山下路，黄尘老尽英雄。","人生长恨水长东。","幽怀谁共语，远目送归鸿。","盖世功名将底用，从前错怨天公。","浩歌一曲酒千钟。","男儿行处是，未要论穷通。"]},{"t":"临江仙 张光甫家儿子咬驴","f":"曲","c":["膝上添丁郎小小，鹓雏彩鹤初匀。","书堂合与孟家邻。","诵诗琴解□，论学墨沾唇。","头玉峣峣眉刷翠，更将秋水为神。","看花留待百年春。","金鞍南陌上，惊动洛阳人。"]},{"t":"临江仙 留别郝和之","f":"曲","c":["昨日故人留我醉，今朝送客西归。","古来相接眼中稀。","青衿同舍乐，白首故山违。","九万里风安税驾，云鹏悔不卑飞。","回头四十七年非。","何因松竹底，茅屋老相依。"]},{"t":"临江仙 寄德新丈","f":"曲","c":["自笑此身无定在，北州又复南州。","买田何日遂归休。","向来元落落，此去亦悠悠。","赤日黄尘三百里，嵩丘几度登楼。","故人多在玉溪头。","清泉明月晓，高树乱蝉秋。"]},{"t":"临江仙 赠仲经女子楚楚","f":"曲","c":["阿楚新来都六岁，掌中一捻娇春。","诗中有笔画难真。","芝香云作朵，鱼细锦为鳞。","旧说张门多静女，更和灵照情亲。","夸谈体遣孔兄瞋。","异时看小妹，林下谢夫人。"]},{"t":"临江仙 赠答飞卿弟","f":"曲","c":["壮岁论交今晚岁，只君知我平生。","六年相望若为情。","吕安思叔夜，残月配长庚。","济上买田堪共隐，嵩丘朝暮阴晴。","紫云仙季白云兄。","风流成二老，林下看升平。"]},{"t":"摊破南乡子","f":"曲","c":["朱麝掌中香。","可怜儿、初浴兰汤。","灵椿未老丹枝秀，东邻西舍，排家助喜，沽酒牵羊。","天与读书郎。","便安排、富贵文章。","高门自有容车日，明年且看，青衫竹马，雁雁成行。"]},{"t":"摊破南乡子","f":"曲","c":["无物慰蹉跎。","占一丘、一壑婆娑。","闲来点检平生事，天南地北，几多尘土，何限风波。","花坞与松坡。","尽先生、少小经过。","老来诗酒犹堪任，家山在眼，亲朋满坐，不醉如何。"]},{"t":"摊破南乡子","f":"曲","c":["朝镜惜蹉跎。","一年年、来日无多。","无情六合乾坤里，颠鸾倒凤，撑霆裂月，直被消磨。","世事饱经过。","算都输、畅饮高歌。","天公不禁人间酒，良辰美景，赏心乐事，不醉如何。"]},{"t":"南乡子","f":"曲","c":["一雨浣年芳。","燕燕莺莺满洛阳。","梨雪渐空桃李过，风光。","恰到风流睡海棠。","何处最难忘。","杨柳高楼近苑墙。","唤取分司狂御史，何妨。","暂醉佳人锦瑟傍。"]},{"t":"南乡子","f":"曲","c":["梅雪弄芳馨。","线日迎长□□蓂。","争看琴堂称贺处，娉婷。","满捧霞觞灿鲤庭。","鹤算更龟龄。","八十仙翁醉复醒。","好倩洛阳驰誉手，丹青。","画与人间作寿星。"]},{"t":"南乡子","f":"曲","c":["衰思怯登楼。","百感中来不自由。","天意时情谁解得，悠悠。","一片黄云画角秋。","汾水绕城流。","流尽朱颜到白头。","万事且休论一醉，都休。","前日黄花蝶已愁。"]},{"t":"南乡子","f":"曲","c":["烟草人西州。","暮雨千山独倚楼。","不似秦东亭上饮，风流。","翠袖春风两玉舟。","事去重回头。","却是多情不自由。","为向河阳桃李道，休休。","青鬓能堪几度愁。"]},{"t":"南乡子","f":"曲","c":["少日负虚名。","问舍求田意未平。","南去北来今老矣，何成。","一线微官误半生。","孤影伴残灯。","万里灯前骨肉情。","短发抓来看欲尽，天明。","能是青青得几茎。"]},{"t":"南乡子","f":"曲","c":["幽意曲中传。","总是才情得处偏。","唱到断肠声欲断，还连。","一串骊珠个个圆。","画扇绮罗筵。","韩马风流在眼前。","坐上有人持酒听，凄然。","梦里梁园又一年。"]},{"t":"南乡子","f":"曲","c":["风雨送春忙，烂醉花时得几场。","枝上桃花吹尽也，残芳。","一片春风一片香。","少日为花狂，老去逢春只自伤。","回首十年欢笑处，难忘。","一曲悲歌泪数行。"]},{"t":"南柯子","f":"曲","c":["画扇香微远，宫螺意自浓。","杏园憔悴五更风。","不道六朝琼树卷春空。","蝶近花疑笑，犀灵月易通。","襄王云雨梦魂中。","曾见芙蓉裙衩几多红。"]},{"t":"南柯子","f":"曲","c":["粉澹梨花瘦，香寒桂叶颦。","画帘双燕旧家春。","曾是玉箫声里断肠人。","澹澹催诗雨，迟迟入梦云。","武陵流水隔红尘。","只怕翠鸾消息未全真。"]},{"t":"南柯子 济川寿席","f":"曲","c":["阀阅真王后，衣冠上客中。","路人遥识紫髯翁。","争信旧来文赋动南宫。","得婿攀龙贵，生男射虎雄。","寿筵休放酒尊空。","且道几人全福与君同。"]},{"t":"南歌子","f":"曲","c":["人日过三日，元宵便五宵。","共言今日好生朝。","皓月光辉，香动玉梅梢。","谢女工飞絮，周郎待小乔。","年年灯下醉金蕉。","鬓影苍球，金缕细鹅毛。"]},{"t":"南歌子 冬景","f":"曲","c":["暖日烘晴昼，轻寒护晓霜。","小春庭院绕天香。","仙佩珊珊，来自五云乡。","庭下芝兰秀，壶中日月长。","要看鬓绿与瞳方。","一笑人间，千岁饮淋浪。"]},{"t":"品令","f":"曲","c":["西斋向晓。","窗影动、人声悄。","梦中行处，数枝临水，幽花相照。","把酒长歌，犹记竹间啼鸟。","风流易老。","更常被、闲愁恼。","年年春事，大都探得，欢游多少。","一夜狂风，又是海棠过了。"]},{"t":"思仙会 效杨吏部礼","f":"曲","c":["人无百年人，枉作千年计。","傀儡棚头，看过几场兴废。","朱颜易改，可惜欢娱地。","劝君酒，唱君歌，为君醉。","沧溟一叶，正在横流际。","阮籍途穷，啼得血流何济。","天公老大，不管人间世。","莫莫休休。","莫问甚底。"]},{"t":"柳梢青","f":"曲","c":["玉嫩红娇。","□花如月，斜袅金翘。","楚女腰肢，小乔风韵，难比妖娆。","当年约住蓝桥。","便回首仙凡路遥。","一曲清歌，千钟美酒，同庆生朝。"]},{"t":"洞仙歌","f":"曲","c":["黄尘鬓发，六月长安道。","羞向清溪照枯槁。","似山中远志，漫出山来，成个甚，只是人间小草。","升平十二策，丞相封侯，说与高人应笑倒。","对清风明月，展放眉头长恁地，大醉高歌也好。","待都把功名付时流，只求个天公，放教空老。"]},{"t":"洞仙歌","f":"曲","c":["千崖滴翠，正秋高时候。","橘绿橙黄又重九。","有蓬壶仙子，赤鲤来游，风云会、施展经纶妙手。","去年称寿处，北斗天浆，今夜天将挹南斗。","听笙歌云里奏。","月荡琼楼，瑶台上、拥出姮娥□酒。","待脚踏、层云倒天河，尽倾向霞觞，与君为寿。"]},{"t":"洞仙歌","f":"曲","c":["青钱白璧，自买愁肠绕。","更恨欢狂负年少。","记阳关图上，尊酒流连，儿女泪，输与闲人坐钓。","茂陵多病后，懒尽琴心，无复求凰与同调。","似清风古殿，风动幡摇晴昼永，惟有龛灯静照。","看胡蝶飞来澹无情，问墙角茙葵，为谁凝笑。"]},{"t":"点绛唇","f":"曲","c":["梦里梁园，暖风迟日熏罗绮。","满城桃李。","车马红尘起。","客枕三年，故国云千里。","更残未。","夜寒如水。","茅屋清霜底。"]},{"t":"点绛唇","f":"曲","c":["帘卷荷香，绮罗人在薰风里。","谢庭家世。","来作闺门瑞。","象服鱼轩，占尽人间贵。","应难比。","蟠桃花底。","一醉三千岁。"]},{"t":"点绛唇","f":"曲","c":["十六芳年，锦儿娇小琼儿秀。","海棠红皱。","恰到愁时候。","天上歌声，未省人间有。","休回首。","渭城烟柳。","肠断离亭酒。"]},{"t":"点绛唇","f":"曲","c":["国艳天香，一丛百朵开来半。","燕忙莺乱。","要结寻芳伴。","买断春风，醉倒应须拚。","清尊满。","谢家池馆。","岁岁年年看。"]},{"t":"点绛唇","f":"曲","c":["痛负花朝，半春犹在长安道。","故园春早。","红雨深芳草。","愁里花开，愁里花空老。","西归好。","一尊倾倒。","乞与花枝恼。"]},{"t":"点绛唇","f":"曲","c":["连夜春寒，夜来好梦衾暖。","寺楼钟断。","却恨更筹短。","一点闲情，苦被离愁管。","西城晚。","雁飞天远。","草色归心满。"]},{"t":"点绛唇","f":"曲","c":["把酒留春，醉扶红袖花前倒。","落花风扫。","红雨深芳草。","又恨春迟，又恨春归早。","花应笑。","惜春人老。","枉被春风恼。"]},{"t":"点绛唇","f":"曲","c":["玉宇沈沈，绿窗珠户还相□。","碧池回绕。","全似蓬莱岛。","今夕笙歌，两两云鬟小。","炉烟袅。","寿觞倾倒。","长愿朱颜好。"]},{"t":"点绛唇","f":"曲","c":["红袖凭阑，画图曾见崔徽半。","吹箫谁伴。","白地肝肠断。","未了尘缘，可道欢缘短。","云山乱。","武陵溪岸。","几误莺声唤。"]},{"t":"点绛唇","f":"曲","c":["玉蕊轻明，洗妆偏费春风手。","韵香襟袖。","别是闺房秀。","锦瑟华年，□醉东园酒。","西归后。","旧家花柳。","谁得何郎瘦。"]},{"t":"点绛唇 长安中作","f":"曲","c":["沙际春归，绿窗犹唱留春住。","问春何处。","花落莺无语。","渺渺吟怀，漠漠烟中树。","西楼暮。","一帘疏雨。","梦里寻春去。"]},{"t":"点绛唇 宜男","f":"曲","c":["绿澹香浓，旧曾百子池边种。","碧筵孤耸。","惊堕钗头凤。","檀粉轻拈，若怕蜂腰重。","天花供。","一枝谁送。","寂寞南华梦。"]},{"t":"点绛唇 青梅永宁时作","f":"曲","c":["玉叶璁珑，素妆不趁宫黄媚。","谢家风致。","最得春风意。","手把青枝，忆得斜横髻。","西州泪。","玉觞无味。","强为清香醉。"]},{"t":"点绛唇 寄李辅之","f":"曲","c":["生死论交，有情何似无情好。","满前花草。","更觉今年老。","塞上春迟，湖上春风早。","东州道。","几时飞到。","烂醉红云岛。"]},{"t":"秋色横空","f":"曲","c":["松液香凝。","澹幽姿一洗，若下宜城。","甘腴小苦中山赋，千古齿颊春生。","灯花喜，缸面清。","爱竹港、冰泉落枕声。","恰值刘纲夫妇、此日丹成。","云峰翠殿画屏。","更晴楼水阁，树拥烟横。","留连光景中年，要歌管淘写襟灵。","人间世，身外名。","笑朝马晨钟梦易惊。","且留看神仙，白昼地行。"]},{"t":"贺新郎 箜篌曲为良佑所亲赋","f":"曲","c":["赴节金钗促。","爱弦间、泠泠细语，非琴非筑。","别鹤离莺云千里，风雨孤猿夜哭。","只雌蝶、雄蜂同宿。","汀树诗成归舟远，认宫眉、隐隐春山绿。","歌宛转，泪盈掬。","吴儿越女皆冰玉。","恨不及、徘徊星汉，流光相属。","破镜何年清辉满，寂寞佳人空谷。","人世事、寻常翻覆。","入塞新声愁未了，更伤心、听得开元曲。","呼羯鼓，醉红烛。"]},{"t":"桃园忆故人 代赠良佐所亲","f":"曲","c":["楚云不似阳台旧，只是无心出岫。","竹外天寒翠袖。","寂寞啼妆瘦。","弦声宛转春风手。","殢得行人病酒。","明日西城回首。","肠断江南柳。"]},{"t":"浣溪沙","f":"曲","c":["琼压为浆作卮，使君真是吏民师。","碧桃仙酎饮乡期。","五马旌□浮喜色，南溪风月要新诗。","缓趋□□及瑶池。"]},{"t":"浣溪沙","f":"七言古诗","c":["芳草垂杨长乐坡。","两行红粉一声歌。","淋漓襟袖酒痕多。","梦里翠翘惊堕枕，愁边罗袜见凌波。","春寒春瘦夜如何。"]},{"t":"浣溪沙","f":"七言古诗","c":["梦里还惊岁月遒。","鲤鱼风退不胜秋。","人生虽异水同流。","酒力有神工驻景，丹房无药可烧愁。","陶陶兀兀老时休。"]},{"t":"浣溪沙","f":"七言古诗","c":["梦绕桃源寂寞回。","春残滋味似秋情。","多情翻恨酒为媒。","数点雨声风约住，一帘花影月移来。","小阑幽径独徘徊。"]},{"t":"浣溪沙","f":"七言古诗","c":["秋气尖寒酒易消。","秋怀元酒更无聊。","夕阳人影卧平桥。","菊就雨前都烂熳，柳丛霜罢便萧条。","夜来风色似今朝。"]},{"t":"浣溪沙","f":"七言古诗","c":["百折清泉绕舍鸣。","隔年杨柳绿阴成。","藕花多处一舟轻。","行处自由皆乐事，得来无用是虚名。","等闲荣辱不须惊。"]},{"t":"浣溪沙","f":"七言古诗","c":["芍药初开百步香，小阑幽径隔长廊。","好花都属富家郎。","此乐莫教儿辈觉，老夫聊发少年狂。","高烧银烛照红妆。"]},{"t":"浣溪沙","f":"七言古诗","c":["为爱刘郎驻玉华。","暗将心事许烟霞。","石田茅屋老生涯。","铁笛不须从二草，头巾长拟挂三花。","他年人说漫郎家。"]},{"t":"浣溪沙","f":"七言古诗","c":["湖上春风散客愁。","芳洲烟景记曾游。","人家浑似玉溪头。","杨柳青旗酤酒市，桃花流水钓鱼舟。","红尘鞍马几时休。"]},{"t":"浣溪沙","f":"七言古诗","c":["绿绮尘埃试拂弦。","今人谁与子争先。","相逢尊酒合留连。","金马玉堂梁苑客，岸花汀草绣江船。","旧游回首又三年。"]},{"t":"浣溪沙","f":"七言古诗","c":["锦带吴钩万里行。","青云人物旧知名。","百壶春酒过清明。","渺渺荒陂冰井路，青青杨柳玉关情。","斜阳无语下西陵。"]},{"t":"浣溪沙","f":"七言古诗","c":["借守陪京尺五天。","碧油旆里地行仙。","政成多暇且同欢。","梅雨□江□□润，薰风高阁水晶寒。","长鲸饮罢玉壶乾。"]},{"t":"浣溪沙","f":"七言古诗","c":["修竹移阴未出墙。","好风斜绰露荷香。","壶中六月也清凉。","不放灵椿仙客□，要有丹桂满林芳。","天教光景为人长。"]},{"t":"浣溪沙","f":"曲","c":["一片青天棹过。","小舟无地受风波。","渔歌浑是太平歌。","乡社年丰寻酒易，陂塘春暖得鱼多。","百年闲过又如何。"]},{"t":"浣溪沙","f":"七言古诗","c":["一片烟蓑一叶舟。","梦中身世是沧洲。","鲤鱼风退不胜秋。","秋月春风行处有，苍苔浊酒醉时休。","人生虽异水同流。"]},{"t":"浣溪沙","f":"七言古诗","c":["日射云间五色芝。","鸳鸯宫瓦碧参差。","西山晴雪入新诗。","焦土已经三月火，残花犹发万年枝。","他年江令独来时。"]},{"t":"浣溪沙","f":"七言古诗","c":["画出清明二月天。","山城三月只萧然。","闲门日日枕书眠。","川下杏花浑欲雪，山中杨柳不成烟。","春风回首又明年。"]},{"t":"浣溪沙 史院得告归西山","f":"七言古诗","c":["万顷风烟入酒壶。","西山归去一狂夫。","皇家结网未曾疏。","情性本宜闲处著，文章自忖用时无。","醉来聊为鼓咙胡。"]},{"t":"浣溪沙 外家种德堂","f":"七言古诗","c":["墙外桑麻雨露深。","堂前桃李有新阴。","高门因见古人心。","三世读书无白屋，一经教子胜黄金。","小雏先与唤琼林。"]},{"t":"浣溪沙 别纬文张兄","f":"七言古诗","c":["欹枕寒鸦处处听。","花前雁后数归程。","小红灯影闹春城。","两地相望今夜月，一尊不尽故人情。","老怀牢落向谁倾。"]},{"t":"浣溪沙 宿孟津官舍","f":"七言古诗","c":["一夜春寒满下厅。","独眠人起候明星。","娟娟山月入疏棂。","万古风云双短鬓，百年身世几长亭。","浩歌聊且慰飘零。"]},{"t":"浪淘沙令","f":"曲","c":["杨柳日三眠。","桃李争妍。","千金谁许占芳年。","买得闲愁无处著，却恨春偏。","流水武陵源。","梦引愁牵。","东风归兴雁翩翩。","试问西窗前夜月，几度先圆。"]},{"t":"浪淘沙令","f":"曲","c":["云外凤凰箫。","天上星桥。","相思魂断欲谁招。","瘦杀三山亭畔柳，不似宫腰。","长日篆烟消。","睡过花朝。","红蔷薇架碧芭蕉。","雌蝶雄蜂天不管，各自无聊。"]},{"t":"浪淘沙令","f":"曲","c":["金翠画屏山。","万髻千鬟。","桃源楼阁五云间。","恨杀芙蓉城下客，不借青鸾。","风雨杏花残。","芳意都阑。","一灯孤影小窗间。","绣被熏来香欲尽，只是春寒。"]},{"t":"浪淘沙令","f":"曲","c":["春瘦怯春衣。","春思低迷。","雨声偏与睡相宜。","懊恼离愁寻殢酒，已被愁知。","烟树望中低，水绕山围。","丁宁双燕话心期。","昨夜狂风花在否，明日郎归。"]},{"t":"浪淘沙令","f":"曲","c":["诗句入冥搜。","欲写还休。","人间情是阿谁留。","千丈游丝不落地，风外悠悠。","烟雨晚山稠。","人倚西楼。","衡阳归雁满沙头。","一种江城寒夜客，一种春愁。"]},{"t":"浪淘沙令","f":"曲","c":["芳树翠烟重。","残角疏钟。","落花飞絮一帘风。","可惜河阳桃李月，弹指春空。","翡翠合欢笼。","相望西东。","锁窗幽梦几回同。","料得朱门歌舞罢，满袖啼红。"]},{"t":"浪淘沙令","f":"曲","c":["何处挽春还。","华屋金盘。","一枝红雪入惊看。","总为西园风露早，特地高闲。","寂寞曲阑干。","高髻云鬟。","绿罗衫子瘦来宽。","好个沈香亭畔月，只在秋寒。"]},{"t":"烛影摇红","f":"曲","c":["红叶翻阶，晚风微扇回轻暖。","群仙高跨紫云车，来赴蓬莱宴。","绣幕围香处远。","扬帘花、时时影转。","彩衣嬉戏，玉女回环，绿娇红软。","戛玉调丝，□音缭绕笙歌院。","蟠桃花发正当春，烟媚明霞脸。","休□飞琼女伴。","捧瑶觞、何妨屡劝。","百处偕老，五福齐眉，人间稀见。"]},{"t":"减字木兰花","f":"曲","c":["幕天度地。","瑞脑香浓笙歌沸。","白纻衣轻。","鹤发童颜照座明。","轻簪小珥。","都是人间真富贵。","好倩丹青。","画与人间作寿星。"]},{"t":"婆罗门引 亦名菊潭秋","f":"曲","c":["商于六里，野塘千古□烟霞。","灵苗郁郁无涯，浩荡青冥风露，金素发清华。","散霜丛弥岸，月影明沙。","仙经浪夸。","种瑶草、养铅砂。","争信琼杯芳荐，药镜黄芽。","秋香晚节，也分到、山中宰相家。","休更羡、刘阮桃花。"]},{"t":"婆罗门引 过孟津河山亭故基","f":"曲","c":["短衣匹马，白头重过洛阳城。","百年一梦初惊。","寂寞高秋云物，残照半林明。","澹横舟古渡，落雁寒汀。","河山故亭。","人与镜、两峥嵘。","争信黄垆此日，深谷高陵。","一时朋辈，谩留住、穷途阮步兵。","尊俎地、谁慰飘零。"]},{"t":"婆罗门引 兖州龙兴阁感遇","f":"曲","c":["峄山霁雪，九层飞观郁峥嵘。","风烟画出新亭。","老眼来今往古，天地两无情。","但浮云平野，短日芜城。","酒狂步兵。","书与剑、此飘零。","为问云间鸡犬，几度丹成。","停杯不语，竟何用、千秋身后名。","休自倚、湖海平生。"]},{"t":"婆罗门引 望月","f":"曲","c":["素蟾散彩，九秋风露发清妍。","常娥尽有情缘。","留著三五盈盈，永夜照凭肩。","看晚妆临镜，若个婵娟。","寻常月圆。","恨都向、别时偏。","几度邮亭枕上，野店尊前。","珠明玉秀，算一日、相看一日仙。","人共月、长似今年。"]},{"t":"惜分飞 戏王鼎玉同年","f":"曲","c":["人见何郎新来瘦。","不见天寒翠袖。","绣被熏香透。","几时却似鸳鸯旧。","九十日春花在手。","可惜欢缘未久。","去去休回首。","柔条去作谁家柳。"]},{"t":"惜奴娇","f":"曲","c":["画扇高秋，恨尘暗秦王女。","涉东城、春烟绿树。","燕子来时应解说，征鞍处。","记取。","未忘得、兰膏香聚。","枕上新声，断肠是江南句。","更行云无心也住。","未了情缘，算惟有、相将云。","□去。","枉轻负、梨花暮雨。"]},{"t":"梅花引 同张仲经杨飞卿赋青梅","f":"曲","c":["绿华仙萼彩云间。","雪消残。","拥香□。","随意轻匀浅注尽高闲。","向道是梅刚不信，更谁占、东风最上番。","韵绝秀绝香又绝，恨□千山复□山。","才情似记何郎句，清泪斑斑。","寂寞孤村篱落小溪湾。","修竹萧萧霜月苦，好留与、青绫护晓寒。"]},{"t":"清平乐","f":"曲","c":["香团娇小。","拍拍春多少。","一树铅华春事了。","消甚珠围翠绕。","生经闹簇枯枝。","只愁吹破胭脂。","说与东风知道，杏花不看开时。"]},{"t":"清平乐","f":"曲","c":["村墟潇洒，似是朱陈画。","神武冠须早挂。","可待儿婚女嫁。","山深水木清华。","渔樵好个生涯。","梦想平桥南畔，竹篱茅舍人家。"]},{"t":"清平乐","f":"曲","c":["离肠宛转。","瘦觉妆痕浅。","飞去飞来双语燕。","消息知郎近远。","楼前小雨珊珊。","海棠帘幕轻寒。","杜宇一声春去，树头无数青山。"]},{"t":"清平乐","f":"曲","c":["香凝娇聚。","玉立临春树。","细看司花留意处。","都在轻匀浅注。","相逢南陌东城。","有情只似无情。","说与新来憔悴，莺儿不解丁宁。"]},{"t":"清平乐","f":"曲","c":["小桥流水。","一径修篁里。","走马章台人未老。","只爱明窗净几。","杏花白白红红。","花时日日狂风。","不是碧壶香供，真成恼破春工。"]},{"t":"清平乐","f":"曲","c":["溪头来去。","坐卧沿溪树。","管甚人间无著处。","已被白云留住。","生平不置肝肠。","只今物我都忘。","说与山中鱼鸟，相亲相近何妨。"]},{"t":"清平乐","f":"曲","c":["琼枝瑶草。","来自三山岛。","莫道生男堪慰老。","掌上金儿更好。","胭脂杏蕾生红。","绣襦学弄春风。","好共兰兰楚楚，画教乞巧图中。"]},{"t":"清平乐","f":"曲","c":["春风倾倒。","京洛春回早。","走马章台人未老。","金翠鹓雏更好。","安排美景良辰。","放教花柳搀新。","谁似君家池馆，又添丹桂灵椿。"]},{"t":"清平乐","f":"曲","c":["丹书碧字。","细说金华事。","试问谁边堪举似。","除却青莲居士。","胎仙八表泠风。","争教低首樊笼。","梦里云装烟驾，倚天坛影西东。"]},{"t":"清平乐","f":"曲","c":["兰膏香聚。","醉枕闻低语。","一刻春宵流水去。","诉得离情几许。","桃花红浅红深。","五年烟草归心。","留得一枝春在，争教绿叶成阴。"]},{"t":"清平乐 太山上作","f":"曲","c":["江山残照。","落落舒清眺。","涧壑风来号万窍。","尽入长松悲啸。","井蛙瀚海云涛。","醯鸡日远天高。","醉眼千峰顶上，世间多少秋毫。"]},{"t":"清平乐 忆镇阳","f":"曲","c":["悲欢聚散。","世事天谁管。","梳去梳来双鬓短。","镜里看看雪满。","燕南十月霜寒。","孤身去住都难。","何日西窗灯火，眼前儿女团栾。"]},{"t":"清平乐 罢镇平归西山草堂","f":"曲","c":["垂杨小渡。","处处归鞍驻。","八十田翁良愧汝。","把酒千言万语。","□□细侯竹马相从。","笑渠奔走儿童。","十里村箫社鼓，依然傀儡棚中。"]},{"t":"清平乐 嘲儿子阿宁","f":"曲","c":["娇莺娅姹。","解说三生话。","试看青衫骑竹马。","若个张萱许画。","西家撞透烟楼。","东家谈笑封侯。","莫道元郎小小，明年部曲黄牛。"]},{"t":"渔家傲","f":"曲","c":["午醉醒来春欲去。","莺儿燕子都无语。","好个一春行乐处。","花无数。","宝钗贳酒花前舞。","十里驿亭杨柳树。","多情折断青青缕。","春到去时留不住。","留不住。","西城日日风和雨。"]},{"t":"眼儿媚","f":"曲","c":["阿仪丑笔学雷家。","绕口墨糊涂。","今年解道，疏篱冻雀，远树昏鸦。","乃公行坐文书里，面皱鬓生华。","儿郎又待，吟诗写字，甚是生涯。"]},{"t":"谒金门","f":"曲","c":["罗衾薄。","帘外五更风恶。","醉后题诗浑忘却。","乌啼残月落。","憔悴何郎东阁。","病酒不禁重酌。","袖里梅花春一握。","幽怀无处托。"]},{"t":"黄鹂绕碧树 秋景","f":"曲","c":["鸳瓦霜轻，翠帘风细，高门瑞气非烟。","积庆源深，有长庚应梦，乔岳生贤。","妙龄秀发，谢庭兰玉争妍。","名动缙绅，况文章政术，俱是家传。","别有神功厚德，向东州治狱，平反玉函。","高第仙风道骨，锡与长年。","最好素秋时节，有画堂高启宾筵。","何妨纵乐，笙歌捧觥船。"]},{"t":"喜迁莺","f":"曲","c":["云雷天造。","快嫖姚玉节，生平豪妙。","野宿貔貅，江横组练，画角一声霜晓。","鱼鸟简书知畏，草木威名先到。","更谁似，并虎头飞将，封侯差早。","谈笑。","尊俎地，兵卫画戟，燕寝凝香好。","伏枥雄心，缺壶高唱，意气不妨倾倒。","父子一门忠力，唯有君恩须报。","济时了。","看郎山长对，元勋难老。"]},{"t":"喜迁莺","f":"曲","c":["清和时序。","望桂影渐生，薰风微度。","拂□金枝，传芳玉叶，天下瑞麟重睹。","竞敕谢庭，兰□振振，西痈□鹭。","庆门里，把丹枝争折，青云平步。","声誉。","喧盛世，咏少□□，□□□□□。","□□□□，□□□□，□□□□□□。","今辰称美，愿与冈陵同固。","更著取。","继沂公勋业，东平茅土。"]},{"t":"最高楼 商于鲁县北山","f":"曲","c":["商于路，山远客来稀。","鸡犬静柴扉。","东家欢饮姜芽脆，西家留宿芋魁肥。","觉重来，猿与鹤，总忘机，风浪里，竟安归。","云山既不求吾是，林泉又不责吾非。","任年年，藜藿饭，芰荷衣。"]},{"t":"朝中措","f":"曲","c":["香轻红浅露梅腮。","江上早春来。","玉声朝丹阙，霓旌影下瑶阶。","朱门向晓，三千珠履，十二金钗。","碧海金鸾来报，蟠桃一夜花开。"]},{"t":"朝中措","f":"曲","c":["醉来长铗为谁弹。","憔悴入函关。","一带秦川如画，夕阳仙堂空闲。","门边肮脏，胸中磈磊，何苦人间。","匹马明年西去，看君射虎南山。"]},{"t":"朝中措","f":"曲","c":["时情天意枉论量。","乐事苦相忘。","白酒家家新酿，黄花日日重阳。","城高望远，烟浓草澹，一片秋光。","故国江山如画，醉来忘却兴亡。"]},{"t":"朝中措","f":"曲","c":["芦沟河上度旃车。","行路看宫娃。","古殿吴时花草，奚琴塞外风沙。","天荒地老，池台何处，罗绮谁家。","梦里数行灯火，皇州依旧繁华。"]},{"t":"朝中措","f":"曲","c":["良宵一刻抵千金。","孤负百年心。","好个一江春水，深来不似情深。","一天好事，还教容易，著甚消任。","烦恼直须宁耐，不成长似如今。"]},{"t":"朝中措","f":"曲","c":["惊弦裂石笔生华。","清兴入悲笳。","为爱南山夜猎，笑人杜曲桑麻。","高歌醉眼，千金骏马，八月仙槎。","都把平生湖海，看君咫尺龙沙。"]},{"t":"朝中措","f":"曲","c":["夹衣晨起怯新霜。","归路楚山长。","只道佳期相误，梦魂夜夜谁行。","镜中鸾舞，芝间鹊转，未抵欢狂。","都把而今烦恼，见时别与论量。"]},{"t":"朝中措","f":"曲","c":["年年重五近佳辰。","蒲艾一番新。","满酌九霞香酝，寿君两鬓长春。","闺中美秀，如何赋得，林下精神。","早办□□布袄，共为云水闲人。"]},{"t":"朝中措","f":"曲","c":["春闺寂寂掩苍苔。","风雨卷春回。","拟写碧云心事，笔头无句安排。","灯昏酒冷，愁牵梦引，直似秋怀。","料得酴醾知我，枕边时有香来。"]},{"t":"朝中措","f":"曲","c":["金凤飘拂莹蝉光。","依约桂华香。","紫府云輧游冶，朱门锦乡高张。","笙歌丛里，霞杯潋滟，玉树芬芳。","共祝寿龄何似，□□松柏□长。"]},{"t":"朝中措","f":"曲","c":["添丁名字入新收。","一长看过头。","拾得羽阳宫瓦，不愁撞透烟楼。","遗山野客，求田问舍，梦想南州。","说甚河东三凤，安排老□班彪。"]},{"t":"朝中措","f":"曲","c":["添盆瓣喜万家传。","满意掷金钱。","仙果休嗔生晚，灵椿最得春偏。","隆颅犀角，丹砂一指，玉润松坚。","看取翰林枝叶，却如东海当年。"]},{"t":"朝中措","f":"曲","c":["帘旌烘日绣波翻。","霜晓试轻寒。","高宴黄堂初启，云外列仙班。","昼明丽锦，香浮宝鸭，身在蓬山。","三见扬尘沧海，春风一笑人间。"]},{"t":"朝中措","f":"曲","c":["御香新拆紫囊封。","苒苒绿云丛。","开晚只嗔寒勒，妆成又怕晴烘。","化工也为，花中第一，熏染偏浓。","谁有石家红锦，重重围住春风。"]},{"t":"朝中措","f":"曲","c":["樱桃花下玉亭亭。","随步觉春生。","处处绮罗丛里，偏他特地分明。","韶华似水，棠梨叶吐，杨柳新成。","不是低鬟一笑，十分只是无情。"]},{"t":"朝中措 永宁时作","f":"曲","c":["连延村落泣阳崖。","川路到山回。","竹树攒成风月，溪堂隔断尘埃。","小亭幽圃，酴醾未过，芍药初开。","驴上一壶春，主人莫厌重来。"]},{"t":"朝中措 周帅花堂紫牡丹","f":"曲","c":["芳苞初破紫霞杯。","香动绿云堆。","只道人间花尽，争知天上春回。","朝吟暮绕，使君情重，不厌频来。","好把韶华留住，莫教百朵齐开。"]},{"t":"朝中措 贺张伯宁家儿子犀郎晬日","f":"曲","c":["骊珠光彩照燕南。","喜气溢街谈。","未到灵椿丹桂，一枝先看宜男。","明年人日，探官贴子，已具新衔。","管甚犀郎小小，安排竹马青衫。"]},{"t":"朝中措 效俳体","f":"曲","c":["瑞云浮动酒波红。","一醉卷愁空。","昨日海棠窠下，今朝芍药香中。","蜂迎蝶送，珠围翠绕，尽谢春风。","管甚碧油堂印，且教临老花丛。"]},{"t":"朝中措 寄杨漕","f":"曲","c":["秋鸿社燕偶相逢。","鞍马又西东。","孤负水南三月，安排万紫千红。","旧游新梦，绿波南浦，黄叶西风。","任是麒麟阁上，争如鹦鹉杯中。"]},{"t":"感皇恩","f":"曲","c":["梦寐见并州，今朝身到。","未怕清汾照枯槁。","百年狂兴，尽与家山倾倒。","黑头谁办得、归来早。","梁苑绿波，长安春草。","惆怅行人暗中老。","故人相送，记得临行曾道。","故园行乐地、依然好。"]},{"t":"感皇恩","f":"曲","c":["浓露堪秋容，凉生□晓。","斗帐葱葱瑞烟袅。","佩霞符梦，初诞灵妃娟妙。","冰姿和玉骨、天然好。","菊韵莲敷，翠眉年少。","消得相如共偕老。","深斟寿酒，惟愿早对新号。","更朝先插上、宜男草。"]},{"t":"感皇恩 寿韩侯恬然","f":"曲","c":["水上觅红云，云藏仙岛。","云外晴峰翠于扫。","东园行乐，一洗山林枯槁。","万金谁办得、安闲早。","石上玉芝，松间瑶草。","容易休教使君老。","寿杯宫袖，醉眼风荷翻倒。","锦堂花与月、年年好。"]},{"t":"感皇恩 张侯寿席此州乐府垂杨一曲方盛","f":"曲","c":["天外想春来，春来天上。","乐府垂杨动新唱。","扁舟西子，并与云帆无恙。","五湖将底用，黄金像。","水阁清深，晴楼萧爽。","丝竹留教助清赏。","松腴仙酎，万斛溪泉供酿。","寿杯先领取、山中相。"]},{"t":"感皇恩 洛西为刘景玄赋秋莲曲","f":"曲","c":["金粉拂霓裳，凌波微步。","瘦玉亭亭倚秋渚。","澹香高韵，费尽一天清露。","恼人容易被、西风误。","微雨岸花，斜阳汀树。","自惜风流怨迟暮。","珠帘青竹，应有阿溪新句。","断魂谁解与，烟中语。"]},{"t":"摊破浣溪沙 代赠仲经所亲","f":"曲","c":["锦瑟花年燕子楼。","楚云湘雨等闲休。","留在贞元供奉曲，尽风流。","约略睡痕妆镜晚，留连香韵琐窗秋。","总道竹西歌吹好，去来休。"]},{"t":"摸鱼儿","f":"曲","c":["问莲根、有丝多少，莲心知为谁苦。","双花脉脉娇相向，只是旧家儿女。","天已许。","甚不教、白头生死鸳鸯浦。","夕阳无语。","算谢客烟中，湘妃江上，未是断肠处。","香奁梦，好在灵芝瑞露。","人间俯仰今古。","海枯石烂情缘在，幽恨不埋黄土。","相思树。","流年度、无端又被西风误。","兰舟少住。","怕载酒重来，红衣半落，狼藉卧风雨。"]},{"t":"摸鱼儿","f":"曲","c":["笑青山、不解留客，林丘夜半掀举。","萧萧暮景千山雪，银箭忽传飞雨。","还记否。","又恐似、龙潭垂钓风雷怒。","山人良苦。","料只为三年，长安道上，来与浣尘土。","清阴渡。","渺渺风烟杖屦。","名山元有佳处。","山僧乞我溪南地，十里瘦藤高树。","私自语。","更须问、洼尊此日谁宾主。","朝来暮去。","要山鸟山花，前歌后舞，从我醉乡路。"]},{"t":"摸鱼儿","f":"曲","c":["忆元龙、旧家湖海，不应年鬓衰槁。","翩翩竹马儿童喜，惊儿汉江归报。","归计早。","黄金印、征西已付诸郎了。","红云仙岛。","渺千里移春，浓薰细染，春意已倾倒。","西溪上，玉镜修眉翠扫。","题诗曾许谁到。","溪亭未入奚奴锦，望断绿波春草。","君且道。","人间世、虚名得似欢游好。","风流未老。","约款段随车，鸱夷载酒，迎我霜陵道。"]},{"t":"摸鱼儿 楼桑呼汉昭烈庙","f":"曲","c":["问楼桑、故居无处。","青林留在祠宇。","荒坛社散鸟声□，寂寞汉家箫鼓。","春已暮。","君不见、锦城花重惊风雨。","刘郎良苦。","尽玉垒青云，锦江秀色，办作一丘土。","西山好，满意龙盘虎踞。","登临感怆千古。","当时诸葛成何事，伯仲果谁伊吕。","还自语。","缘底事、十年来往燕南路。","征鞍且驻。","就老瓦盆边，田翁共饮，携手醉乡去。"]},{"t":"满江红","f":"曲","c":["汉水方城，今古道、几回投迹。","留滞久、浩歌狂醉，此心谁识。","渭北清光摇草树，故人对酒相应识。","记雨窗、相对话离忧，秋风夕。","风月笛，烟霞屐。","身易老，时难得。","鸟飞天不尽，野春平碧。","我梦秦东亭上饮，举头但见长安日。","便与君、重结入关期，明年必。"]},{"t":"满江红","f":"曲","c":["一枕馀醒，厌厌共、相思无力。","人语定、小窗风雨，暮寒岑寂。","绣被留欢香未减，锦书封泪红犹湿。","问寸肠、能著几多愁，朝还夕。","春草远，春江碧。","云暗澹，花狼藉。","更柳绵闲扬，柳丝谁织。","入梦终疑神女赋，写情除有文星笔。","恨伯劳、东去燕西归，空相忆。"]},{"t":"满江红","f":"曲","c":["枕上吴山，隐隐见、宫眉修碧。","人好在、断浑似，画图相识。","罗袜尘香来有信，玉箫声远寻无迹。","恨不将、春色醉仙桃，迷芳席。","婵娟月，韶华日。","梦已尽，愁仍积。","江花共江草，几时终极。","锦树摧残胡蝶老，冰绡剪破鸳鸯只。","拌楚云、湘雨一生休，休相忆。"]},{"t":"满江红","f":"曲","c":["腊后春前，高楼外、梅飘香馥。","正□□云輧初下，瑶池西曲。","罗幕笙歌围粉黛，阶前青紫团兰玉。","更如宾、相待衮衣新，尊浮醁。","柔懿范，康宁福。","荣耀事，都齐足。","向宝薰烟里，寿祺同祝。","□雪仙姿元不老，丹台已注长生箓。","问从今、欢宴几何年，蟠桃熟。"]},{"t":"满江红","f":"曲","c":["寒日春温，照庭院、瑞烟芬馥。","人尽道、衢山当日，谪仙新毓。","子舍荣华孙□茂，诗书万卷生涯足。","但放怀、寿酒十分斟，添香祝。","竹太瘦，松偏独。","鹤易怨，龟何俗。","算人间无物，共供新曲。","但愿长如天上月，年年此夕光如玉。","伴长庚、百岁永团圆，蟠桃熟。"]},{"t":"满江红","f":"曲","c":["画戟清香，谁得似、韦郎诗笔。","还又见、从容车骑，待州西北。","竹马儿童应有语，使君姓字人人识。","是往时、曾护国西门，金汤壁。","千日醉，三更席。","事已去，寻无迹。","对暮凉灯火，怅然如失。","万里功名知未免，中年离别万堪惜。","恨洛阳、风雨暗旌旗，空相忆。"]},{"t":"满江红 三泉醉饮","f":"曲","c":["桃李漫山，风日暖、朝来开彻。","东溪上、落花流水，暮春三月。","一片花飞春意减，有花堪折君须折。","恨百年、春事短长亭，匆匆别。","金缕唱，金蕉拍，休直待，芳华歇。","到绿阴青子，只供愁绝。","坐上常看尊有酒，镜中莫管头如雪。","料醉来、人说次公狂，从渠说。"]},{"t":"满江红 内乡半山亭浮休居士张芸叟洼尊石刻在焉","f":"曲","c":["江上洼尊，人道有、浮休遗迹。","尊俎地、江山如画，百年岑寂。","白鹤重来城郭在，山花山鸟浑相识。","便与君、载酒半山亭，追畴昔。","人易老，时难得。","欢未减，悲还及。","身前与身后，杳无终极。","一笑何须留故事，千年复知今日。","拌醉来、横卧陇头云，林间石。"]},{"t":"满江红 内乡作","f":"曲","c":["老树荒台，秋兴动、悠然独酌。","秋也老、江山憔悴，鬓华先觉。","人到中年原易感，眼看华屋归零落。","算世间、惟有醉乡民，平生乐。","凌浩荡，观寥廓。","月为烛，云为幄。","尽百川都酿，不供杯杓。","身外虚名将底用，古来已错今尤错。","唤野猿、山鸟一时歌，休休莫。"]},{"t":"满江红 关希颜之官徐州","f":"曲","c":["元鼎诗仙，知音少、喜君留迹。","还有恨、故山飞去，石城琼壁。","万里征西天有意，四方问舍今何日。","便金虬、飞驭解移文，知无及。","淮海地，云雷夕。","自不负，髯如戟。","望幕中谈笑，隐然勍敌。","此老何堪丞掾事，佳时但要江山笔。","向楚王、台上酒酣时，须相忆。"]},{"t":"满江红 再过水南","f":"曲","c":["问柳寻花，津桥路、年年寒节。","佳丽地、梁园池馆，洛阳城关。","白鹤重来人换世，凄凉一树梅花发。","记水南、昨暮赏春回，今华发。","金缕唱，龙香拨。","云液暖，琼杯滑。","料羁愁千种，不禁掀豁。","老眼只供他日泪，春风竟是谁家物。","恨马头、明月更多情，寻常缺。"]},{"t":"满江红 嵩山中作","f":"曲","c":["天上飞鸟，问谁遣、东生西没。","明镜里、朝为青鬓，暮为华发。","弱水蓬莱三万里，梦魂不到金银阙。","更几人、能有谢家山，飞仙骨。","山鸟弄，林花发。","玉杯冷，秋云滑。","彭殇共一醉，不争毫末。","鞭石何年沧海过，三山只是尊中物。","暂放教、老子据胡床，邀明月。"]},{"t":"满庭芳","f":"曲","c":["偃屈霜青，棱层烟碧，□□□古人间。","山光林色，常伴住人闲。","元有仙风道骨。","□心趁、玉笋朝班。","归来赋，不因五斗，谈笑挂衣冠。","九难。","谁不羡，商山橘弈，渭水渔竿。","引相君玉子，助发幽欢。","□□寿觞多少，南溟共北海波澜。","君知否，庙堂有意，相与□寒岩。"]},{"t":"满庭芳","f":"曲","c":["丹染吴枫，青环越岫，镜天霁色凝鲜。","画堂环佩，瑞霭拥神仙。","天遣神清海字，亲曾受、黄石奇编。","兴王略，智名俱美，功业妙难言。","□翩。","□□立，香飘衮服，乡色映貂蝉。","有清诗千首。","美酒如川。","长与嫦娥共约，放飞轮、今夕先圆。","中秋月，从今屈指，更借一千年。"]},{"t":"满庭芳","f":"曲","c":["腊雪融酥，春冰浮玉，素蟾三五才过。","晚来庭户，何事五云多。","尽道九天麟坠，锵环佩、声袅鸣珂。","风标爽，胸中嵬垒，豪气挽天河。","平生横槊志，指挥夷虏，平□干戈。","□他年功业，翠琰应磨。","福海寿山难老，金尊满、鲸吸沧波。","歌声溢，玉山扶起，拦取醉颜酡。"]},{"t":"满庭芳","f":"曲","c":["妆镜韶华，牙签名品，惯看培养经年。","何年曾见，槁叶散芳妍。","知是毗耶坐客，三生梦、犹有情缘。","熏香手，融霞晕雪，来占百花前。","嫣然。","谁为笑，珠围翠绕，且共流连。","待诗中偷写，画里真传。","绣帽拥霜凝紫塞，琼肌莹，春满温泉。","新声在，梁园异事，并记玉堂仙。"]},{"t":"满庭芳","f":"曲","c":["绛阙凌风，瑶池玩月，众仙侍立清班。","就中仙伯，乘兴到人间。","洒落襟怀万顷，词源壮、三峡波澜。","偏惟有，清游自适，不肯饵金丹。","清闲。","谁得似，轩名佚老，名利都关。","但梦中时到，方丈蓬山。","满泛杯中玉液，应知是、生长尧年。","凭谁劝，云璈度曲，醉□朱颜。"]},{"t":"满庭芳","f":"曲","c":["十里轻阴，一川新绿，不应春事来迟。","试探消息，犹未减罗衣。","谁信闺房秀色，倚风试、桃李先枝。","呈纤巧，吹香滴粉，漫放镜奁移。","芳时。","常在眼，歌清舞软，烟缕霏霏。","向金徽促柱，玉局弹棋。","尽待功成九转，蓬莱近、未肯升栖。","还应是，梁鸿举案，同作百年期。"]},{"t":"瑞鹤仙","f":"曲","c":["四山秋气爽。","正云淡、银河露零仙掌。","轻烟瑞屏嶂。","有文星一点，□从天上。","襟怀倜傥。","笑谈间、光焰万丈。","向玉皇案底，秋毫□纸，屡承天奖。","何况云龙风虎，万乘故人，两朝耆望。","油幢玉帐。","听环佩，丁东响。","有弹弦吹竹，年年高会，增壮中秋气象。","□月中玉兔长生，借公醉赏。"]},{"t":"瑞鹤仙","f":"曲","c":["薰风弦上奏。","正蛙鸣池沼，莺吟槐柳。","龙涎喷金兽。","□一番疏雨、梅黄时候。","神仙旧友。","爱五亭、山明水秀。","向□时庆旦，高明富贵，殆由天授。","知否。","风流儒雅，利达丛中，似公稀有。","芝兰挺秀。","看早晚，定成就。","况雪儿佳丽，歌清舞妙，管取天长地久。","愿年年预借菖蒲，劝君寿酒。"]},{"t":"瑞鹤仙","f":"曲","c":["薰风□院宇。","蔼清香、凝户晓凉如雨。","开帘望莲渚。","拥轻红嫩绿、三千宫女。","□商泛羽。","命双成、婵娟妙舞。","记当时，初下瑶池阆苑，翠輧来处。","几许玉簪珠履，玳筵绮席，寿觞初举。","从容笑语。","吹箫伴，骖鸾女。","算灵椿难老，蟠桃频见，两□蓬瀛便住。","看家族叶叶金貂，凤池稳步。"]},{"t":"蓦山溪","f":"曲","c":["群花烂漫，春色浓如酒。","芳草绿铺砌，正酴醾、牡丹时候。","佳辰协瑞，来降玉宫仙。","珠帘卷，画堂深，香雾腾金兽。","朱颜□□，不改长如旧。","金斝莫辞深，拚通宵、尽从银漏。","笙歌丛里，欢□度年华，看荣贵，有儿孙，永祝松椿寿。"]},{"t":"蓦山溪 夏景集曲名","f":"曲","c":["梁州夏早，南浦荷花媚。","人月欲圆时，贺圣朝、生申名世。","桂枝香满，早夺锦标回，春光好，少年游，烂醉蓬莱里。","谒金门贵，小镇西南地。","品令贯三台，□雄望、江南江北。","归朝欢乐，好事近佳辰，风流子，玉团儿，为唱千秋岁。"]},{"t":"虞美人","f":"曲","c":["一杯薄酒休辞醉。","愿一千二百岁。","白云长伴此身闲，桂月苹风，分取□壶天。","鹊炉香□黄金尾。","庭院生秋意。","倒倾银汉作流霞。","剩看蟠桃，碧海记年华。"]},{"t":"虞美人","f":"曲","c":["樱桃元是仙郎种。","次第芳菲动。","开残山杏没都红。","一树梨花如雪月明中。","三生蝶化南华梦。","只有情缘重。","曲阑幽径小帘栊。","好共扫眉才子管春风。"]},{"t":"虞美人","f":"曲","c":["花心苦被春摇荡。","粉艳娇相向。","隔帘微雨送幽香。","未羡寒梅，疏影月昏黄。","芳温一念何时忘。","笑了还惆怅。","无端开近宋东墙。","真个晓人，情思断人肠。"]},{"t":"虞美人 题苏小小图","f":"曲","c":["桐阴别院宜清昼。","入坐春山秀。","美人图子阿谁留。","都是宣和名笔内家收。","莺莺燕燕分飞后。","粉澹梨花瘦。","只除苏小不风流。","倒插一枝萱草凤钗头。"]},{"t":"鹊桥仙","f":"曲","c":["槐根梦觉，瓜田岁暮，白发新来无数。","长安迁客望朱崖，未唤得、烟霄失路。","西州芍药，南州琼树，香满云窗月户。","蒺藜沙上野花开，也算却、春风一度。"]},{"t":"鹊桥仙","f":"曲","c":["梨花春暮，垂杨秋晚，归袖无人重挽。","浮云流水十年间，算只有、青山在眼。","风台月榭，朱唇檀板，多病全疏酒盏。","刘郎争得似当时，比前度、心情又减。"]},{"t":"鹊桥仙 同钦叔钦用赋梅","f":"曲","c":["孤根渐暖，芳魂乍返，待吐檀心又懒。","未先拈出一枝香，算只是、司花会拣。","情缘未断，韶华易减，早去寻芳已晚。","东风容易莫吹残，暂留与、何郎慰眼。"]},{"t":"愿成双","f":"七言律诗","c":["绣帘高卷沈烟细。","燕堂深、玳筵初开。","阶下芝兰劝金卮。","有多少、雍容和气。","翠眉偕老应难比。","效鸾凤、镇日于飞。","惟愿一千二百岁。","永同欢、如鱼如水。"]},{"t":"蝶恋花","f":"曲","c":["最是一年秋好处。","橘绿橙黄，半带金茎露。","翠幕珠帘开紫府。","五云深处台星聚。","昨夜玉皇传诏语。","闻道君家，勋业高前古。","赐与金丹并玉醑。","壶中日月留长住。"]},{"t":"蝶恋花","f":"曲","c":["春到桃源人不到。","白发刘郎，误入红云岛。","著意酬春还草草。","东风一夜花如扫。","过眼风花人自恼。","已□寻芳，更约明年早。","天若有情天亦老。","世间原只无情好。"]},{"t":"蝶恋花","f":"曲","c":["急鼓疏钟催报晓。","楼上今朝，卷起重帘早。","环佩珊珊香袅袅。","尘埃不到蓬莱岛。","何用珠玑相映照。","韵美形清，自有天然好。","莫向尊前辞醉倒。","松枝鹤骨偏宜老。"]},{"t":"蝶恋花","f":"曲","c":["玉宇生凉秋恰半。","月到今宵，分外清光满。","兔魄呈祥冰彩烂。","广寒宫里逢华旦。","聪慧风流天与擅。","玉骨冰姿，本是飞琼伴。","且领绿衣诗酒劝。","蟠桃待熟瑶池宴。"]},{"t":"蝶恋花 戊辰岁长安作","f":"曲","c":["一片花飞春意减。","雨雨风风，常恨寻芳晚。","若个花枝偏入眼。","尊前细问春风拣。","醉里看花云锦烂。","只记莺声，不记红牙板。","留著佳人鹦鹉盏。","明朝剩把长条换。"]},{"t":"蝶恋花 甲申岁南都作","f":"曲","c":["牢落羁怀愁有信。","流水浮生，几见中秋闰。","千古诗坛将酒阵。","一轮明月消磨尽。","八月人间秋满鬓。","桂树扶疏，更与秋风近。","天上姮娥应有恨。","骑鲸人去无人问。"]},{"t":"蝶恋花 白鹿原新斋作","f":"曲","c":["负郭桑麻秋课重。","十角黄牛，分去声得山田种。","乡社鸡豚人与共。","春风渐入浮蛆瓮。","绕屋清溪醒午梦。","一榻翛然，坐受云山供。","四海虚名将底用。","一声啼鸟岩花动。"]},{"t":"蝶恋花 同乐舜咨郎中梦梅","f":"曲","c":["梅信初传金点小。","翠羽多情，尽耐风枝袅。","乞与吟鞋□百绕。","小窗月暗人声悄。","枕上诗成还自笑。","万斛清愁，换得春多少。","临水幽姿空自照。","罗浮册下孤村晓。"]},{"t":"踏莎行","f":"曲","c":["微步生尘，残妆晕酒。","朱门如海空回首。","东风正有去年花，柔条去作谁家柳。","细雨春寒，青灯夜久。","孤衾未暖还分手。","梦中见也不多时，怎生望得长相守。"]},{"t":"醉花阴","f":"曲","c":["候馆青灯淡相对。","夜迢迢无奈。","掩泪惜分飞，好梦空回，留得闲愁在。","同心易绾双罗带。","只连环难解。","且莫望归鞍，尽眼西山，人更西山外。"]},{"t":"鹧鸪天","f":"曲","c":["著意朝云复暮云。","良宵留住宋东邻。","玄霜玉杵期无定，高烛明妆赏更新。","团扇曲，画梁尘。","万家秋气一家春。","月光不照金尊里，只为夭娆醉得人。"]},{"t":"鹧鸪天","f":"曲","c":["总道狙公不易量。","朝三暮四尽无妨。","旧时邺下刘公干，今日家中白侍郎。","歌浩荡，酒淋浪。","浮云身世两相忘。","孤峰顶上青天阔，独对春风舞一场。"]},{"t":"鹧鸪天","f":"曲","c":["拍塞车箱满载书。","梁鸿元与世相疏。","只缘携手成归计，不恨埋头屈壮图。","苍玉研，古铜壶。","坐看儿辈了耕锄。","年年此日如川酒，千尺青松尽未枯。"]},{"t":"鹧鸪天","f":"曲","c":["白白红红小树花。","春风满意与铅华。","烟霄自属千金马，月旦真成两部蛙。","诸葛菜，邵平瓜。","白头孤影一长嗟。","南园睡足松阴转，无数蜂儿趁晚衙。"]},{"t":"鹧鸪天","f":"曲","c":["天上腰枝说馆娃。","眼中金翠有芳华。","行去著意留歌扇，远柳无情隔钿车。","周昉画，洛阳花。","一枝浓艳落谁家。","春寒恨杀如年夜，庭树阴阴欲暮鸦。"]},{"t":"鹧鸪天","f":"曲","c":["姚宋光明到此家。","争教老作贾长沙。","碧山也要崖州住，百匝千遭绕郡衙。","南苑月，曲江花。","青云轩盖满京华。","新生黄雀君休笑，占了春光却被他。"]},{"t":"鹧鸪天","f":"曲","c":["憔悴鸳鸯不自由。","镜中鸾舞只堪愁。","庭前花是同心树，山下泉分两玉流。","金络马，木兰舟。","谁家红袖水西楼。","春风殢杀官桥柳，吹尽香绵不放休。"]},{"t":"鹧鸪天","f":"曲","c":["月窟秋清桂叶丹。","仙家酿熟水芝残。","香来宝地三千界，露入金茎十二盘。","天澹澹，夜漫漫。","五湖豪客酒肠宽。","醉来独跨苍鸾去，太华峰高玉井寒。"]},{"t":"鹧鸪天","f":"曲","c":["华表归来老令威。","头皮留在姓名非。","旧时逆旅黄粱饭，今日田家白板扉。","沽酒市，钓鱼矶。","爱闲真与世相违。","墓头不要征西字，元是中原一布衣。"]},{"t":"鹧鸪天","f":"曲","c":["抛却浮名恰到闲。","却因猥懒得颟顸。","从教道士夸悬解，未信禅和会热谩。","山院静，草堂宽。","一壶浊酒两蒲团。","题诗寄与王夫子，乘兴时来看药阑。"]},{"t":"鹧鸪天","f":"曲","c":["内府清虚息万缘。","逍遥真是地行仙。","从他玉带金鱼贵，听我纶巾羽扇偏。","倾美酝，祝长年。","休辞潋滟十分圆。","来年此日称觞处，定有重孙戏膝前。"]},{"t":"鹧鸪天","f":"曲","c":["八月芦沟风路清。","短衣孤剑此飘零。","苍龙双阙平生恨，只有西山满意青。","尘扰扰，雁冥冥。","因君南望涌金亭。","还家剩买宜城酒，醉尽梅花不要醒。"]},{"t":"鹧鸪天","f":"曲","c":["寿菊才开□□□。","秋光着意主人家。","清香未许人间识，先占重阳□□□。","儿绶绿，母金花。","斑衣庭下乐无涯。","要知他日中书考，细步□□堤上沙。"]},{"t":"鹧鸪天","f":"曲","c":["偃蹇苍山卧北冈。","郑庄场圃入微茫。","即看花树三春满，旧数松风六月凉。","蔬近井，蜜分房。","茅斋坚坐有藜床。","傍人错比扬雄宅，笑杀韩家昼锦堂。"]},{"t":"鹧鸪天","f":"曲","c":["八茧吴蚕剩欲眠。","东西荷叶两相怜。","一江春水何年尽，万古清光此夜圆。","花烂锦，柳烘烟。","韶华满意与欢缘。","不应寂寞求凰意，长对秋风泣断弦。"]},{"t":"鹧鸪天","f":"曲","c":["万古寒光太白精。","直宜分作两郎星。","不□安得难兄弟，先后尧蓂三荚生。","霜月冷，斗杓横。","老人今夜亦齐明。","他年莫作郎星看，两两□躔拱太清。"]},{"t":"鹧鸪天","f":"曲","c":["自在晴云覆苑墙。","徘徊明月驻清光。","已看红袖沾芳酒，犹认宫螺映绮窗。","金翡翠，绣鸳鸯。","春风花暖柳绵香。","殷勤未数闲情赋，不愿将身作枕囊。"]},{"t":"鹧鸪天","f":"曲","c":["著意寻春苦未迟。","无情风雨妒芳期。","青楼天远无书到，绣被寒多只梦知。","云澹泞，月低迷。","洛阳山色见愁眉。","何时重解香罗带，细看春风玉一围。"]},{"t":"鹧鸪天","f":"曲","c":["临锦堂前春水波。","兰皋亭下落梅多。","三山宫阙空瀛海，万里风埃暗绮罗。","云子酒，雪儿歌。","留连风月共婆娑。","人间更有伤心处，柰得刘伶醉后何。"]},{"t":"鹧鸪天","f":"曲","c":["小字缭绫写欲成。","印来眉黛绿分明。","水流刻漏何曾住，玉作弹棋尽未平。","愁易积，梦频惊。","闲衾敧卧觉霜清。","月明不放寒枝稳，夜夜乌啼彻五更。"]},{"t":"鹧鸪天","f":"曲","c":["短发如霜久已拚。","无冠可挂更须弹。","初闻古寺多伥鬼，又说层冰有热官。","闲处坐，静中看。","时情天意酒杯干。","篱边老却陶潜菊，一夜西风一夜寒。"]},{"t":"鹧鸪天","f":"曲","c":["枕上清风午梦残。","华胥东望海漫漫。","湖山似要闲身管，花柳难将病眼看。","三径在，一枝安。","小斋容膝有馀宽。","鹿裘孤坐千峰雪，耐与青松老岁寒。"]},{"t":"鹧鸪天","f":"曲","c":["复幕重帘锦作天。","金荷银烛夜如年。","汉皋解佩终疑梦，缑岭吹笙恰是仙。","花一梦，柳三眠。","春风无意惜芳妍。","罗裙细看轻盈态，元在腰肢婀娜边。"]},{"t":"鹧鸪天","f":"曲","c":["零落栖迟感兴多。","酒杯直欲卷银河。","人间清镜悲华发，世外仙棋烂斧柯。","长袖舞，抗音歌。","月明人影两婆娑。","醉来知被旁人笑，无柰风情未减何。"]},{"t":"鹧鸪天","f":"曲","c":["百啭娇莺出画笼。","一双蝴蝶殢芳丛。","葱茏花透纤纤月，暗澹香摇细细风。","情不尽，梦还空。","欢缘心事泪痕中。","长安西望肠堪断，雾阁云窗又几重。"]},{"t":"鹧鸪天","f":"曲","c":["长恨箫声隔粉墙。","争教移住五云乡。","一溪春水关何事，流水桃花赚阮郎。","风搅梦，月侵床。","情缘消得海生桑。","鸳鸯不锁黄金殿，雌蝶雄蜂枉断肠。"]},{"t":"鹧鸪天","f":"曲","c":["玉立芙蓉镜里看。","铅红无地著边鸾。","半衾幽梦香初散，满纸春心墨未乾。","深院落，曲阑干。","旧欢新恨苎衣宽。","几时忘得分携处，黄叶疏云渭水寒。"]},{"t":"鹧鸪天","f":"曲","c":["袅袅香风响佩环。","广寒仙子跨青鸾。","谁教瑞世仪周国，天赋多才继小山。","铃阁静，画堂闲。","衮衣象服□团圆。","年年此日称觞处，留得菖蒲驻玉颜。"]},{"t":"鹧鸪天","f":"曲","c":["饮量平常发兴偏。","留连光景惜欢缘。","悲歌慷慨人争和，醉墨淋漓自笑颠。","麟阁画，祖生鞭。","拍浮多负酒家钱。","老来事事消磨尽，只有尊前似少年。"]},{"t":"鹧鸪天","f":"曲","c":["身外虚名一羽轻。","封侯何必胜躬耕。","田园活计浑闲在，诗酒风流属老成。","三会水，半山亭。","村村花柳自升平。","锦城未比还家好，何处而今有锦城。"]},{"t":"鹧鸪天","f":"曲","c":["酒兴浓于琥珀浓。","争教相望水西东。","人家寒食清明后，天气轻烟细雨中。","花不尽，柳无穷。","赏心难是此时同。","阿连近日歌喉稳，唱得春窗烛影红。"]},{"t":"鹧鸪天","f":"曲","c":["少日骊驹白玉珂。","灵砂犀角费频磨。","西城灯火长安梦，满意春风似两坡。","流素月，澹秋河。","百年狂兴一声歌。","醉归扶路人应笑，头上花枝柰老何。"]},{"t":"鹧鸪天","f":"曲","c":["好梦初惊百感新。","谁家歌管隔墙闻。","残灯收罢空明月，腊雪消融更暮云。","莺有伴，雁离群。","西窗寂寞酒微醺。","春寒留得梅花在，剩为何郎瘦几分。"]},{"t":"鹧鸪天","f":"曲","c":["澹澹青灯细细香。","四更人语在幽窗。","西风数点迎秋雨，六尺芙蓉满意凉。","秦树远，楚天长。","绿娇红小负年芳。","鸳鸯莫道无离恨，锁向金笼恰是双。"]},{"t":"鹧鸪天 与钦叔京甫市饮","f":"曲","c":["楼上歌呼倒接□。","楼前分手却相携。","雨前雨后花枝减，州北州南酒价低。","怜木雁，笑醯鸡。","鹤长凫短几时齐。","醒来门外三竿日，卧听春泥过马蹄。"]},{"t":"鹧鸪天 山阳七圣堂","f":"曲","c":["沙岸萦回入草泥。","霜余烟景自凄迷。","树嫌川近重重掩，云要村深故故低。","茅盖屋，稻分畦。","何人今日此幽栖。","十年来往山阳道，只□清溪过马蹄。"]},{"t":"鹧鸪天 木犀","f":"曲","c":["桂子纷翻浥露黄。","桂华高韵静年芳。","蔷薇水润宫衣软，婆律膏清月殿凉。","云岫句，海仙方。","情缘心事两难忘。","衰莲枉误秋风客，可是无尘袖里香。"]},{"t":"鹧鸪天 孟津作","f":"曲","c":["总道忘忧有杜康。","酒逢欢处更难忘。","桃红李白春千树，古是今非笑一场。","歌浩荡，墨淋浪。","银钗缟袂满邻墙。","百年得意都能几，乞与儿曹说醉狂。"]},{"t":"鹧鸪天 宫体八首","f":"曲","c":["候馆灯昏雨送凉。","小楼人静月侵床。","多情却被无情恼，今夜还如昨夜长。","金屋暖，玉炉香。","春风都属富家郎。","西园何限相思树，辛苦梅花候海棠。"]},{"t":"鹧鸪天 效东坡体","f":"曲","c":["煮酒青梅入坐新。","姚家池馆宋家邻。","楼中燕子能留客，陌上杨花也笑人。","梁苑月，洛阳尘。","少年难得是闲身。","殷勤昨夜三更雨，胜醉东城一日春。"]},{"t":"鹧鸪天 效朱希真体","f":"曲","c":["十步宫香出绣帘。","恼人帘底月纤纤。","五花骄马垂杨渡，孤负仙郎侧帽檐。","秋澹澹，酒厌厌。","新诗和恨入香奁。","相思恰似鸳鸯锦，一夜新凉一夜添。"]},{"t":"鹧鸪天 莲","f":"曲","c":["瘦绿愁红倚暮烟。","露华凉冷洗婵娟。","含情脉脉知谁怨，顾影依依定自怜。","风送雨，水连天。","凌波无梦夜如年。","何时北渚亭边月，狼藉秋香拂画船。"]},{"t":"鹧鸪天 其一 宿赵州","f":"曲","c":["宿酒消来睡思清。","梦中身世可怜生。","绿衿红烛樱桃宴，画角黄云细柳营。","秋历□，月胧明。","步檐倚杖候晨星。","无穷宇宙无穷事，一笑山城打六更。"]},{"t":"鹧鸪天 薄命妾辞","f":"曲","c":["一日春光一日深。","眼看芳树绿成阴。","娉婷卢女娇无柰，流落秋娘瘦不禁。","霜塞阔，海烟沈。","燕鸿何地更相寻。","早教会得琴心了，醉尽长门买赋金。"]},{"t":"鹧鸪天 薄命妾辞","f":"曲","c":["颜色如花画不成。","命如叶薄可怜生。","浮萍自合无根蒂，杨柳谁教管送迎。","云聚散，月亏盈。","海枯石烂古今情。","鸳鸯只影江南岸，肠断枯荷夜雨声。"]},{"t":"鹧鸪天 薄命妾辞三首","f":"曲","c":["复幕重帘十二楼。","而今尘土是西州。","香云已失金钿翠，小景犹残画扇秋。","天也老，水空流。","春山供得几多愁。","桃花一簇开无主，尽著风吹雨打休。"]},{"t":"喜春来","f":"曲","c":["梅残玉靥香犹在，柳破金梢眼未开。","东风和气满楼台，桃杏拆，宜唱喜春来。"]},{"t":"玉楼春","f":"七言律诗","c":["楚娘最瘦腰围小，会看新声歌水调。","已看天上驻行云，更向花间留晚照。","倾城不博嫣然笑，剩破千金犹恨少。","少年恰是惜春时，第一莫教容易了。"]},{"t":"鹧鸪天 其二 宿赵州","f":"曲","c":["绿袖垂肩士女图。","艳歌还似转莺雏。","一春杨柳吹绵后，五月榴花照眼初。","明画烛，倒金壶。","使君晓夙宴西湖。","老来忘却行云梦，犹要春风醉后扶。"]},{"t":"饮酒五首 其二","f":"五言律诗","c":["去古日已远，百伪无一真。","独馀醉乡地，中有羲皇淳。","圣教难为功，乃见酒力神。","谁能酿沧海，尽醉区中民。"]},{"t":"饮酒五首 其三","f":"五言律诗","c":["利端始萌芽，忽复成祸根。","名虚买实祸，将相安足论。","驱驴上邯郸，逐兔出东门。","离官寸亦乐，里社有拙言。"]},{"t":"饮酒五首 其四","f":"五言律诗","c":["万事有定分，圣智不能移。","而于定分中，亦有不测机。","人生桐叶露，见日忽已晞。","唯当饮美酒，傥来非所期。"]},{"t":"饮酒五首 其五","f":"五言律诗","c":["此饮又复醉，此醉更酣适。","徘徊云间月，相对澹以默。","三更风露下，巾袖警微湿。","浩歌天壤间，今夕知何夕？"]},{"t":"后饮酒五首 其一","f":"五言古诗","c":["少日不能觞，少许便有馀。","比得酒中趣，日与杯杓俱。","一日不自浇，肝肺如欲枯。","当其得意时，万物寄一壶。","作病知奈何，妾妇良区区。","但愧生理废，饥寒到妻孥。","吾贫盖有命，此酒不可无。"]},{"t":"后饮酒五首 其二","f":"五言古诗","c":["金丹换凡骨，诞幻若无实。","如何杯杓间，乃有此乐国。","天生至神物，与世作酣适。","岂曰无妙理，滉漾莫容诘。","康衢吾自乐，何者为帝力。","大笑白与刘，区区颂功德。"]},{"t":"后饮酒五首 其三","f":"五言律诗","c":["客从崧少来，贻我招隐诗。","为言学仙好，人间竟何为？","一笑顾客言，神仙非所期。","山中如有酒，吾与尔同归。"]},{"t":"后饮酒五首 其四","f":"五言古诗","c":["酒中有胜地，名流所同归。","人若不解饮，俗病从何医。","此语谁所云？","吾友田紫芝。","紫芝虽吾友，痛饮真吾师。","一饮三百杯，谈笑成歌诗。","九原不可作，想见当年时。"]},{"t":"后饮酒五首 其五","f":"五言古诗","c":["饮人不饮酒，正自可饮泉。","饮酒不饮人，屠沽从击鲜。","酒如以人废，美禄何负焉。","我爱靖节翁，于酒得其天。","庞通何物人？","亦复为陶然。","兼忘物与我，更觉此翁贤。"]},{"t":"麦叹","f":"五言古诗","c":["借地乞麦种，徼倖今年秋。","乞种尚云可，无丁复无牛。","田主好事人，百色副所求。","盻盻三百斛，宽我饥寒忧。","我梦溱南川，平云绿油油。","起来望河汉，旱火连东州。","四月草不青，吾种良谩投。","田间一太息，此岁何时周。","向见田父言，此田本良畴。","三岁废不治，种则当倍收。","如何落吾手，羊年变鸡猴。","身自是旱母，咄咄将谁尤。","人满天地间，天岂独吾雠。","正以赋分薄，所向因拙谋。","不稼且不穑，取禾亦何繇。","办作高敬通，恶雨将漂流。","吾贫有滥觞，贤达未始羞。","单衣适至骭，一剑又蒯缑。","焉知寄食饿，不取丞相侯。","作诗以自广，时用商声讴。"]},{"t":"丰山怀古","f":"五言古诗","c":["丰山一何高，古屋苍烟重。","开门望吴楚，鸟去天无穷。","连山横巨鳌，白水亘长虹。","川原郁佳气，自古南都雄。","炎精昔季兴，卧龙起隆中。","落落出奇策，言言揭孤忠。","时事有可论，生晚恨不逢。","汉贼不两立，大义皎日同。","吴人操等耳，忍与分河潼。","夺操而与权，何以示至公。","一民汉遗黎，尺地汉故封。","守民及守土，天地与相终。","不能禦寇雠，顾以寇自功。","既异鸿沟初，又非列国从。","一券捐半产，二祖宁汝容。","端本一已失，孤唱谁当从？","至今有遗恨，庙柏号阴风。","旧闻清泠渊，天籁如撞钟。","山径野人语，诞幻欺孩童。","开元有乱阶，鹿饮温泉宫。","黄猿何为者，乃尔能啸凶。","乾坤之大音，久郁理当通。","清箱旦夕落，伫尔惊群聋。"]},{"t":"乙酉六月十一日雨","f":"五言古诗","c":["一旱近两月，河洛东连淮。","骄阳佐大火，南风卷黄埃。","草树青欲乾，四望令人哀。","时时怪事发，雨雹如李梅。","我梦天河翻，崩腾走云雷。","今日复何日？","駃雨东南来。","元气淋漓中，焦卷意已回。","良苗与新颖，郁郁无边涯。","书生如老农，苦乐与之偕。","闾阎闻吉语，一笑心颜开。","酉年酒如浆，乾溢安能灾。","惟当作高廪，多具尊与罍。","家人笑问我，君用安在哉！"]},{"t":"观淅江涨","f":"曲","c":["一旱千里赤，一雨垣屋败。","淅故以江名，暴与众壑会。","初惊沙石卷，稍觉川谷隘。","雷风入先驱，大块供一噫。","千帆鼓前浪，万马接后派。","崩崖不暇顾，拔木无留碍。","凭陵如藉势，洄洑各有态。","平分乍舒徐，怒触忽碎坏。","云蒸楚树杪，雪映商岭背。","髣髴千丈潮，恍与海门对。","佽飞斗蛟鳄，燃犀出鳞介。","阳侯富阴族，万首露光怪。","翠蕤澹偃蹇，钲鼓乱?磕。","永怀疏凿力，重叹神禹大。","乾坤海为壑，未碍变横溃。","纳污非无处，流恶聊自快。","投诗与龙盟，涤荡烦一再。"]},{"t":"鹳雀崖北龙潭","f":"五言古诗","c":["层崖閟顽阴，水木深以阻。","湍声半空落，汹汹如怒虎。","风生木叶脱，魄动不敢语。","何年浑沌窍，灵物此栖处。","初从一线溜，开凿到神禹。","云雨鼓飞浪，喷薄齐万弩。","藏珠骊龙颔，百斛快一吐。","油油入无底，细散不濡缕。","归藏海有穴，汎溢愁下土。","南峰天一柱，万古镇幽府。","江山有奇探，落景迫行旅。","多惭茹芝人，终年看飞雨。"]},{"t":"五松平","f":"五言古诗","c":["竹港晨露白，石门秋气寒。","湍流落涧壑，细路深茅菅。","江平白石出，竟日沿清湾。","四顾不见人，山鸟时閒关。","苍崖入地底，烟霭青漫漫。","力尽不能过，却坐空长叹。","青天白云间，可望不可攀。","虚名竟何得，行路乃尔难。"]},{"t":"赠答杨焕然","f":"五言古诗","c":["诗亡又已久，雅道不复陈。","人人握和璧，燕石谁当分？","关中杨夫子，高诲世所闻。","十年玄尚白，藜藿甘长贫。","有来河水篇，四海付斯文。","斯文有定在，桓生知子云。","古来知己难，万里犹比邻。","千人国中和，要非心所亲。","东楚西南秦，望君劳我神。","相逢不得语，别去徒殷勤。","白云不可赠，相思秋复春。"]},{"t":"送诗人李正甫","f":"五言古诗","c":["阳和入枯株，霭霭含芳津。","山头太古石，不与万物春。","朝从木客游，暮将山鬼邻。","紫芝仅盈掬，幽兰不克纫。","青云入长吁，肝胆空轮囷。","我尝读君诗，天趣触眼新。","秦游得豪宕，晋产馀真淳。","怒虎不受唾，骇鹿未易驯。","安坐谁不如？","半生走逡巡。","苍苍不可问，藐藐谁当亲？","青山碾为尘，白日无閒人。","空歌东野曲，不救西州贫。"]},{"t":"放言","f":"五言古诗","c":["韩非死孤愤，虞卿著穷愁。","长沙一湘累，郊岛两诗囚。","人生定能几，肺肝日相雠。","井蛙奚足论，裈虱良足羞。","正有一朝乐，不偿百年忧。","古来帝王师，或从赤松游。","大笑人间世，起灭真浮沤。","曾是万户封，不博一掉头。","有来且当避，未至吾何求。","悠悠复悠悠，大川日东流。","红颜不暇惜，素发忽已稠。","我欲升嵩高，挥杯劝浮丘。","因之两黄鹄，浩荡观齐州。"]},{"t":"黄公庙","f":"五言古诗","c":["羁客无恒居，六月走长路。","清风黄公祠，地古欣所遇。","剑飞素灵哭，龙跃云雨赴。","堂堂文成君，谈笑取帝傅。","功名要有命，阴相果何预。","谁谓圯上人，异事惊竹素。","河清不可俟，筋力疲世故。","袖间一编书，尘埃叹迟暮。"]},{"t":"学东坡移居八首 其一","f":"五言古诗","c":["谁谓我屋宽？","寝处无复馀。","谁谓我屋小？","十口得安居。","南荣坐诸郎，课诵所依于。","西除著僮仆，休沐得自如。","老我于其閒，兀兀穷朝晡。","起立足欠伸，偃卧足展舒。","窗明火焙煖，似欲忘囚拘。","屋前有隙地，客舍不可无。","花阑及菜圃，次第当耘锄。","东野载家具，家具少于车。","我贫不全贫，尚有百本书。"]},{"t":"学东坡移居八首 其二","f":"五言古诗","c":["故书堆满床，故物贮满箱。","浑浑商宝鬲，累累汉铜章。","杖饰昭敬恭，严卯诃瘅刚。","雷文绕杖节，兽面出佩璜。","私印刻王尊，玉斗蛟龙翔。","逸少留半纸，鱼网非硬黄。","亦有昙首帖，不辨作雁行。","雪景睿思物，宣政旧所藏。","晋公古渔父，浩歌濯沧浪。","因观宫骑图，卧驼识提囊。","溪石含馀润，奚墨凝幽香。","南荣挂风响，云裾佩铿锵。","镜背先秦书，八字环中央。","读之三叹息，此日何时光？"]},{"t":"学东坡移居八首 其三","f":"五言古诗","c":["壬辰困重围，金粟论升勺。","明年出青城，瞑目就束缚。","毫釐脱鬼手，攘臂留空橐。","聊城千里外，狼狈何所托？","诸公颇相念，馀粒分凫鹤。","得损不相偿，抔土填巨壑。","一冬不制衣，缯纩如纸薄。","一日仅两食，强半杂藜藿。","不羞蓬累行，粗识瓢饮乐。","敌贫如敌寇，自信颇亦悫。","儿啼饭箩空，坚阵为屡却。","沧溟浮一叶，渺不见止泊。","五穷果何神？","为戏乃尔虐。"]},{"t":"学东坡移居八首 其四","f":"五言古诗","c":["旧隐嵩山阳，笋蕨丰馈饷。","新斋淅江曲，山水穷放浪。","乾坤两茅舍，气压华屋上。","一从陵谷变，归顾无复望。","渔樵忆往还，风土梦间旷。","恍如悟前身，姓改心不忘。","去年住佛屋，尽室寄寻丈。","今年僦民居，卧榻碍盆盎。","静言寻祸本，正坐一出妄。","青山不能隐，俯首入羁鞅。","巢倾卵随覆，身在颜亦强。","空悲龙髯绝，永负鱼腹葬。","置锥良有馀，终身志悲怆。"]},{"t":"学东坡移居八首 其五","f":"五言古诗","c":["国史经丧乱，天幸有所归。","但恨后十年，时事无人知。","兴废属之天，事岂尽乖违。","传闻入雠敌，秖以兴骂讥。","老臣与存亡，高贤死兵饥。","身死名亦灭，义士为伤悲。","哀哀淮西城，万夫甘伏尸。","田横巨擘耳，犹为谈者资。","我作南冠录，一语不敢私。","稗官杂家流，国风贱妇诗。","成书有作者，起本良在兹。","朝我何所营，暮我何所思。","胸中有茹噎，欲得快吐之。","湿薪烟满眼，破砚冰生髭。","造物留此笔，吾贫复何辞。"]},{"t":"学东坡移居八首 其六","f":"五言古诗","c":["此州多寓士，论年悉肩随。","风波同一舟，奚必骨肉为。","倪家莲花白，每酿必见贻。","季昌妙琴事，足以相娱嬉。","郭侯家多书，篇帙得遍窥。","赵子笃于学，间以问所疑。","王生旧邻舍，穷达心不移。","千里访存殁，十口分寒饥。","独有仲通甫，天马不可羁。","直以论诗文，稍稍窥藩篱。","永怀王与李，朔漠行当归。","书来闻吉语，报我脱絷维。","惭非一狐腋，不直五羖皮。","我作野史亭，日与诸君期。","相从一笑乐，来事无庸知。"]},{"t":"济南庙中古桧同叔能赋","f":"五言古诗","c":["亭亭祠宫桧，郁郁上云雨。","扶持几来年，造物心独苦。","青馀玉川润，根入铁岸古。","虽含栋梁姿，斤斧安得取。","沇洑地中久，骇浪思一鼓。","天柱屹不移，水国奠平土。","乾坤此神物，甲乙存世谱。","濑乡留耳孙，阙里传鼻祖。","秦松徒自污，蜀柏聊共数。","会待十抱成，兹焉重摩拊。"]},{"t":"别李周卿二首 其一","f":"五言古诗","c":["行路涩于棘，单车望千山。","歌君归云曲，清涕留馀潸。","六年河朔州，动辄得谤讪。","惟君笃高义，日来款柴关。","古交松柏心，今交桃李颜。","古人去不返，古道挽不还。","相思一尊酒，幽恨寄山间。"]},{"t":"别李周卿二首 其二","f":"五言古诗","c":["城居日蛙黾，局促复局促。","去作山中客，放浪谁检束。","溪光淡于冰，山骨净如玉。","怀我同心人，团茅住深竹。","垂纶鲜可食，种秫酒亦足。","石坛三万丈，醉眼天一粟。","安得万里风，相从两黄鹄。"]},{"t":"九日读书山用陶诗露凄暄风息气清天旷明为韵赋十诗 其一","f":"五言古诗","c":["行帐适南下，居人局庭户。","城中望青山，一水不易渡。","今朝川涂静，偶得展衰步。","荡如脱囚拘，广莫开四顾。","半生无根著，筋力疲世故。","大似丁令威，归来叹墟墓。","乡闾丧乱久，触目异平素。","枌榆虽尚存，岁晏多霜露。"]},{"t":"九日读书山用陶诗露凄暄风息气清天旷明为韵赋十诗 其二","f":"五言古诗","c":["山腰抱佛刹，十里望家园。","亦有野人居，层崖映柴门。","昔我东岩君，曾此避尘喧。","林泉留杖屦，岁月归琴尊。","翁今为飞仙，过眼几寒暄。","苍苍池上柳，青衫见诸孙。","疏灯照茅屋，新月入颓垣。","依依览陈迹，恻怆不能言。"]},{"t":"九日读书山用陶诗露凄暄风息气清天旷明为韵赋十诗 其三","f":"五言古诗","c":["宇宙有此山，阅世过鸟疾。","何人不此游，名姓宁复识。","兹辰世所重，前代多盛集。","柴桑有故事，□谢留俊笔。","并数孟与桓，此外谁记忆。","人生百年内，踏地皆陈迹。","独惟我辈人，兴怀念今昔。","山林与泉壤，自古长太息。"]},{"t":"九日读书山用陶诗露凄暄风息气清天旷明为韵赋十诗 其四","f":"五言古诗","c":["往年在南都，閒閒主文衡。","九日登吹台，追随尽名卿。","酒酣公赋诗，挥洒笔不停。","蛟龙起庭户，破壁春雷轰。","堂堂髯御史，痛饮益精明。","亦有李与王，玉树含秋清。","我时最后来，四座颇为倾。","今朝念存没，壮心徒自惊。"]},{"t":"九日读书山用陶诗露凄暄风息气清天旷明为韵赋十诗 其五","f":"五言古诗","c":["我在正大初，作吏淅江边。","山城官事少，日放淅江船。","菊潭秋花满，紫稻酿寒泉。","甘腴入小苦，幽光出清妍。","归路踏明月，醉袖风翩翩。","父老遮我留，谓我欲登仙。","一别半山亭，回头馀十年。","江山不可越，目断西南天。"]},{"t":"九日读书山用陶诗露凄暄风息气清天旷明为韵赋十诗 其六","f":"五言古诗","c":["吾山一何高，清凉屹相望。","龙头出白塔，佛屋压青嶂。","云光见秋半，旭日发豪相。","峨峨宝楼阁，金界俨龙象。","乡曲二十年，香火阙瞻向。","金花香绵芊，梦想云雨上。","福田行欲近，重为诗酒障。","终当陟层巅，放眼天宇旷。"]},{"t":"梨花海棠二首 其一","f":"五言古诗","c":["梨花如静女，寂寞出春暮。","春工惜天真，玉颊洗风露。","素月淡相映，萧然见风度。","恨无尘外人，为续雪香句。","孤芳忌太洁，莫遣凡卉妒。"]},{"t":"梨花海棠二首 其二","f":"五言古诗","c":["妍花红粉妆，意态工媚妩。","窈窕春风前，霞衣欲轻举。","金盘渺华屋，国艳徒自许。","依依如有意，脉脉不得语。","诗人太冷落，愁绝残春雨。"]},{"t":"题张左丞家范宽秋山横幅","f":"五言古诗","c":["层崖閟长阴，细径缘绝巘。","梯云阑干峻，廓廓清眺展。","斜阳半天赤，飞鸟大江远。","清霜张秋气，草树生意剪。","风雪斫坚敌，旗旆纷仆偃。","峥嵘峰峦出，莽苍林薄晚。","盘盘范家笔，老怀寄高蹇。","经营入惨淡，得处乃萧散。","嵩丘动归兴，突兀青在眼。","何时卧云身，团茅遂疏懒。"]},{"t":"宿张靖田家","f":"五言古诗","c":["川涂尽坡陀，岭路入荒梗。","微茫望烟火，向背得庐井。","残民安朴陋，倦客喜幽屏。","儿童闻叩扉，租吏有馀警。","两崖纷丛薄，砂石立顽犷。","湍流落空嵌，百折不容骋。","山深饶风露，夜气凄以耿。","园花淡相望，边月空照影。","深居苦不早，素发忽垂领。","谁谓林野人？","兹焉惜清景。"]},{"t":"宝严纪行","f":"五言古诗","c":["阴崖转清深，秋老木坚瘦。","城居望已远，步觉脱氛垢。","宝严夙所爱，丈室方再叩。","曛黑才入门，径就石泉漱。","遥遥金门寺，宝焰出岩窦。","我岂无尽公，昔见今乃又。","同来二三子，寝饭故相就。","况有杜紫微，琴筑终雅奏。","曈曈上初日，深樾炯穿漏。","逶迤陟西巘，万景若迎候。","绝壁三面开，仰看劳引脰。","两山老突兀，屹立柱圆覆。","诸峰出头角，随起随偃仆。","不可无烟霞，朝暮为先后。","横亘连巨鳌，飞堕集灵鹫。","九华与奇巧，五老失浑厚。","想当位置初，遂欲雄宇宙。","太行有谼谷，胜绝无出右。","大似尘外人，眉宇见高秀。","哀湍下绝壑，电激龙怒斗。","崩奔翻雪窖，瑩滑泻琼甃。","穷源得悬流，伟观骇初遘。","仙人宝楼阁，白雨散檐溜。","天孙拂机丝，素锦绚清昼。","永怀登高赋，意匠困驰骤。","窘于游暴秦，百说不一售。","林间太古石，稍复抔饮旧。","已约铭洼尊，细凿留篆籀。","兹山缘未了，僧夏容宿留。","终当丐馀年，奇探尽云岫。"]},{"t":"雁门道中书所见","f":"五言古诗","c":["金城留旬浃，兀兀醉歌舞。","出门览民风，惨惨愁肺腑。","去年夏秋旱，七月黍穟吐。","一昔营幕来，天明但平土。","调度急星火，逋负迫捶楚。","网罗方高悬，乐国果何所。","食禾有百螣，择肉非一虎。","呼天天不闻，感讽复何补。","单衣者谁子？","贩籴就南府。","倾身营一饱，岂乐远服贾。","盘盘雁门道，云涧深以阻。","半岭逢驱车，人牛一何苦！"]},{"t":"同白兄赋瓶中玉簪","f":"五言古诗","c":["畏景众芳歇，仙葩此夷犹。","冰姿出新沐，娟娟倚清秋。","昨梦今见之，风鬟玉搔头。","谁言闺房秀，高情渺林丘。","碧筵古铜壶，一室香四周。","怀人成独咏，远思徒悠悠。"]},{"t":"野史亭雨夜感兴","f":"五言律诗","c":["私录关赴告，求野或有取。","秋兔一寸毫，尽力不易举。","衰迟私自惜，忧畏当谁语。","展转天未明，幽窗响疏雨。"]},{"t":"继愚轩和党承旨雪诗二首 其一","f":"五言古诗","c":["今古几诗人，扰扰剧毛粟。","吾爱陶与韦，泠然扣冰玉。","大雅久不作，闻韶信忘肉。","求音扣寂寞，一叹动邻屋。","水风清鹤梦，月露洗蝉腹。","白头两遗编，吟唱心自足。","谁为起九原？","寒泉荐芳菊。"]},{"t":"继愚轩和党承旨雪诗二首 其二","f":"五言古诗","c":["愚轩具诗眼，论文贵天然。","颇怪今时人，雕镌穷岁年。","君看陶集中，饮酒与归田。","此翁岂作诗，真写胸中天。","天然对雕饰，真膺殊相悬。","乃知时世妆，粉绿徒争妍。","枯淡足自乐，勿为虚名牵。"]},{"t":"寄英禅师师时住龙门宝应寺","f":"五言古诗","c":["我本宝应僧，一念堕儒冠。","多生经行地，树老井未眢。","一穷缚两脚，寸步百里难。","空馀中夜梦，浩荡青林端。","故人今何如？","念子独轻安。","孤云望不及，冥鸿杳难攀。","前时得君诗，失喜忘朝餐。","想君亦念我，登楼望青山。","山中多诗人，杖屦时往还。","但苦诗作祟，况味同酸寒。","清凉诗最圆，往往似方干。","半年卧床席，疟我疥亦顽。","济甫诗最苦，寸晷不识閒。","倾身营一饱，船上八节滩。","安行诗最工，六马鸣和鸾。","郁郁饥寒忧，惨惨日在颜。","老秦诗最和，平易出深艰。","脱身豺虎丛，白发罹茕鳏。","张侯诗最豪，惊风卷狂澜。","窍繁天和泄，外腴中已乾。","城中崔夫子，老笔郁盘盘。","家无儋石储，气压风骚坛。","我诗有凡骨，欲换无金丹。","呻吟二十年，似欲见一斑。","大笑揶揄生，已复不相宽。","爱君梅花篇，入手如弹丸。","爱君山堂句，深静如幽兰。","诗僧第一代，无愧百年间。","思君复思君，恨不生羽翰。","何时溪上石，清坐两蒲团。"]},{"t":"梦归","f":"五言古诗","c":["虚庭霜夜寒，落叶风自扫。","恍如南窗月，坐失西山道。","长安佳丽地，游子自枯槁。","人生家居乐，学稼苦不早。","衡门眼中见，归意满秋草。","夜长梦已尽，愁绝令人老。"]},{"t":"秋蚕","f":"七言古诗","c":["室人筐中无寸缕，一箔秋蚕课诸女。","朝来饲却上马桑，隔簇仍闻竹间雨。","阿容阿璋墨满面，画彻灰城前致语。","上无苍蝇下无鼠，作茧直须如瓮许。","东家追胥守机杼，有桑有税吾犹汝。","官家却少一絇丝，未到打门先自举。"]},{"t":"南溪","f":"七言古诗","c":["南溪酒熟清而醇，北溪梅花发兴新。","前年去年花下醉，今年冷落花应嗔。","梅花娟娟如静女，寂寞甘与荒山邻。","诗人爱花山亦好，幽林穹谷生阳春。","风鬟峨峨一尺云，芳香幽卧如相亲。","山堂夜半北风恶，一点相思愁杀人。"]},{"t":"范宽秦川图","f":"七言古诗","c":["乱山如马争欲前，细路起伏蛇蜿蜒。","秦川之图范宽笔，来从米家书画船。","变化开阖天机全，浓淡覆露清而妍。","云兴霞蔚几千里，著我如在峨眉巅。","西山盘盘天与连，九点尽得齐州烟。","浮云未清白日晚，矫首四顾心茫然。","全秦天地一大物，雷雨澒洞龙头轩。","因山分势合水力，眼底廓廓无齐燕。","我知宽也不办此，渠宁有笔如修椽。","紫髯落落西溪君，长剑倚天冠切云，望之见之不可亲。","元龙未除湖海气，李白岂是蓬蒿人？","爱君恨不识君早，乃今得子胸中秦。","作诗一笑君应闻。"]},{"t":"寄荅溪南诗老辛愿敬之","f":"七言古诗","c":["五年不唤溪南渡，日夕心驰洛西路。","山中今日见君诗，惆怅良辰又相误。","龙蛇大泽变风景，虎豹天门郁烟雾。","丈夫不合把锄犁，青鬓无情忽衰素。","平泉漫作穷愁志，笠泽休题自怜赋。","长安正有五侯鲭，肮脏谁能作楼护？","青灯老屋深蓬蒿，蝙蝠掠面莎鸡号。","剑歌夜半激悲壮，松风万壑翻云涛。","区区墓上曹征西，我知惭愧王东皋。","人生只有一杯酒，螟蛉蜾蠃安能豪。"]},{"t":"西园","f":"七言古诗","c":["西园老树摇清秋，画船载酒芳华游。","登山临水袪烦忧，物色无端生暮愁。","百年此地旃车发，易水迢迢雁行没。","梁门回望绣成堆，满面黄沙哭燕月。","荧荧一炬殊可怜，膏血再变为灰烟。","富贵已经春梦后，典刑犹在靖康前。","当时三山初奏功，三山宫阙云锦重。","璧月琼枝春色里，画阑桂树雨声中。","秋山秋水今犹昔，漠漠荒烟送斜日。","铜人携出露盘来，人生无情泪沾臆。","丽川亭上看年芳，更为清歌尽此觞。","千古是非同一笑，不须作赋拟《阿房》。"]},{"t":"双峰竞秀图为参政杨侍郎赋","f":"七言古诗","c":["红烟霏霏云拂石，山木萧萧山鬼泣。","江岸人家失南北，两峰突兀何许来，元气淋漓洗秋碧。","画家晴景费经营，共爱移山入杳冥。","安得北风吹雨去，倚天长剑看峥嵘。"]},{"t":"二月十五日鹤","f":"七言古诗","c":["九龙冈上玄元祠，人言尊像神所遗。","年年二月降灵鹤，来无定数有定期。","城头晓露生新警，万首望穿云际影。","不知浊世谁下临，只许霜毛见修整。","石坛花落松风冷，戛然长鸣人语定。","百年黧老誇见闻，万里黄冠赴灵应。","只从游骑突重围，城郭并与人民非。","可怜陊殿荒烟里，无复当年丁令威。"]},{"t":"阎商卿还山中","f":"七言古诗","c":["阿卿去月从我来，今日西山成独往。","野人不是城中物，涧饮岩栖梦馀想。","翰林湿薪爆竹声，待诏履穿沾雪行。","兰台从事更閒冷，文书如山白发生。","孤灯静照寒窗宿，北风夜半歌黄鹄。","田家闭门风雪深，梅花开时酒应熟。","半世虚名不疗贫，栖迟零落百酸辛。","凭君莫向山中说，白石清泉笑杀人。"]},{"t":"邓州城楼","f":"七言律诗","c":["邓州城下湍水流，邓州城隅多古丘。","隆中布衣不复见，浮云西北空悠悠。","长鲸驾空海波立，老鹤叫月苍烟愁。","自古江山感游子，今人谁解赋登楼？"]},{"t":"宛丘叹","f":"曲","c":["秦阳陂头人迹绝，荻花茫茫白于雪。","当年万家河朔来，尽出牛头入租帖。","苍髯长官错料事，下考大笑阳城拙。","至今三老背肿青，死为逋悬出膏血。","君不见刘君宰叶海内称，饥摩寒拊哀孤茕。","碑前千人万人泣，父老梦见如平生。","冰霜纨裤渠有策，如我碌碌当何成！","荒田满眼人得耕，诏书已复三年征。","早晚林间见鸡犬，一犁春雨麦青青。"]},{"t":"密公宝章小集","f":"七言古诗","c":["天东长白大宝幢，天河发源导三江。","有木蔽映山朝阳，云谁巢者雏凤凰？","云间吐气日五色，百鸟不敢言文章。","名都盘盘魏大梁，黄金甲第罗康庄。","王家书绝画亦绝，欲与中秘论低昂。","密公书院无丝簧，窗明几洁凝幽香。","元光以后门钥废，文士稍得连壶觞。","客来喜色浮清扬，典衣置酒馀空箱。","生平俊气不易降，眼中俗物都茫茫。","渊明素琴嵇阮酒，妙意所寄谁能量。","在昔武元握乾纲，扶桑为弓射八荒。","猎取大国如驱羊，民风朴鲁资鸷彊，文洽未及武尅刚。","兴陵之孙越王子，天以人瑞归明昌。","十三执经侍帝傍，十八健笔凌阿房。","撑肠文字五千卷，灵台架构森铺张。","高阳苗裔袭众芳，胡不置之贡玉堂。","袖中正有活国手，地下才得修文郎。","悲风萧萧吹白杨，丘山零落可怜伤。","承平故态耿犹在，拂拭宝墨生辉光。","恰似如庵连榻坐，一瓯春露澹相忘。"]},{"t":"送张君美往南中","f":"七言古诗","c":["南朝词臣北朝客，栖迟零落无颜色。","阳平城边握君手，不似铜驼洛阳陌。","去年春风吹雁回，今年雁逐秋风来。","春风秋风雁声里，行人日暮心悠哉。","长江大浪金山下，吴儿舟船疾于马。","西湖十月赏风烟，想得新诗更潇洒。"]},{"t":"赠休粮张鍊师","f":"七言律诗","c":["金砂雾散风雨疾，一点黄金铸秋橘。","中林宴坐人不知，野鹿衔花蜂课蜜。","富儿盘馔罗膻荤，扰扰飞蝇复聚蚊。","见说西山好薇蕨，一枝青竹愿随君。"]},{"t":"读书山雪中","f":"七言古诗","c":["前年望归归不得，去年中途脚无力。","残生何意有今年，突兀家山堕眼前。","东家西家百壶酒，主人捧觞客长寿。","先生醉袖挽春回，万落千村满花柳。","山灵为渠也放颠，世界幻入兜罗绵。","似嫌衣锦太寒乞，别作玉屑妆山川。","人言少微照乡井，准备黄云三万顷。","何人办作陈瑩中，来与先生共炊饼。"]},{"t":"蟾池","f":"七言古诗","c":["老蟆食月饱复吐，天公一目频年瞽。","下界新增养蟾户，玉斧谁怜修月苦。","郡国蟾池知几所，碧玉清流水仙府。","小蟾徐行腹如鼓，大蟾张颐怒于虎。","渠家眉间有黄乳，膏梁大丁正须汝。","何人敢与月复雠，疾过池头不容语。","向来属私今属官，从今见蟆当好看，爬沙即上青云端。"]},{"t":"高门关","f":"七言古诗","c":["高门关头霜树老，细路千山万山绕。","乱馀村落不见人，雪霰霏霏暗清晓。","莘川百里如掌平，閒田满眼人得耕。","山中树艺亦不恶，谁遣多田知姓名。","许李申杨竟何得？","只今惟有石滩声。"]},{"t":"甲辰秋洛阳得黄葵子种之南庵明年夏六月作花佛经所谓阎浮檀金明净柔软令人爱乐者此花可以当之因为赋长韵予方以病止酒故卒章及之","f":"七言古诗","c":["芳蕤浥露娇黄湿，五叠湘裙轻襞积。","晨妆午醉一日间，白白红红总狼藉。","上阳宫女要头冠，摹写虽工破的难。","看来明净复柔软，花中乃有阎浮檀。","千里移根洛阳陌，主人不饮谁看客？","乞与金杯自倾侧，明年为渠当举白。"]},{"t":"云峡","f":"七言古诗","c":["石盆清冷贮秋水，水面苍烟飞不起。","一堆寒碧几研间，宝气峥嵘插箕尾。","山中雪浪空影像，长安鹦鹉犹纨绮。","枉著奇章甲乙中，槁项才堪把耕来。","不知天壤此尤物，鬼刻神劖通有几。","薰蒸似欲出泉脉，瑩滑定应凝石髓。","剥裂雯华渍月秋，辛苦诗仙费摹拟。","车箱箭筈连西东，仇池百穴总玲珑。","飞堕不嫌灵鹫小，奇探已觉太湖空。","故都乔木今如此，梦想熙春百花里。","膏血纲船枯九州，亡国愁颜为谁洗？","主人天质粹以温，天然与山作知闻。","退食从容北窗卧，今古起灭真浮云。"]},{"t":"云岩","f":"七言古诗","c":["壶中九华玉孱颜，紫烟著水往复还。","小窗虚明淡相对，不数汉宫铜博山。","会稽禹穴深无底，宝石偷来定山鬼。","一堆寒碧殊不凡，满谷春云更堪喜。","阿欣秀发见眉宇，小杜才情沦骨髓。","摩挲不作几上看，缭白纡青便千里。","浑沌日凿馀空嵌，漏天蒸湿饶风岚。","世外元无种香国，海南真有补陁岩。","观州爱玩频湔祓，民部平生几熏沐。","藏舟夜壑未厌深，竟作新轩坐中物。","一天星斗入金尊，翠射娉婷自有人。","只欠宣和郑先觉，为君留写五湖真。"]},{"t":"天涯山","f":"七言古诗","c":["九州上游推大卤，独恨山形颇椎鲁。","天涯一峰今日看，快似昂头出环堵。","何年气母此融结，鬼凿神劖未奇古。","八窗玲珑透朝日，洞穴惨澹藏雷雨。","名花锦石粲可喜，乞与云烟相媚妩。","半空掷下金芙蕖，想得飞来自玄圃。","传闻绝顶更灵异，云是清都群玉府。","五云飞步吾未能，风袂泠泠已轻举。","东州死爱华不注，向在陋邦何足数。","敬亭不著谢宣城，断岸何缘比天姥。","酒船何时朝复暮，倒卷滹沱浣尘土。","唤起山灵搥石鼓，汉女湘妃出歌舞。","诗狂他日笑遗山，饭颗不妨嘲杜甫。"]},{"t":"世宗御书田不伐望月婆罗门引先得楚字韵","f":"七言古诗","c":["瑶光楼前按歌舞，桂树秋香月三五。","白头谁解记开元，四海欢声自箫鼓。","两都秋色皆乔木，三月阿房已焦土。","天人亦有离别情，可是田郎心独苦。","承平旧物《霓裳》谱，宝气晖晖映千古。","银桥望极竟不归，灭没燕鸿下平楚。"]},{"t":"赠别孙德谦","f":"七言律诗","c":["津桥垂杨雪花白，挽断春衫苦留客。","西河一雨春意浓，绝似铜驼洛阳陌。","河亭轰醉卧春风，到手金杯不放空。","鹊山一带伤心碧，羡杀孙郎马首东。"]},{"t":"太原赠张彦远","f":"七言古诗","c":["并州城边十月末，清霜棱棱风入骨。","因君夜话吴江春，酒光潋滟金杯滑。","閒閒骑鲸去灭没，当年爱君俊于鹘。","平生我亦识翁人，惆怅流年如电抹。","官家新筑文昌台，苍生不忧堕巅崖。","眼看东阁奇士满，如君岂得藏蒿莱？","晨鸡未鸣子当发，明星煌煌大于月，野夫一笑冠缨绝。"]},{"t":"鹿泉新居二十四韵","f":"七言古诗","c":["土门西边井陉渡，野日荒荒下汀树。","榆关石岭都几程，客梦往往迷归路。","尘埃风雨半生过，尽著筋骸支世故。","宁州假馆又两年，未保东来不西去。","山城百家家有山，觌面呈山谁一顾。","卖书买得吕氏园，不谓全山举相付。","北崖老作土灰色，拥肿形模一夸父。","娟娟正有小峨眉，却立不容亲杖屦。","就中抱犊尤峭拔，望见韩山即攀附。","韩王砦头四望阔，全赵米如才数聚。","眼中麾盖天上来，泜水鼓旗纷偃仆。","汉家威灵万万古，石子连冈犹虎距。","夏秋众壑会鹿泉，浩浩湍声泻馀怒。","西南诸峰不知数，荡海鲲䲔尻背露。","霏烟空翠有无中，百态阴晴变朝暮。","灵岩龙泉曾一到，独欠封龙展衰步。","学仙不爱徐童花，李相书龛心所慕。","平生怀抱向山尽，老气崔嵬如有助。","岩居枯寂朝市喧，喧寂两閒差有趣。","得行固愿留不恶，流坎且当随所遇。","何曾万钱何用许，方丈有山容下箸。","管城初无食肉相，黄帽非供折腰具。","明年高筑野史亭，天已安排看山处。","多惭不及谢宣城，标出敬亭天一柱。"]},{"t":"王学士熊岳图","f":"七言古诗","c":["洗蔘池水甜于蜜，玉堂仙翁发如漆。","膝前文度更风流，尽卷风流入诗笔。","长松手种欲摩天，海岳楼空落照边。","古来说有辽东鹤，仙语星星谁为传。","五百年间异人出，却将锦绣裹山川。"]},{"t":"去岁君远游送仲梁出山","f":"楚辞体","c":["去岁君远游，今年客他州。","青天万古一明月，只与行人生暮愁。","问君游何许，情多地僻兮遍处处。","金鞭断折骐骥死，万里长鸿思一举。","忆初识子梁王台，清风入座无纤埃。","华岳峰尖见秋隼，金眸玉爪不凡材。","西园日晴花满烟，五云楼阁三山巅。","玉树瑶林照春色，青钱白璧买芳年。","三年一梦南阳道，汴水迢迢入秋草。","挐云心事人不知，千首新诗怨枯槁。","破屋仰见星，疏衾风露清。","匣中有长剑，为君鸣不平。","泥涂久辱思一濯，去去举足皆清泠。","邓州大帅材望雄，爱客不减奇章公。","军中宴酣笳鼓竞，银烛吐焰如长虹。","幕中多士君又往，谈笑已觉南夷空。","东州春回十月后，梅花分香入春酒。","平生得意钦与京，青眼高歌望君久。","淅江南下青沄沄，石门细路苍烟屯。","五松平头白日静，千山万山如乱云。","菊源不逐时事改，芝岭自与商颜邻。","他日想思一回首，渔舟时问武陵人。"]},{"t":"此日不足惜","f":"曲","c":["此日不足惜，此酒不可无。","颇怪昌黎公，亦复为世儒。","天生至神物，与人作华胥。","一酌舌本强，二酌燥吻濡。","三酌动高兴，四酌色敷腴。","连绵五六酌，枯肠润如酥。","眼花耳热后，万物寄一壶。","十酌未渠央，百觚亦奚拘。","人生一世间，忽若过隙驹。","有酒不解饮，问君谁与娱。","君不见东家骑■李，胆满六尺躯。","万言黄石策，八阵夔州图。","酒酣起舞不称意，长吁青云指夷吾。","又不见西家紫髯郎，老气雄万夫。","狂歌饮燕市，击筑声呜呜。","倚天长剑插少室，颇欲四海皆东湖。","鹰扬虎视今焉如，河山永隔黄公垆。","衔杯直待秋井塌，青苔白骨怜君愚。","少年觅计生白须，扪参历井无危途。","荣不满睫良区区，就令一朝便得八州督，争似高吟大醉穷朝晡。","馀名安得润枯骨，四十岂不知头颅。","此日不足惜，此酒不可无。","太虚为室月为烛，醉倒不用春风扶。"]},{"t":"虎害","f":"曲","c":["北山虎有穴，南山虎为群。","目光如电声如雷，倚荡起伏山之垠。","百人一饱不留骨，败衣坠絮徒纷纷。","空谷绝樵声，长路无行尘。","呀呀垂涎口，眈眈阚城闉。","天地岂不仁，社公岂不神。","哀哀太山妇，叫断秋空云。","可怜封使君，生不治民死食民。","世上无复裴将军，北平太守今何人？"]},{"t":"寄赵宜之","f":"曲","c":["大城满豺虎，小城空雀鼠。","可怜河朔州，人掘草根官煮弩。","北人南来向何处，共说莘川今乐土。","莘川三月春事忙，布谷劝耕鸠唤雨。","旧闻抱犊山，摩云出苍棱。","长林绝壑人迹所不到，可以避世如武陵。","煮橡当果谷，煎术甘饴饧。","此物足以度荒岁，况有麋鹿可射鱼可罾。","自我来嵩前，旱乾岁相仍。","耕田食不足，又复违亲朋。","三年西去心，笼禽念飞腾。","一瓶一钵百无累，恨我不如云水僧。","崧山几来层，不畏登不得，但畏不得登。","洛阳一昔秋风起，羡杀云间张季鹰。"]},{"t":"纪子正杏园燕集","f":"曲","c":["纪翁种杏城西垠，千株万株红艳新。","今年寒食好天色，晓气郁郁含芳津。","天公自爱此花好，朝薰暮染烦花神。","融霞晕雪一倾倒，非烟非雾非卿云。","未开何所似，乳儿粉妆深绛唇。","能啼能笑痴复騃，画出百子元非真。","半开何所似，里中处女东家邻。","阳和入骨春思动，欲语不语时轻颦。","就中烂熳尤更好，五家合队虢与秦。","曲江江头看车马，十里罗绮争红尘。","阳平一邑多诗豪，主人买酒邀众宾。","花时有成约，恨少杨子张吾军。","落花著衣红缤纷，四坐惨澹伤精魂。","花开花落十日耳，对花不饮花应嗔。","爱花常苦得花晚，争教行乐无閒身。","芳苞一破不更合，且看锦树烘残春。"]},{"t":"王黄华墨竹","f":"曲","c":["古来画竹尊右丞，东坡敛袂不敢评。","开元石本出摹写，燕市骏骨留空名。","亦有文湖州，画意不画形。","一为坡所赏，四海知有筼筜亭。","深衣幅巾老明经，老死不敢言纵横。","岂知辽江一派最后出，运斤成风刃发硎。","雪溪仙人诗骨清，画笔尚馀诗典刑。","月中看竹写秋影，清镜平明白发生。","娟娟略似萱草咏，落落不减丛台行。","千枝万叶何许来，但见醉帖字欹倾。","君不见忠恕大篆草书法，赵生怒虎噀墨成。","至人技进不名技，游戏亦复通真灵。","百年文章公主盟，屏山见之跽且擎。","声光旧塞天壤破，议论今著儿曹轻。","有物于此鸣不平，悲邪啸邪谁汝令？","只恐破窗风雨夜，怒随雷电上青冥。"]},{"t":"九月七日梦中作诗续以末后二句","f":"曲","c":["桃花红深李花白，昨日成团今日拆。","歌声满耳何处来，杨柳青旗洛阳陌。","拊君背，握君手。","朝钟暮鼓无了期，世事于人竟何有！","青青镜中发，忽忽成白首。","六国印，何如负郭二顷田，千载名，不及即时一杯酒。"]},{"t":"南冠行","f":"曲","c":["南冠累累渡河关，毕逋头白乃得还。","荒城雨多秋气重，颓垣败屋深茅菅。","漫漫长夜浩歌起，清涕晓枕留馀潸。","曹侯少年出纨绮，高门大屋垂杨里。","诸房三十侍中郎，独守残编北窗底。","王孙上客生光辉，竹花不实鹓雏饥。","丝桐切切解人语，海云唤得青鸾飞。","梁园三月花如雾，临锦芳华朝复暮。","阿京风调阿钦才，晕碧裁红须小杜。","长安张敞号眉妩，吴中周郎知曲误。","香生春动一诗成，瑞露灵芝满窗户。","鱼龙吹浪三山没，万里西风入华发。","无人重典鹔鹴裘，展转空床卧秋月。","宝镜埋寒灰，郁郁万古不可开。","龙剑出地底，青天白日驱云雷。","层冰千里不可留，离魂楚些招归来。","生不愿朝入省暮入台，愿与竹林嵇阮同举杯。","郎食猩猩唇，妾食鲤鱼尾，不如孟光案头一盂水。","黄河之水天上流，何物可煮人间愁。","撑霆裂月不称意，更与倒翻鹦鹉洲。","安得酒船三万斛，与君轰醉太湖秋。"]},{"t":"题刘紫微尧民野醉图","f":"曲","c":["苍苔浊酒同歌呼，白须红颊醉相扶。","尧时皇质未全散，不论朝野皆欢虞。","望云云非云，就日日非日。","先秦迂儒强解事，极口誉尧初未识。","尧民与酒同一天，此外更谁为帝力。","仙老曾经甲子年，戏将陈迹画中传。","山川淳朴忽当眼，回望康衢一慨然。","不见只今汾水上，田翁鞭背出租钱。"]},{"t":"下黄榆岭","f":"曲","c":["北崖玄武暮，黕黑如积铁。","东厓劫火馀，绚烂开锦缬。","就中岭头一峰凸朴奇，剩费寒云几千叠。","摩围可望不可到，青壁无梯猿叫绝。","林烟日射彩翠新，跬步疑有黄金阙。","画工胸次墨汁满，那得冰壶贮秋月。","直须潮阳老笔回万牛，露顶张颠挥醉帖。","石门细路无涧泉，行人饥渴挽不前。","辛苦黄榆三十里，岂知却有看山缘。"]},{"t":"驱猪行","f":"曲","c":["沿山莳苗多费力，办与豪猪作粮食。","草庵架空寻丈高，击版摇铃闹终夕。","孤犬无猛噬，长箭不暗射。","田夫睡中时叫号，不似驱猪似称屈。","放教田鼠大于兔，任使飞蝗半天黑。","害田争合到渠边，可是山中无橡术。","长牙短喙食不休，过处一抹无禾头。","天明陇亩见狼藉，妇子相看空泪流。","旱乾水溢年年日，会计收成才什一。","资身百倍粟豆中，儋石都能几钱直。","儿童食糜须爱惜，此物群猪口中得。","县吏即来销税籍。"]},{"t":"游龙山","f":"曲","c":["曩予魏大梁，得交此州雷与刘。","自闻两公誇南山，每恨南海北海风马牛。","老龙面目今日始一见，更信造物工雕锼。","是时山雨晴，平田绿油油。","并山凉气多，况得通深幽。","山泉谷口出迎客，石罅戛击琳琅球。","蜿蜒入微行，渐觉藤萝罥衣树打头。","恶木拉䬃栖，直干比指稠。","石门无风白日静，自是林响寒飕飕。","一峰忽当眼，仰看看不休。","一峰一峰千百峰，虽欲一一顾揖知无由。","金城偃蹇不得上，瑶瓮回合如相留。","苔花万锦石，丹碧烂不收。","天关守虎豹，武库开戈矛。","小山随起随偃仆，独立千仞绝顶缥缈之飞楼。","百花冈头藉草坐，潇洒正直金莲秋。","亭亭妙高台，玉斧何年修？","登高览元化，快如鹰脱鞲。","山灵故为作开阖，巧与诗境供冥搜。","白云何许来？","纤丝弄轻柔。","蓬莱作雾涌，飘飘与烟浮。","玉衣仙人鞭素虬，翕忽变化令人愁。","须臾视六合，浩荡不可求。","初疑陶轮比运甓，今悟夜壑真藏舟。","劫石拂未穷，杞国浪自忧。","断鳌立极万万古，争遣起灭如浮沤。","快哉万里风，一扫天四周。","谁言太始再开辟，日驭本自无停辀。","举手谢山灵，就无清凉毫相非神羞。","贱子贪名山，客刺已屡投。","黄华挂镜台，天坛避秦沟。","太山神明观，二室汗漫游。","胸中隐然复有此大物，便可挥斥八极隘九州。","玉峰有佳招，绝唱须一酬。","为君探囊掷下珊瑚钩，白云相望空悠悠。","异时华表见老鹤，姓字莫忘元丹丘。"]},{"t":"游泰山","f":"曲","c":["泰山天壤间，屹如郁萧台。","厥初造化手，办此何雄哉！","天门一何高，天险若可阶。","积苏与累块，分明见九垓。","扶摇九万里，未可诬齐谐。","秦皇憺威灵，茂陵亦雄材。","翠华行不归，石坛满苍苔。","古今一俯仰，感极令人哀。","是时春夏交，红绿无边涯。","奇探忘登顿，意惬自迟回。","惜无赏心人，欢然尽馀杯。","夜宿玉女祠，崩奔涌云雷。","山灵见光怪，似喜诗人来。","鸡鸣登日观，四望无氛霾。","六龙出扶桑，翻动青霞堆。","平生华嵩游，兹山未忘怀。","十年望齐鲁，登临负吟鞋。","孤云拂层崖，青壁落落云间开。","眼前有句道不得，但觉胸次高崔嵬。","徂徕山头唤李白，吾欲从此观蓬莱。"]},{"t":"游承天悬泉","f":"曲","c":["诗人爱山爱彻骨，十月东来犯冰雪。","悬流百里行不前，但觉飞湍醒毛发。","閒閒老仙仙去久，石壁姓名苔藓滑。","此翁可是六一翁，四十三年如电抹。","并州之山水所洑，骇浪几轰山石裂。","只知晋阳城西天下稀，娘子关头更奇劂。","周南留滞何敢叹，投老天教探禹穴。","君不见管涔汾源大车轮，平泉丈八玻璃盆。","不知承天此水何所本，乃与沇渎争雄尊。","平地突出随崩奔，汹如颓波射天门。","太初元气未凝结，更欲何处留胚腪？","素虬腾掷翠蛟舞，衮衮后出皆鳄鲲。","雷车怒击冰雹散，石峡峻滑苍烟屯。","凭崖下视心魄动，自愧气衰笔老胜概过眼无由吞。","少东水帘亦潇洒，珠琲一一明朝暾。","阳龙暗滋瑶草活，礜石自与莲汤温。","神祠水之浒，仪卫盛官府。","颇怪祠前碑，稽考失莽鲁。","吾闻尹革台胎宣汾洮障大泽，自是生有自来，归有所假。","而自经沟渎便可尸祝之，祀典纷纷果何取？","子胥鼓浪怒未泄，精卫衔薪心独苦。","楚臣有问天不酬，肯以诞幻虚荒惊聋瞽。","宇宙有此水，万古万万古。","人言主者介山氏，且道未有介山之前复谁主？","山深地古自是有神物，不假灵真谁敢侮。","稗官小说出闾巷，社鼓村箫走翁媪。","当时大历十才子，争遣李諲镵陋语。","石林六月清无暑，人家青红湿窗户。","射鹿有场鱼有浦，好筑漕台俯洲渚。","瓮面㭨瓢挹膏乳，醉扶红袖别吴歌，风雨不忧惊妒女。"]},{"t":"蛟龙引","f":"七言古诗","c":["古剑咸阳墓中得，抉开青云见白日。","蛟龙地底气如虹，土花千年不敢蚀。","洪炉烈焰初腾精，横海已觉无长鲸。","世上元无倚天手，匣中谁解不平鸣。","割城恨不逢相如，行酒恨不逢朱虚。","尚方未入朱云请，盟盘合与毛生俱。","谁念田文坐中客？","只将弹铗叹无鱼。"]},{"t":"孤剑咏","f":"曲","c":["郁郁重郁郁，夜半长太息。","吟成孤剑咏，门外山鬼泣。","清霜棱棱风入骨，残月耿耿灯映壁。","君不见一饥缚壮士，僵卧时自惜黄鹄。","一举摩苍天，时念樊笼束修翼。"]},{"t":"渚莲怨","f":"五言绝句","c":["阿溪何许来，素面涴风雨。","寂寞烟中魂，依依欲谁语。"]},{"t":"芳华怨","f":"曲","c":["娃儿十八娇可怜，亭亭袅袅春风前。","天上仙人玉为骨，人间画工画不出。","小小油壁车，轧轧出东华。","金缕盘双带，云裾踏雁沙。","一片朝云不成雨，被风吹去落谁家？","少年岂无恩泽侯，金鞍绣帽亦风流。","不然典取鹔鹴裘，四壁相如堪白头。","金谷楼台悄无主，燕子不来花著雨。","只知环佩作离声，谁向琵琶得私语。","无情鸂鶒翡翠儿，有情蜂雄蛱蝶雌。","劝君满酌金屈卮，明日无花空折枝。"]},{"t":"后芳华怨","f":"曲","c":["江南破镜飞上天，三五二八清光圆。","岂知汴梁破来一千日，寂寞菱花仍半边。","白沙漫漫车辘辘，鹍鸡弦中杜鹃哭。","塞门憔悴人不知，枉为珠娘怨金谷。","乐府初唱娃儿行，弹棋局平心不平。","只今雄蜂雌蝶两不死，老眼天公如有情。","白玉搔头绿云发，玫瑰面脂透肉滑。","春风著人无气力，不必相思解销骨。","洛花绝品姚家黄，扬州银红一国香。","千围万绕看不足，雨打风吹空断肠。","丹砂万年药，金印九州督，不及秦宫一生花里活。","长门晓夕寿相如，尽著千金买消渴。"]},{"t":"结杨柳怨","f":"七言古诗","c":["长乐坡前一杯酒，郑重行人结杨柳。","可怜杨柳千万枝，看看尽入行人手。","轻烟细雨绿相和，恼乱春风态度多。","路人爱是风流树，无奈朝攀暮折何？","朝攀暮折何时了，不道行人暗中老。","素衣今日洛阳尘，白发朝朝塞城草。","柳色年年岁岁青，关人何事管离情。","春风谁向丁宁道？","折断长条莫再生。"]},{"t":"秋风怨","f":"七言古诗","c":["碧瓦高梧响疏雨，坐倚薰笼时独语。","守宫一著死生休，狗走鸡飞莫为女。","云间箫鼓夜厌厌，禁漏谁将海水添。","一春门外羊车过，又见秋风拂翠帘。","总把丹青怨延寿，不知犹有《竹枝盐》。"]},{"t":"归舟怨","f":"曲","c":["渡头杨柳青复青，闺中少妇动离情。","只从问得狂夫处，夜夜梦到洛阳城。","南风吹橹声，北雁鸣嘤嘤。","江流望不极，相思春草生。"]},{"t":"征人怨","f":"七言绝句","c":["瀚海风烟扫易空，玉关归路几时东。","塞垣可是秋寒早，一夜清霜入镜中。"]},{"t":"塞上曲","f":"七言绝句","c":["平沙细草散羊牛，几簇征人在戍楼。","忽见陇头新雁过，一时回首望南州。"]},{"t":"后平湖曲","f":"曲","c":["越女颜如花，吴儿洁于玉。","天教并墙居，不著同被宿。","美人一笑千黄金，连城不博百年心。","楼上墙头无一物，暮爨朝舂一生足。","秋风拂罗裳，秋水照红妆。","举头见郎至，低头采莲房。","郎心只如菱刺短，妾意未觉藕丝长。","与郎期何许，眼碍同舟女。","春波澹澹无尽情，双星盈盈不得语。","十里平湖艇子迟，岸花汀草伴人归。","鸳鸯惊起东西去，惟有蜻蜓接翅飞。"]},{"t":"长安少年行","f":"七言古诗","c":["黄衫少年如玉笔，生长侯门人不识。","道逢豪客问姓名，袖把金鞭侧身揖。","卧驼行橐锦帕蒙，石榴压浆银作筒。","八月苍鹰一片雪，五花骄马四蹄风。","日暮新丰原上猎，三更歌舞灞桥东。"]},{"t":"黄金行","f":"七言古诗","c":["王郎少年诗境新，气象惨澹含古春。","笔头仙语复鬼语，只有温李无他人。","天公著诗贫子身，子曾不知乃自神。","人閒不买诗名用，一片青衫衡霍重。","儿贫女富母两心，何论同袍不同梦。","入门唤妇不下机，泪子垢面儿啼饥。","君诗只有贫女谣，何曾梦见金缕衣。","外家翁媪日有语，嫁女书生徒尔为。","昆阳城下三更酒，醉胆轮囷插星斗。","一夕诗肠老蛟吼，十尺长人堕车走。","斫头不屈三万言，欲向何门复低首。","何人寿我黄金千，使君破镜飞上天。"]},{"t":"隋故宫行","f":"七言古诗","c":["渭川杨柳先得春，二月莺啼百啭新。","长春宫中千树锦，暖日晴云思杀人。","君王半醉唱吴歌，绛仙起舞嚬翠蛾。","吴儿谩说曾行乐，三十六宫能几多。","千秋万古金银阙，海没三山一毫发。","繁华梦觉人不知，留得寒螀泣秋月。"]},{"t":"解剑行","f":"曲","c":["古剑黑于漆，郁郁动星文。","摩挲二十年，今日持赠君。","长鲸鼓浪三山没，知君不是泥中物。","袖间一卷白猿书，未分持刀买黄犊。","壮怀风云郁沈沈，惭愧漂母无千金。","长安侏儒饱欲死，万古不解天公心。","北风浩浩吹行客，陇水无声雪花白。","荆卿墓头秋草乾，击筑行歌欲谁识。","君不见秦相五羖皮，去时烹鸡炊扊扅。","又不见敝裘苏季子，合从归来印累累。","丈夫堕地自有万里气，翕忽变化安能知。","大冠如箕望吾子，富贵同生亦同死。"]},{"t":"征西壮士谣","f":"七言古诗","c":["三十未有二十强，手内蛇矛丈八长。","总为官家金印大，不怕百死向沙场。","捉却贺兰山下贼，金鞍绣帽好还乡。"]},{"t":"梁园春五首 其一","f":"七言绝句","c":["军从南去三回胜，雪自冬来二尺强。","今岁长春多乐事，内家应举万年觞。"]},{"t":"梁园春五首 其二","f":"七言绝句","c":["暖入金沟细浪添，津桥杨柳绿纤纤。","卖花声动天街远，几处春风揭绣帘。"]},{"t":"梁园春五首 其三","f":"七言绝句","c":["上苑春浓昼景闲，绿云红雪拥三山。","宫墙不隔东风断，偷送天香到世间。"]},{"t":"梁园春五首 其四","f":"七言绝句","c":["楼观沈沈细雨中，出墙花木乱青红。","朱门不解藏春色，燕宿莺啼处处通。"]},{"t":"梁园春五首 其五","f":"七言绝句","c":["双凤箫声隔綵霞，宫莺催赏玉溪花。","谁怜丽泽门边柳，瘦倚东风望翠华。"]},{"t":"探花词三首 其一","f":"七言绝句","c":["禁里苍龙启九关，殿前鹦鹉唤新班。","沈沈绿树鞭声远，袅袅薰风扇影閒。"]},{"t":"探花词三首 其二","f":"七言绝句","c":["浩荡春风入绣鞍，可怜东野一生寒。","皇州花好无人管，不用新郎走马看。"]},{"t":"探花词三首 其三","f":"七言绝句","c":["六十人中数少年，风流谁占探花筵。","阿钦正使才情尽，犹欠张郎白玉鞭。"]},{"t":"猎城南","f":"五言古诗","c":["翩翩游侠儿，白马如匹练。","朝出城南猎，暮趁军中宴。","北平有真虎，爱惜腰间箭。"]},{"t":"春风来","f":"曲","c":["春风来时瑶草芳，绿池珠树宿鸳鸯。","春风去后瑶草歇，来鸿去雁遥相望。","鸳鸯不得双，燕鸿天一方。","娟娟愁眉色，静与遥山长。","锦衾复罗荐，梦语相思怨。","月明乌夜啼，空闺泪如霰。"]},{"t":"并州少年行","f":"楚辞体","c":["北风动地起，天际浮云多。","登高一长啸，六龙忽蹉跎。","我欲横江斗蛟鼍，万弩迸射阳侯波。","或当大猎燕赵间，黄熊朱豹皆遮罗。","男儿万马随撝诃，朝发细柳暮朝那。","扫云黑山布阳和，归来明堂见天子，黄金横带冠峨峨。","人生只作张骞傅介子，远胜僵死空山阿。","君不见并州少年夜枕戈，破屋耿耿天垂河，欲眠不眠泪滂沱。","著鞭忽记刘越石，拔剑起舞鸡鸣歌。","东方未明兮奈夜何！"]},{"t":"续小娘歌十首 其一","f":"七言绝句","c":["吴儿沿路唱歌行，十十五五和歌声。","唱得小娘相见曲，不解离乡去国情。"]},{"t":"续小娘歌十首 其二","f":"七言绝句","c":["北来游骑日纷纷，断岸长堤是阵云。","万落千村藉不得，城池留著护官军。"]},{"t":"续小娘歌十首 其四","f":"七言绝句","c":["青山高处望南州，漫漫江水绕城流。","愿得一身随水去，直到海底不回头。"]},{"t":"续小娘歌十首 其五","f":"七言绝句","c":["风沙昨日又今朝，踏碎鸦头路更遥。","不似南桥骑马日，生红七尺系郎腰。"]},{"t":"续小娘歌十首 其七","f":"七言绝句","c":["竹溪梅坞静无尘，二月江南烟雨春。","伤心此日河平路，千里荆榛不见人。"]},{"t":"续小娘歌十首 其八","f":"七言绝句","c":["太平婚嫁不离乡，楚楚儿郎小小娘。","三百年来涵养出，却将沙漠换牛羊。"]},{"t":"续小娘歌十首 其九","f":"七言绝句","c":["饥乌坐守草间人，青布犹存旧领巾。","六月南风一万里，若为白骨便成尘。"]},{"t":"续小娘歌十首 其十","f":"七言绝句","c":["黄河千里扼兵冲，虞虢分明在眼中。","为向淮西诸将道，不须誇说蔡州功。"]},{"t":"怀益之兄","f":"五言古诗","c":["世故伊川叹，乡情越客音。","天宜他日定，陆已向来沈。","冉冉愁看老，源源事益侵。","谁言易排遣，自分不胜任。","鞭影惊疲马，钟声急暮禽。","局中无旷迹，喧外有幽寻。","梦失名家笔，书存遗子金。","山田和石瘦，茅屋过云深。","春雨蔬成圃，秋霜柿满林。","树阴凉拂席，花气澹盈襟。","宿鹭窥晨汲，孤猿伴暝吟。","溪僧时问字，野客或知琴。","抱璞休奇售，临觞得缓斟。","阿兄团聚日，曾语百年心。"]},{"t":"汴禅师自斲普照石为研以诗见饷为和二首 其一","f":"五言古诗","c":["寺废瓦不毁，研奇功亦多。","已知良斲少，更奈苦心何！","挺挺刚无敌，津津润可呵。","羽阳陵谷变，冰井字书讹。","赠比黄金璞，辞惭紫石歌。","遥知玉音在，洗耳俟研磨。"]},{"t":"汴禅师自斲普照石为研以诗见饷为和二首 其二","f":"五言古诗","c":["点化铅仍见，坚凝铁易穿。","何年埋朽壤，此日睹青天。","古色秋烟重，哀音夜雨悬。","有刀堪切玉，是镜不名砖。","佛荫沦空劫，书林结后缘。","禅河一勺水，更拟就师传。"]},{"t":"癸巳除夜","f":"五言古诗","c":["鼎定周元重，薪安汉已然。","不随南渡马，虚泛北归船。","身并枯蜩化，心争脱兔先。","尘埃嗟落泊，光景强留连。","往事青灯里，浮生白发前。","更残钟未动，犹属出京年。"]},{"t":"病中","f":"五言古诗","c":["战胜颇自恃，宁知从外腴。","文章工作祟，时运迫摧枯。","止酒嗟何及，烧猪本不图。","膏梁无急变，山泽有真臞。","诗信藤条戏，方遭铁弹诬。","盐红忘后顾，黧黑见前驱。","眩入投床仆，晨淹伏枕呼。","万钱惟呕泄，一脔尔乘除。","静伏心仍悸，深调息亦粗。","局嫌囚宇宙，渴忆卷江湖。","风柳留蝉蜕，霜松映鹤孤。","养和惩往失，扶老念时须。","杯杓归神誓，垣墙任佛踰。","回蹊且垂翅，望或在桑榆。"]},{"t":"老树","f":"五言律诗","c":["老树高留叶，寒藤细作花。","沙平时泊雁，野迥已攒鸦。","旋食秋看尽，行吟日又斜。","干戈正飘忽，不用苦思家。"]},{"t":"阳翟道中","f":"五言律诗","c":["长路伶俜里，羁怀苍莽中。","千山分晚照，万籁入秋风。","频见参旗缩，虚传朔幕空。","故园归未得，细问北来鸿。"]},{"t":"太室同希颜赋","f":"五言律诗","c":["壮矣崧维岳，盘盘上窈冥。","中天瞻巨镇，元气有遗形。","雨入秦川黑，云开楚岫青。","鳌掀一柱在，万古压坤灵。"]},{"t":"送登封张令西上","f":"五言律诗","c":["罢县人称屈，悠悠复此行。","渭城秋雁到，秦岭暮云平。","道路衣从典，风尘剑已鸣。","山西多侠客，莫说是书生。"]},{"t":"送曹吉甫兼及通甫","f":"五言律诗","c":["意气羡君豪，怜君屈骑曹。","安能事笔砚，且复混弓刀。","风雪貂裘暗，关山马骨高。","南飞见鸿雁，应为惜哀劳。"]},{"t":"胜概","f":"五言律诗","c":["胜概烟尘外，新诗杖屦间。","偶随流水去，澹与暮云还。","吾道三缄口，时情一解颜。","从今便高卧，已负半生閒。"]},{"t":"落魄","f":"五言律诗","c":["落魄宜多病，艰危更百忧。","雨声孤馆夜，草色故园秋。","行役鱼赪尾，归期乌白头。","中州遂南北，残息付悠悠。"]},{"t":"长寿新居","f":"五言律诗","c":["地古村墟迥，川回县郭斜。","蒲池馀老节，菊水引新芽。","卜筑欣成趣，归耕觉有涯。","迎门顾儿女，今日是山家。"]},{"t":"十二月六日二首 其一","f":"五言律诗","c":["伥鬼跳梁久，群雄结构牢。","天机不可料，世网若为逃。","白骨丁男尽，黄金甲第高。","阊门隔九虎，休续楚臣骚。"]},{"t":"十二月六日二首 其二","f":"五言律诗","c":["海内兵犹满，天涯岁又新。","龙移失鱼鳖，日食斗麒麟。","草棘荒山雪，烟花故国春。","聊城今夜月，愁绝未归人。"]},{"t":"短日","f":"五言律诗","c":["短日砧声急，重云雁影深。","风霜侵晚节，天地入归心。","零落沟中断，酸嘶爨下音。","五年朝与夕，清血几沾襟。"]},{"t":"送杨次公兼简秦彦容李天成","f":"五言律诗","c":["海国山如染，云堆草易荒。","时危频虎穴，路绝更羊肠。","吊影双蓬鬓，携家一药囊。","殷勤秦与李，无惜借馀光。"]},{"t":"倪庄中秋","f":"五言律诗","c":["强饭日逾瘦，裌衣秋已寒。","儿童漫相忆，行路岂知难。","露气入茅屋，溪声喧石滩。","山中夜来月，到晓不曾看。"]},{"t":"阳兴砦","f":"五言律诗","c":["乱石通樵径，重冈拥戍城。","山川带淳朴，鸡犬见升平。","雨烂沙仍软，秋偏气自清。","年年避营马，几向此中行。"]},{"t":"聚仙台夜饮","f":"五言律诗","c":["永夜留欢席，高怀远市尘。","月凉衣有露，风细酒生鳞。","乡社情亲旧，仙台姓字新。","殷勤诗卷在，长记坐中人。"]},{"t":"十月四日往关南","f":"五言律诗","c":["行路见新月，独行还独谣。","劳生尘衮衮，晚色鬓萧萧。","野旷无遗穗，林疏有堕樵。","回头麦山岭，更觉马蹄遥。"]},{"t":"和仲梁","f":"五言律诗","c":["林影兼秋薄，云阴带晚凉。","石潭鱼近藻，沙渚雁留霜。","笑语无长路，登临岂异乡。","一尊堪共醉，惜不是重阳。"]},{"t":"感事","f":"五言律诗","c":["壮事本无取，老谋何所成？","人皆传已死，吾亦厌馀生。","潦倒封侯骨，淹留混俗情。","百年堪一笑，辛苦惜虚名。"]},{"t":"同冀文明秀山行","f":"五言律诗","c":["暮景披横幅，山间二老同。","云如愁戍苦，雪亦笑诗穷。","古木冻欲折，断崖行复通。","从今胡谷梦，时到水声中。"]},{"t":"庚子三月十日作","f":"五言律诗","c":["残梦忘书帙，馀寒殢酒杯。","青铜元懒照，白纻更宽裁。","水际时独往，花边知几回。","殷勤双语燕，应自谢家来。"]},{"t":"甲寅十二月四日出镇阳寄宰鲁伯","f":"五言律诗","c":["滹水晓光动，灞桥诗境同。","冲寒骑瘦马，认影识衰翁。","长路风声里，孤城雪意中。","回头歌笑处，凄绝意何穷。"]},{"t":"同姚公茂徐沟道中联句","f":"五言律诗","c":["路转川涂阔，天低雨气昏。","绵山连汉垒，汾水入并门。","来往频鞍马，登临负酒樽。","联诗强一笑，凄绝恐销魂。"]},{"t":"帝城","f":"七言律诗","c":["帝城西下望孤云，半废晨昏愧此身。","世俗但知从仕乐，书生只合在家贫。","悠悠未了三千牍，碌碌翻随十九人。","预遣儿书报归日，安排鸡黍约比邻。"]},{"t":"仆射陂醉归即事","f":"七言律诗","c":["多生曾得江湖乐，每见陂塘觉眼明。","诗酒共寻前日约，风阴新自夜来晴。","春波澹澹沙鸟没，野色荒荒烟树平。","醉踏扁舟浩歌起，不须红袖出重城。"]},{"t":"春日","f":"七言律诗","c":["里社春盘巧欲争，裁红晕碧助春情。","忽惊此日仍为客，却想当年似隔生。","贫里齑盐怜节物，乱来歌吹失欢声。","南州剩有还乡伴，戎马何时道路清。"]},{"t":"野菊，座主閒閒公命作 其一","f":"七言律诗","c":["柴桑人去已千年，细菊班班也自圆。","共爱鲜明照秋色，争教狼藉卧疏烟。","荒畦断垄新霜后，瘦蝶寒螀晚景前。","只恐春丛笑迟暮，题诗端为发幽妍。"]},{"t":"昆阳二首 其二","f":"七言律诗","c":["去日黄花半未开，南来忽复见寒梅。","淹留岁月无馀物，料理尘埃有此杯。","老马长途良惫矣，白鸥春水亦悠哉！","商馀说有沧洲趣，早晚乾坤入钓台。"]},{"t":"叶县雨中","f":"七言律诗","c":["春旱连延入麦秋，今朝一雨散千忧。","龙公有力回枯槁，客子何心叹滞留。","多稼即看连楚泽，归云应亦到崧丘。","兵尘浩荡乾坤满，未厌明河拂地流。"]},{"t":"山中寒食","f":"七言律诗","c":["小雨班班浥曙烟，平林簇簇点晴川。","清明寒食连三月，颍水崧山又一年。","乐事渐随花共减，归心长与雁相先。","平生最有登临兴，百感中来只慨然。"]},{"t":"楚汉战处","f":"七言律诗","c":["虎掷龙挐不两存，当年曾此赌乾坤。","一时豪杰多行阵，万古山河自壁门。","原野犹应厌膏血，风云长遣动心魂。","成名竖子知谁谓？","拟唤狂生与细论。"]},{"t":"后湾别业","f":"七言律诗","c":["薄云晴日烂烘春，高柳清风便可人。","一饱本无华屋念，百年今见老农身。","童童翠盖桑初合，滟滟苍波麦已匀。","便与溪塘作盟约，不应重遣濯缨尘。"]},{"t":"寄钦用","f":"七言律诗","c":["憔悴京华苜蓿盘，南山归兴夜漫漫。","长门有赋人谁买？","坐榻无毡客亦寒。","虫臂偶然烦造物，獐头何者亦求官。","故人东望应相笑，世路羊肠乃尔难。"]},{"t":"内乡县斋书事","f":"七言律诗","c":["吏散公庭夜已分，寸心牢落百忧熏。","催科无政堪书考，出粟何人与佐军。","饥鼠绕床如欲语，惊乌啼月不堪闻。","扁舟未得沧浪去，惭愧舂陵老使君。"]},{"t":"除夜","f":"七言律诗","c":["一灯明暗夜如何，梦寐衡门在涧阿。","物外烟霞玉华远，花时车马洛阳多。","折腰真有陶潜兴，扣角空传宁戚歌。","三十七年今日过，可怜出处两蹉跎。"]},{"t":"刘光甫内乡新居","f":"七言律诗","c":["廌冠平日凛秋霜，老去声名只闭藏。","父老渐来同保社，儿童久已爱文章。","蔬随隙地皆成圃，竹放新梢欲过墙。","为向长安旧游道，世间元有北窗凉。"]},{"t":"西斋夜宴","f":"七言律诗","c":["飘零无物慰天涯，酒伴相逢饮倍加。","误谬君当略彭泽，回旋我亦笑长沙。","金钗翠亸迎春髻，银烛光摇半夜花。","只欠东山游录事，不来坚坐看纷哗。"]},{"t":"出山","f":"七言律诗","c":["松门石径静无关，布袜青鞋几往还。","少日漫思为世用，中年直欲伴僧闲。","尘埃长路仍回首，升斗微官亦强颜。","休道西山不留客，数峰如画暮云间。"]},{"t":"岐阳三首 其一","f":"七言律诗","c":["突骑连营鸟不飞，北风浩浩发阴机。","三秦形胜无今古，千里传闻果是非。","偃蹇鲸鲵人海涸，分明蛇犬铁山围。","穷途老阮无奇策，空望岐阳泪满衣。"]},{"t":"岐阳三首 其三","f":"七言律诗","c":["眈眈九虎护秦关，懦楚孱齐几上看。","禹贡土田推陆海，汉家封檄自天山。","北风猎猎悲笳发，渭水萧萧战骨寒。","三十六峰长剑在，倚天仙掌惜空闲。"]},{"t":"雨后丹凤门登眺","f":"七言律诗","c":["绛阙遥天霁景开，金明高树晚风回。","长虹下饮海欲竭，老雁叫云秋更哀。","劫火有时归变灭，神嵩何计得飞来。","穷途自觉无多泪，莫傍残阳望吹台。"]},{"t":"怀秋林别业","f":"七言律诗","c":["茅屋萧萧淅水滨，岂知身属洛阳尘。","一家风雪何年尽，二顷田园入梦频。","高树有巢鸠笑拙，空墙无穴鼠嫌贫。","西南遥望肠堪断，自古虚名只误人。"]},{"t":"壬辰十二月车驾东狩后即事五首 其一","f":"七言律诗","c":["翠被匆匆见执鞭，戴盆郁郁梦瞻天。","只知河朔归铜马，又说台城堕纸鸢。","血肉正应皇极数，衣冠不及广明年。","何时真得携家去，万里秋风一钓船。"]},{"t":"壬辰十二月车驾东狩后即事五首 其三","f":"七言律诗","c":["郁郁围城度两年，愁肠饥火日相煎。","焦头无客知移突，曳足何人与共船。","白骨又多兵死鬼，青山元有地行仙。","西南三月音书绝，落日孤云望眼穿。"]},{"t":"壬辰十二月车驾东狩后即事五首 其五","f":"七言律诗","c":["五云宫阙露盘秋，银汉无声桂树稠。","复道渐看连上苑，戈船仍拟下扬州。","曲中青冢传新怨，梦里华胥失旧游。","去去江南庾开府，凤凰楼畔莫回头。"]},{"t":"癸巳四月二十九日出京","f":"七言律诗","c":["塞外初捐宴赐金，当时南牧已骎骎。","只知灞上真儿戏，谁谓神州竟陆沈。","华表鹤来应有语，铜盘人去亦何心。","兴亡谁识天公意？","留著青城阅古今。"]},{"t":"喜李彦深过聊城","f":"七言律诗","c":["围城十月鬼为邻，异县相逢白发新。","恨我不如南去雁，羡君独是北归人。","言诗匡鼎功名薄，去国虞翻骨相屯。","老眼天公只如此，穷途无用说悲辛。"]},{"t":"与张杜饮","f":"七言律诗","c":["故人寥落晓天星，异县相逢觉眼明。","世事且休论向日，酒尊聊喜似承平。","山公倒载群儿笑，焦遂高谈四座惊。","轰醉春风一千日，愁城从此不能兵。"]},{"t":"秋夕","f":"七言律诗","c":["小簟凉多睡思清，一窗风雨送秋声。","频年但觉貂裘敝，万古何曾马角生。","寄食且依严尹幕，附书谁住邓州城？","洗愁欲问东家酒，恨杀寒鸡不肯鸣。"]},{"t":"梦归","f":"七言律诗","c":["憔悴南冠一楚囚，归心江汉日东流。","青山历历乡国梦，黄叶萧萧风雨秋。","贫里有诗工作祟，乱来无泪可供愁。","残年兄弟相逢在，随分齑盐万事休。"]},{"t":"淮右","f":"七言律诗","c":["淮右城池几处存，宋州新事不堪论。","辅车谩欲通吴会，突骑谁当捣蓟门。","细水浮花归别涧，断云含雨入孤村。","空馀韩偓伤时泪，留与累臣一断魂。"]},{"t":"秋夜","f":"七言律诗","c":["九死馀生气息存，萧条门巷似荒村。","春雷谩说惊坯户，皎日何曾入覆盆。","济水有情添别泪，吴云无梦寄归魂。","百年世事兼身事，尊酒何人与细论！"]},{"t":"乙未正月九日立春","f":"七言律诗","c":["十度新正九处家，今年痴坐转堪嗟。","一冬残雪不肯尽，连日苦阴殊未涯。","重碧总誇燕市酒，小红谁记上林花？","残魂零落今无几，乞与春风恼鬓华。"]},{"t":"三仙祠","f":"七言律诗","c":["三仙祠下往来频，憔悴征衫满路尘。","箫鼓未休寒食酒，樵苏时见旧都人。","吹残芳树红仍在，展放平田绿已匀。","西北并州隔千里，几时还我故乡春。"]},{"t":"送辅之仲庸还大梁","f":"七言律诗","c":["骅骝争道渺翩翩，谁遗风尘失壮年。","四壁旧闻悬磬宅，一囊今有卖书钱。","淋浪别酒青灯夜，灭没孤帆落照边。","想得还家过春半，故都乔木满苍烟。"]},{"t":"寄钦止李兄","f":"七言律诗","c":["征车南北转秋蓬，关塞相望两秃翁。","衮衮便当随世路，悠悠难复倚天公。","铜驼荆棘千年后，金马衣冠一梦中。","尊酒云州古城下，几时携手哭春风。"]},{"t":"镇州与文举百一饮","f":"七言律诗","c":["翁仲遗墟草棘秋，苍龙双阙记神州。","只知终老归唐土，忽漫相逢是楚囚。","日月尽随天北转，古今谁见海西流？","眼中二老风流在，一醉从教万事休。"]},{"t":"卫州感事二首 其一","f":"七言律诗","c":["神龙失水困蜉蝣，一舸仓皇入宋州。","紫气已沈牛斗夜，白云空望帝乡秋。","劫前宝地三千界，梦里琼枝十二楼。","欲就长河问遗事？","悠悠东注不还流。"]},{"t":"卫州感事二首 其二","f":"七言律诗","c":["白塔亭亭古佛祠，往年曾此走京师。","不知江令还家日，何似湘累去国时。","离合兴亡遽如此，凄迟零落竟安之！","太行千里青如染，落日阑干有所思。"]},{"t":"望崧少二首 其一","f":"七言律诗","c":["崧少飞来昆阆山，山家茅屋翠微间。","鸡豚乡社相劳苦，花木禅房时往还。","结习尚馀三宿恋，残年多负半生閒。","长河一苇人千里，望断西城碧玉环。"]},{"t":"望崧少二首 其二","f":"七言律诗","c":["饮鹤池边万木稠，养龙崖上五峰秋。","藤垂绝壁云添润，涧落哀湍雪共流。","田父占年惊玉旆，诗仙留迹叹昆丘。","西风落日山阳道，空对红尘忆旧游。"]},{"t":"怀州子城晚望少室","f":"七言律诗","c":["河外青山展卧屏，并州孤客倚高城。","十年旧隐抛何处？","一片伤心画不成。","谷口暮云知郑重，林梢残照故分明。","洛阳见说兵犹满，半夜悲歌意未平。"]},{"t":"羊肠坂","f":"七言律诗","c":["浩荡云山直北看，凌兢羸马不胜鞍。","老来行路先愁远，贫里辞家更觉难。","衣上风沙叹憔悴，梦中灯火忆团圞。","凭谁为报东州信？","今在羊肠百八盘。"]},{"t":"太原","f":"七言律诗","c":["梦里乡关春复秋，眼明今得见并州。","古来全晋非无策，乱后清汾空自流。","南渡衣冠几人在？","西山薇蕨此生休。","十年弄笔文昌府，争信中朝有楚囚。"]},{"t":"野谷道中怀昭禅师","f":"七言律诗","c":["行行汾沁欲分疆，渐喜人声挟两乡。","野谷青山空自绕，金城白塔已相望。","汤翻豆饼银丝滑，油点茶心雪蕊香。","说向阿师应被笑，人生生处果难忘。"]},{"t":"寄杨飞卿","f":"七言律诗","c":["客梦悠悠信转蓬，藜床殷殷动晨钟。","西风白发三千丈，故国青山一万重。","沙水有情留过雁，乾坤多事泣秋虫。","三间老屋知何处，惭愧云间陆士龙。"]},{"t":"再到新卫","f":"七言律诗","c":["蝗旱相仍岁已荒，伶俜十口值还乡。","空令姓字喧时辈，不救饥寒趋路傍。","行帐马嘶尘澒洞，空村人去雨淋浪。","河平千里筋骸尽，更欲驱车上太行。"]},{"t":"别冠氏诸人","f":"七言律诗","c":["东舍茶浑酒味新，西城红艳杏园春。","衣冠会集今为盛，里社追随分更亲。","分手共伤千里别，低眉常愧六年贫。","他时细数平原客，看到还乡第几人？"]},{"t":"四哀诗李钦叔","f":"七言律诗","c":["赤县神州坐陆沈，金汤非粟祸侵寻。","当官避事平生耻，视死如归社稷心。","文采是人知子重，交朋无我与君深。","悲来不待山阳笛，一忆同衾泪满襟。"]},{"t":"冀京父","f":"七言律诗","c":["先公藻鉴识终童，曾拔昆山玉一峰。","不见连城沽白璧，早闻烈火燎黄琮。","重围急变纷纷口，九地忠魂耿耿胸。","欲吊南云无觅处，士林能不泣相逢。"]},{"t":"李长源","f":"七言律诗","c":["冀都事死东州祸，李翰林亡陕府兵。","方为骚人笺楚些，更禁书客堕秦坑。","石苞本不容孙楚，黄祖安能贷祢衡！","同甲四人三横霣，此身虽在亦堪惊。"]},{"t":"王仲泽","f":"七言律诗","c":["太学声华弱冠驰，青云岐路九霄飞。","上前论事龙颜喜，幕下筹边犬吠稀。","壮志相如头碎柱，赤心嵇绍血沾衣。","从来圣牍褒忠义，谁为幽魂一发挥。"]},{"t":"杏花二首 其一","f":"七言律诗","c":["芳树春融绛蜡凝，春风寂寞掩柴荆。","画眉卢女娇无奈，龋齿孙娘笑不成。","已怕宿妆添蝶粉，更堪暖蕊闹蜂声。","一般疏影黄昏月，独爱寒梅恐未平。"]},{"t":"赋南中杨生玉泉墨","f":"七言律诗","c":["万灶玄珠一唾轻，客卿新以玉泉名。","御团更觉香为累，冷剂休誇漆点成。","涴袖秦郎无藉在，画眉张遇可怜生。","晴窗弄笔人今老，孤负松风入砚声。"]},{"t":"赤石谷","f":"七言律诗","c":["林罅阴崖雾杳冥，石根寒溜玉玎玲。","云来朔漠疑秋早，山近清凉觉地灵。","静爱鸟声存野调，闹嫌人迹带尘腥。","南台说有金银气，可是并汾处士星。"]},{"t":"亭同麻知几赋","f":"七言律诗","c":["零落栖迟复此游，一尊聊得散羁愁。","天围平野莽无际，水绕孤城閒不流。","柳意渐回淮浦暖，雁声仍带塞门秋。","登高望远令人起，欲买烟波无钓舟。"]},{"t":"过应州","f":"七言律诗","c":["平野风埃接戍楼，边城三月似穷秋。","人家土屋才容膝，驿路旃车不断头。","随俗未甘尝马湩，敌寒直欲御羊裘。","十年紫禁烟花绕，此日云山是应州。"]},{"t":"感事","f":"七言律诗","c":["富贵何曾润髑髅，直须淅米向矛头。","血雠此日逢三怨，风鉴生平备九流。","瓢饮不甘颜巷乐，市钳真有楚人忧。","世间安得如川酒，力士铛头醉死休。"]},{"t":"感兴","f":"七言律诗","c":["倚梯从昔望烟霄，七叶何人竟珥貂。","道路常教车历鹿，功名唯有鬓飘萧。","勤如韩子初无补，晚似冯公岂见招。","五十三年等閒里，一窗风叶雨潇潇。"]},{"t":"甲辰三月旦日以后杂诗二首 其一","f":"七言律诗","c":["濈濈猩红闹晓晴，攒头真似与春争。","舒开杨柳聊相映，瘦杀寒梅枉自清。","粉艳低回工作态，绛唇寂寞独含情。","画图只爱残妆好，未信徐郎解写生。"]},{"t":"甲辰三月旦日以后杂诗二首 其二","f":"七言律诗","c":["密雾轻尘细洒匀，绿云红雪一番新。","风光烂熳供欢席，酒味清醇似主人。","落落湖山如有喜，欣欣鱼鸟亦相亲。","新诗写入奚奴锦，从此他乡不算春。"]},{"t":"紫牡丹","f":"七言律诗","c":["梦里华胥失玉京，小阑春事自升平。","只缘造物偏留意，须信凡花浪得名。","蜀锦浪淘添色重，御炉风细觉香清。","金刀一剪肠堪断，绿鬓刘郎半白生。"]},{"t":"为邓人作诗","f":"七言律诗","c":["再见州人本不期，相留相挽忍相违。","携盘渭水空流涕，种柳金陵已合围。","事去恍疑春梦过，眼明还似故乡归。","题诗未要题名字，今是中原一布衣。"]},{"t":"赠张主簿伟","f":"七言律诗","c":["江岸坟荒草棘秋，朱阳南下重君忧。","弓刀近塞人烟少，林壑经霜虎迹稠。","究竟畏途知有渐，激昂高义报无由。","从今弟侄通家了，莫向瓜田认故侯。"]},{"t":"寄荅商孟卿","f":"七言律诗","c":["窈渺朱弦寂寞心，得诗何啻得黄金。","冷猿挂梦山月暝，老雁叫群江渚深。","异县五年仍隔阔，荒城连日想登临。","书来且只平安了，拨触离愁恐不禁。"]},{"t":"十一月五日暂往西张","f":"七言律诗","c":["城隈细路入沙汀，絮帽冲风日再经。","岁歉村虚更荒恶，穷冬人影亦伶俜。","林烟漠漠鸦边暗，山骨棱棱雪外青。","四十年来此寒苦，冻吟犹记陇关亭。"]},{"t":"石岭关书所见","f":"七言律诗","c":["轧轧旃车转石槽，故关犹复戍弓刀。","连营突骑红尘暗，微服行人细路高。","已化虫沙休自叹，厌逢豺虎欲安逃。","青云玉立三千丈，元只东山意气豪。"]},{"t":"汴梁除夜","f":"七言律诗","c":["六街歌鼓待晨钟，四壁寒斋只病翁。","鬓雪得年应更白，灯花何喜也能红。","养生有论人空老，祖道无诗鬼亦穷。","数日西园看车马，一番桃李又春风。"]},{"t":"龙兴寺阁","f":"七言律诗","c":["全赵堂堂入望宽，九层飞观尽高寒。","空闻赤帜疑军垒，真见金人泣露盘。","桑海几经尘劫坏，江山独恨酒肠乾。","诗家总道登临好，试就遗台老树看。"]},{"t":"听姨女乔夫人鼓风入松","f":"七言律诗","c":["白雪朱弦一再行，春风纤指十三星。","云窗雾阁有今夕，宝靥罗裙无此声。","萧洒寒松度虚籁，悠扬飞絮搅青冥。","胎仙不比湘灵瑟，五字钱郎莫漫惊。"]},{"t":"寒食","f":"七言律诗","c":["上苑春风盛物华，天津云锦赤城霞。","轻舟矮马追随远，翠幕青旗笑语哗。","化国楼台隔瀛海，吴儿洲渚记仙家。","山斋此日肠堪断，寂寞铜瓶对杏花。"]},{"t":"过寂通庵别陈丈","f":"七言律诗","c":["心远由来地自偏，不离城市得林泉。","从教上界多官府，且放閒身作地仙。","三月有期何敢负，百杯未满会须填。","违离更觉从公晚，却望都门一慨然。"]},{"t":"送李同年德之归洛西","f":"七言律诗","c":["无奈流光冉冉何，逢君聊得慰蹉跎。","飞黄老去空奇骨，社燕归来只旧窠。","举世尽从愁里过，一尊独爱醉时歌。","洛中定有人相问，休道今年白发多。"]},{"t":"存没","f":"七言律诗","c":["行间杨赵提衡早，老去辛刘入梦频。","案上酒杯聊自慰，袖中诗卷欲谁亲。","两都秋色皆乔木，一代名家不数人。","汲冢遗编要完补，可能虚负百年身。"]},{"t":"人日有怀愚斋张兄纬文","f":"七言律诗","c":["书来聊得慰怀思，清镜平明见白髭。","明月高楼燕市酒，梅花人日草堂诗。","风光流转何多态，儿女青红又一时。","涧底孤松二千尺，殷勤留看岁寒枝。"]},{"t":"张村杏花","f":"七言律诗","c":["昨日樱桃绛蜡痕，今朝红袖已迎门。","只应芳树知人意，留著残妆伴酒尊。","浓李尚须羞粉艳，寒梅空自怨黄昏。","诗家元白无今古，从此张村即赵村。"]},{"t":"送奉先从军","f":"七言律诗","c":["潦倒书生百战场，功名都属绣衣郎。","虎头食肉无不可，鼠目求官空自忙。","卷月清笳渭城晓，倚天长剑蜀山苍。","习池老去风流减，醉后扬鞭愧葛疆。"]},{"t":"赠玉峰魏文邦彦","f":"七言律诗","c":["梦想南山掩霭间，眼明惊见玉峰寒。","风波旧忆横身过，世事今归袖手看。","贩妇庸儿识名姓，故乡遗族见衣冠。","临流卜筑平生事，会就辽东管幼安。"]},{"t":"郁郁","f":"七言律诗","c":["郁郁羁怀不易开，更堪寥落动凄哀。","华胥梦破青山在，梁甫吟成白发催。","秋意渐随林影薄，晓寒都逐雁声来。","并州旧日风声恶，怅望乡书早晚回。"]},{"t":"秋日载酒光武庙","f":"七言律诗","c":["美酒良辰邂逅同，赤眉城北汉王宫。","百年星斗归天上，万古旌旗在眼中。","草木暗随秋气老，河山长为昔人雄。","一杯径醉风云地，莫放银盘上海东。"]},{"t":"丙辰九月二十六日挈家游龙泉","f":"七言律诗","c":["风色澄鲜称野情，居僧闻客喜相迎。","藤垂石磴云添润，泉漱山根玉有声。","庭树老于临济寺，霜林浑是汉家营。","明年此日知何处？","莫惜题诗记姓名。"]},{"t":"洛阳高少府瀍阳后庵四首 其一","f":"五言绝句","c":["溪上弄明月，风露发新警。","心空无一尘，万竹扫清影。"]},{"t":"洛阳高少府瀍阳后庵四首 其二","f":"五言绝句","c":["一水随人意，蔬畦复芋沟。","风波河洛近，莫放出山流。"]},{"t":"洛阳高少府瀍阳后庵四首 其三","f":"五言绝句","c":["韭早春先绿，菘肥秋未黄。","殷勤绕畦水，终日为君忙。"]},{"t":"洛阳高少府瀍阳后庵四首 其四","f":"五言绝句","c":["地僻境逾静，林疏秋已分。","清溪一片月，修竹四山云。"]},{"t":"山居杂诗六首 其二","f":"五言绝句","c":["石润云先动，桥平水渐过。","野阴添晚重，山意向秋多。"]},{"t":"山居杂诗六首 其五","f":"五言绝句","c":["涨落沙痕出，堤摧岸口斜。","断桥堆聚沫，高树阁浮槎。"]},{"t":"梁父吟扇头","f":"五言绝句","c":["盘礴万古心，块石入危坐。","青天一明月，孤唱谁与和？"]},{"t":"辛亥寒食","f":"五言绝句","c":["寒食年年好，今年迥不同。","秋千与花影，并在月明中。"]},{"t":"德和墨竹扇头","f":"曲","c":["静里离离新粉，动时细细清香。","明月清风自在，红尘白日何妨。"]},{"t":"曹得一扇头","f":"曲","c":["机中秦女仙去，月底梅花晚开。","只见一枝疏影，不知何处香来。"]},{"t":"西园","f":"七言绝句","c":["百草千花雨气新，今朝陌上有游尘。","皇州春色浓于酒，醉杀西园歌舞人。"]},{"t":"杏花杂诗八首 其二","f":"七言绝句","c":["露华浥浥汎晴光，睡足东风倚绿窗。","试遣红妆映银烛，湘桃争合伴仙郎。"]},{"t":"杏花杂诗八首 其四","f":"七言绝句","c":["暖日园林可散愁，每逢花处尽迟留。","青旗知是谁家酒？","一片春风出树头。"]},{"t":"杏花杂诗八首 其五","f":"七言绝句","c":["纷纷红紫不胜稠，争得春光竞出头。","却是梨花高一著，随宜梳洗尽风流。"]},{"t":"杏花杂诗八首 其六","f":"七言绝句","c":["露浥清华粉自添，隔溪遥见玉帘苫。","眼看桃李飘零尽，更拣繁枝插帽檐。"]},{"t":"杏花杂诗八首 其七","f":"七言绝句","c":["楚客离魂不易招，野春平碧水迢迢。","垂杨也被多情恼，瘦损春风十万条。"]},{"t":"杏花杂诗八首 其八","f":"七言绝句","c":["红妆翠盖惜风流，春动香生不自由。","莫向芸斋厌閒冷，小诗供作锦缠头。"]},{"t":"出京","f":"七言绝句","c":["巫峡归云底处寻，高城渺渺暮烟沈。","春风不剪垂杨断，系尽行人北望心。"]},{"t":"惠崇芦雁","f":"七言绝句","c":["寒沙折苇静相依，故国春风早晚归。","意外羁栖谁画得？","羽毛单薄稻粱微。"]},{"t":"铜雀台瓦砚","f":"七言绝句","c":["爱惜铅华洗又看，画阑桂树雨声寒。","千年不作鸳鸯去，唤得书生笑老瞒。"]},{"t":"步虚词三首 其一","f":"七言绝句","c":["阆苑仙人白锦袍，海山宫阙醉蟠桃。","三更月底鸾声急，万里风头鹤背高。"]},{"t":"步虚词三首 其二","f":"七言绝句","c":["万神朝罢出通明，和气欢声满玉京。","见说人间有新异，绿章封事谢升平。"]},{"t":"步虚词三首 其三","f":"七言绝句","c":["琪树明霞碧落宫，歌音袅袅度泠风。","人间听得《霓裳》惯，犹恐钧天是梦中。"]},{"t":"风雨停舟图","f":"七言绝句","c":["老木高风作意狂，青山和雨入微茫。","画图唤起扁舟梦，一夜江声撼客床。"]},{"t":"长寿山居元夕","f":"七言绝句","c":["微茫灯火共荒村，黄叶漫山雪拥门。","三十九年何限事，只留孤影伴黄昏。"]},{"t":"右司正之家渭川千亩图","f":"七言绝句","c":["官街尘土雾中天，入眼荒寒一洒然。","大似终南山下看，北风和雪卷苍烟。"]},{"t":"山居二首 其一","f":"七言绝句","c":["斜阳高树挂晴虹，肃肃微凉雨气中。","一道鹭鸶花不断，密香吹满马头风。"]},{"t":"山居二首 其二","f":"七言绝句","c":["诗肠搜苦怯茶瓯，信手拈书却枕头。","檐溜滴残山院静，碧花红穗媚凉秋。"]},{"t":"寄女严","f":"七言绝句","c":["鹳崖鱼窟路间关，旬月无由一往还。","寒食归宁见邻女，举家回首望西山。"]},{"t":"自邓州幕府暂归秋林","f":"七言绝句","c":["升斗微官不疗饥，中林春雨蕨芽肥。","归来应被青山笑，可惜缁尘染素衣。"]},{"t":"题省掾刘德润家骖鸾图并为同舍郎刘长卿记异刘在方城先有碧箫之遇如芙蓉城事云","f":"七言绝句","c":["千劫情缘万古期，楼中萧史姓名非。","洞天花落秋云冷，肠断青鸾独自飞。"]},{"t":"杂著三首 其一","f":"七言绝句","c":["青盖朝来帝座新，岂知卫瓘是忠臣。","洛阳荆棘千年后，愁绝铜驼陌上人。"]},{"t":"杂著三首 其二","f":"七言绝句","c":["天上河源地上流，黄金浮世等閒休。","埋愁不著重泉底，尽向人间种白头。"]},{"t":"杂著三首 其三","f":"七言绝句","c":["半纸虚名百战身，转头高冢卧麒麟。","山间曾见渔樵说，辛苦凌烟阁上人。"]},{"t":"俳体雪香亭杂咏十二首 其一","f":"七言绝句","c":["洛阳城阙变灰烟，暮虢朝虞只眼前。","为向杏梁双燕道，营巢何处过明年？"]},{"t":"俳体雪香亭杂咏十二首 其三","f":"七言绝句","c":["醇和旁近洞房环，碧瓦参差竹树閒。","批奏内人轮上直，去年名姓在窗间。"]},{"t":"俳体雪香亭杂咏十二首 其四","f":"七言绝句","c":["天上三郎玉不如，手中白羽趁花奴。","御屏零落宣和笔，留得华清按乐图。"]},{"t":"俳体雪香亭杂咏十二首 其五","f":"七言绝句","c":["诗仙诗鬼不谩欺，时事先教梦里知。","禁苑又经人物散，荒凉台榭水流迟。"]},{"t":"俳体雪香亭杂咏十二首 其六","f":"七言绝句","c":["金缕歌词金曲卮，百年人事鬓成丝。","重来未必春风在，更为梨花住少时。"]},{"t":"俳体雪香亭杂咏十二首 其七","f":"七言绝句","c":["杨柳随风散绿丝，桃花临水弄妍姿。","无端种下青青竹，恰到湘君泪尽时。"]},{"t":"俳体雪香亭杂咏十二首 其八","f":"七言绝句","c":["琵琶心事曲中论，曾笑明妃负汉恩。","明日天山山下路，不须回首望都门。"]},{"t":"俳体雪香亭杂咏十二首 其九","f":"七言绝句","c":["炉薰浥浥带轻阴，翠竹高梧水殿深。","去去旃车雪三尺，画罗休缕麝香金。"]},{"t":"俳体雪香亭杂咏十二首 其十","f":"七言绝句","c":["苦才多思是春风，偏近骚人怅望中。","啼尽杜鹃枝上血，海棠明日更应红。"]},{"t":"俳体雪香亭杂咏十二首 其十一","f":"七言绝句","c":["暖日晴云锦树新，风吹雨打旋成尘。","宫园深闭无人到，自在流莺哭暮春。"]},{"t":"俳体雪香亭杂咏十二首 其十二","f":"七言绝句","c":["暮云楼阁古今情，地老天荒恨未平。","白发累臣几人在，就中愁杀庾兰成。"]},{"t":"记梦","f":"七言绝句","c":["天上材官老不材，从教兀兀走尘埃。","梦中望拜通明殿，曾见金书两字来。"]},{"t":"杂著二首 其一","f":"七言绝句","c":["六朝琼树掌中春，回首胡妆一面新。","生羡石家金谷里，千年独有坠楼人。"]},{"t":"杂著二首 其二","f":"七言绝句","c":["燕语莺啼百啭新，长廊寂寂不逢人。","东君去作谁家客？","花柳无情各自春。"]},{"t":"眉","f":"七言绝句","c":["石绿香煤浅淡间，多情长带楚梅酸。","小诗拟写春愁样，忆著分明下笔难。"]},{"t":"出都","f":"七言绝句","c":["春闺斜月晓闻莺，信马都门半醉醒。","官柳青青莫回首，短长亭是断肠亭。"]},{"t":"姨母陇西君讳日作","f":"七言绝句","c":["宝镜煌煌照九州，埋藏曾及见诸刘。","酆城今日无雷焕，紫气谁当辨斗牛。"]},{"t":"自赵庄归冠氏","f":"七言绝句","c":["杏园红过雪披离，杨柳无风绿线齐。","寒食人家在原野，乳鸦墙外尽情啼。"]},{"t":"济南杂诗五首 其一","f":"七言绝句","c":["儿时曾过济南城，暗算存亡只自惊。","四十二年弹指过，却疑行处是前生。"]},{"t":"济南杂诗五首 其二","f":"七言绝句","c":["吴儿洲渚似神仙，罨画溪光碧玉泉。","别有洞天君不见，鹊山寒食泰和年。"]},{"t":"济南杂诗五首 其三","f":"七言绝句","c":["石刻烧残宴集辞，雄楼杰观想当时。","只应画戟清香地，多欠韦郎五字诗。"]},{"t":"济南杂诗五首 其四","f":"七言绝句","c":["白烟销尽冻云凝，山月飞来夜气澄。","且向波间看玉塔，不须桥畔觅金绳。"]},{"t":"济南杂诗五首 其五","f":"七言绝句","c":["荷叶荷花烂熳秋，鹭鸶飞近钓鱼舟。","北城佳处经行遍，留著南山更一游。"]},{"t":"题刘才卿湖石扇头","f":"七言绝句","c":["幽涧云凝雨未乾，曲池疏竹共荒寒。","扇头唤起西园梦，好似熙春阁下看。"]},{"t":"闻歌怀京师旧游","f":"七言绝句","c":["楼前谁唱《绿腰》催，千里梁园首重回。","记得杜家亭子上，信之钦用共听来。"]},{"t":"出镇州","f":"七言绝句","c":["汾水归心日夜流，孤云飞处是松楸。","无端行近还乡路，却傍西山入相州。"]},{"t":"南关二首 其一","f":"七言绝句","c":["风里秋蓬不自由，一生几度过隆州。","无情团柏关前水，流尽朱颜到白头。"]},{"t":"南关二首 其二","f":"七言绝句","c":["路转川回失系舟，更教两驿过徐沟。","多情团柏关前水，却共清汾一处流。"]},{"t":"马坊冷大师清真道院","f":"七言绝句","c":["枯蒲折苇障清湾，十里风荷指顾间。","安得西湖展江手，乱铺云锦浸青山。"]},{"t":"游天坛杂诗五首 其一","f":"七言绝句","c":["芳树阴阴鸟语哗，绿云晴雪映红霞。","青山可是堪人恨，藏著中岩十里花。"]},{"t":"游天坛杂诗五首 其二","f":"七言绝句","c":["漫山白白与红红，小树低丛看不供。","总道楂花香气好，就中偏爱玉珑松。"]},{"t":"游天坛杂诗五首 其三","f":"七言绝句","c":["溪童相对采椿芽，指似阳坡说种瓜。","想得近山营马少，青林深处有人家。"]},{"t":"游天坛杂诗五首 其五","f":"七言绝句","c":["仙坛倒影凤麟洲，一道云光插素秋。","也是天公閒不得，海东移著海西头。"]},{"t":"初挈家还读书山杂诗二首 其一","f":"七言绝句","c":["天门笔势到閒閒，相国文章玉笋班。","从此晋阳方志上，系舟山是读书山。"]},{"t":"初挈家还读书山杂诗二首 其二","f":"七言绝句","c":["眼中华屋记生存，旧事无人可共论。","老树婆娑三百尺，青衫还见读书孙。"]},{"t":"赋瓶中杂花七首 其一","f":"七言绝句","c":["老眼惊看节物新，今年更与酒杯亲。","东山一道花如绣，从此他乡不是春。"]},{"t":"赋瓶中杂花七首 其二","f":"七言绝句","c":["香中人道睡香浓，谁信丁香臭味同。","一树百枝千万结，更应薰染费春工。"]},{"t":"赋瓶中杂花七首 其三","f":"七言绝句","c":["生红点点弄娇妍，半拆花房更可怜。","传语春风好将护，莫教容易作银钱。"]},{"t":"赋瓶中杂花七首 其四","f":"七言绝句","c":["红抹兰膏绿染衣，绿娇红小两相宜。","华边剩有清香在，木石痴儿自不知。"]},{"t":"赋瓶中杂花七首 其五","f":"七言绝句","c":["素艳来从月姊家，温风淑气发清华。","人间自有交枝玉，天上休开六出花。"]},{"t":"赋瓶中杂花七首 其六","f":"七言绝句","c":["昨日桃花锦片新，兔葵今日到残春。","低枝留得稀疏朵，比似全开更恼人。"]},{"t":"赋瓶中杂花七首 其七","f":"七言绝句","c":["古铜瓶子满芳枝，裁剪春风入小诗。","看看海棠如有语，杏花也到退房时。"]},{"t":"杜生绝艺","f":"七言绝句","c":["杜生绝艺两弦弹，穆护沙词不等閒。","莫怪曲终双泪落，数声全似古《阳关》。"]},{"t":"德华小女五岁能诵予诗数首以此诗为赠","f":"七言绝句","c":["牙牙娇语总堪誇，学念新诗似小茶。","好个通家女兄弟，海棠红点紫兰芽。"]},{"t":"春归","f":"七言绝句","c":["野杏溪桃三两枝，春归也作送春诗。","东君自爱长安好，能住山城得几时。"]},{"t":"发南楼度雁门关二首 其一","f":"七言绝句","c":["鸡声未动发南楼，涧水随人向北流。","欲望读书山远近，雁门关上懒回头。"]},{"t":"发南楼度雁门关二首 其二","f":"七言绝句","c":["棱磳石磴倚高梯，穹谷无人绿树齐。","总为古来征戍苦，宿云常傍塞垣低。"]},{"t":"自题中州集后五首 其一","f":"七言绝句","c":["邺下曹刘气尽豪，江东诸谢韵尤高。","若从华实评诗品，未便吴侬得锦袍。"]},{"t":"自题中州集后五首 其二","f":"七言绝句","c":["陶谢风流到百家，半山老眼净无花。","北人不拾江西唾，未要曾郎借齿牙。"]},{"t":"自题中州集后五首 其三","f":"七言绝句","c":["万古骚人呕肺肝，乾坤清气得来难。","诗家亦有长沙帖，莫作宣和阁本看。"]},{"t":"自题中州集后五首 其四","f":"七言绝句","c":["文章得失寸心知，千古朱弦属子期。","爱杀溪南辛老子，相从何止十年迟。"]},{"t":"自题中州集后五首 其五","f":"七言绝句","c":["平世何曾有稗官，乱来史笔亦烧残。","百年遗稿天留在，抱向空山掩泪看。"]},{"t":"讲武城","f":"七言绝句","c":["作计千年复万年，似嫌蒸土不能坚。","祇今讲武人何在？","衰柳残阳有乱蝉。"]},{"t":"药山道中","f":"七言绝句","c":["西风砧杵日相催，著破征衣整未回。","白雁已衔霜信过，青林閒送雨声来。"]},{"t":"黄华峪十绝句 其一","f":"七言绝句","c":["岱崧王屋旧经过，自倚胸中胜概多。","独欠太行高绝处，青天白日看山河。"]},{"t":"黄华峪十绝句 其四","f":"七言绝句","c":["绝壁孤云仔细看，云间龙穴想高寒。","碧澜寸寸横秋色，空对山灵说到难。"]},{"t":"黄华峪十绝句 其五","f":"七言绝句","c":["玉立千峰画不如，天公自有范宽图。","闾山要著黄华老，千尺珠帘得似无。"]},{"t":"黄华峪十绝句 其六","f":"七言绝句","c":["团团石瓮琢青瑶，仰面看云觉动摇。","谁著天瓢洒飞雨，半空翻转玉龙腰。"]},{"t":"黄华峪十绝句 其九","f":"七言绝句","c":["落峡飞流散不收，湍声汹汹动高秋。","也应嫌被红尘浣，才近山门便洑流。"]},{"t":"乡郡杂诗二首 其一","f":"七言绝句","c":["一沟流水几桥横，岸上人家种柳成。","来岁春风一千树，绿烟和雨暗重城。"]},{"t":"乡郡杂诗二首 其二","f":"七言绝句","c":["新堂缥缈接飞楼，云锦周遭霜树秋。","若道使君无妙思，冠山移得近城头。"]},{"t":"楚山清晓图","f":"七言绝句","c":["雨润烟浓十二峰，云间合有楚王宫。","遥知别后西州梦，一抹春愁浅淡中。"]},{"t":"三乡杂诗二首 其一","f":"七言绝句","c":["梦寐沧洲烂熳游，西风安得钓鱼舟。","薄云楼阁犹烘暑，细雨林塘已带秋。"]},{"t":"三乡杂诗二首 其二","f":"七言绝句","c":["尖新秋意晚晴中，六尺筇枝满袖风。","草合断桥通暗绿，竹摇残照漏疏红。"]},{"t":"杨秘监马图","f":"七言绝句","c":["天闲谁省识真龙，金粟堆前草色空。","忽见画图疑是梦，东华驰道麝香骢。"]},{"t":"岳山道中","f":"七言绝句","c":["野禾成穗石田黄，山木无风雨气凉。","流水平冈尽堪画，数家村落更斜阳。"]},{"t":"雪岸鸣䳺","f":"七言绝句","c":["离离残雪点荒丛，更著幽禽惨淡中。","笑杀画帘双燕子，秋千红索海棠风。"]},{"t":"客意","f":"七言绝句","c":["雪屋灯青客枕孤，眼中了了见归途。","山间儿女应相望，十月初旬得到无？"]},{"t":"论诗三首 其一","f":"七言绝句","c":["坎井鸣蛙自一天，江山放眼更超然。","情知春草池塘句，不到柴烟粪火边。"]},{"t":"论诗三首 其二","f":"七言绝句","c":["诗肠搜苦白头生，故纸尘昏枉乞灵。","不信骊珠不难得，试看金翅擘沧溟。"]},{"t":"论诗三首 其三","f":"七言绝句","c":["晕碧裁红点缀匀，一回拈出一回新。","鸳鸯绣了从教看，莫把金针度与人。"]},{"t":"风柳鸣蝉","f":"七言绝句","c":["轻明双翼晓风前，一曲哀筝续断弦。","移向别枝谁画得，只留残响客愁边。"]},{"t":"僧寺阻雨","f":"七言绝句","c":["山气森岑入葛衣，砧声偏与客心期。","僧窗连夜萧萧雨，又较归程几日迟。"]},{"t":"王子文琴斋","f":"七言绝句","c":["天上秋风月底霜，求凰一曲鬓丝长。","相如四壁消何物？","直要文君典鹔鹴。"]},{"t":"旧与赵景温","f":"七言绝句","c":["浮云流水易西东，回首梁园似梦中。","一别十年今又别，酒尊能得几回同。"]},{"t":"雪谷早行图","f":"七言绝句","c":["画到天机古亦难，遗山诗境更高寒。","贞元朝士今谁在？","莫厌明窗百过看。"]},{"t":"夜宿山中","f":"七言绝句","c":["月华人影共徘徊，未算归程梦已回。","涧水悲鸣易愁绝，长松休送雨声来。"]},{"t":"台山杂咏五首 其二","f":"七言绝句","c":["山上离宫魏故基，黄金佛阁到今疑。","异时人读清凉传，应记诸孙赋《黍离》。"]},{"t":"台山杂咏五首 其三","f":"七言绝句","c":["一国春风帝子家，绿云晴雪间红霞。","香绵稳藉僧溪草，蜀锦惊看佛钵花。"]},{"t":"台山杂咏五首 其四","f":"七言绝句","c":["沈沈龙穴贮云烟，百草千花雨露偏。","佛土休将人境比，谁家随步得金莲。"]},{"t":"台山杂咏五首 其五","f":"七言绝句","c":["灵蛇不与世相关，时复蜿蜒水石间。","何处天瓢待霖雨？","一龛香火梵仙山。"]},{"t":"乙卯二月二十一日归自汴梁二十五日夜久旱而雨偶记内乡一诗追录于此今三十年矣","f":"七言绝句","c":["桑条沾润麦沟青，轧轧耕车闹晓晴。","老眼不随花柳转，一犁春事最关情。"]},{"t":"石勒问道图","f":"七言绝句","c":["轻比韩彭作李阳，高僧久已笑君狂。","中原果有刘文叔，肯说铃声替戾冈。"]},{"t":"贞燕","f":"七言绝句","c":["杏梁双宿复双飞，海国争教只影归。","想得秋风逼凉冷，谢家儿女亦依依。"]},{"t":"留赠丹阳王鍊师","f":"七言绝句","c":["敝尽貂裘白发新，京华旅食记前身。","仙翁相见休相笑，同是邯郸枕上人。"]},{"t":"元夕","f":"七言绝句","c":["花影灯光一万重，青衫骢马踏东风。","彰阳旧事无人记，二十三年似梦中！"]},{"t":"酴醾","f":"七言绝句","c":["枕帏馀韵最清真，梦里犹来著莫人。","拟借浓阴作罗幕，玉缨多处卧残春。"]},{"t":"和德新丈","f":"七言绝句","c":["二年老眼暗兵尘，今日逢君喜事新。","结伴还乡有成约，不应先作北归人。"]},{"t":"倦绣图","f":"七言绝句","c":["香玉春来困不胜，啼莺唤梦几时应。","可怜憔悴田家女，促织声中对晓灯。"]},{"t":"雪谷晓行图","f":"七言绝句","c":["漫漫长路几时休，风雪无情梦亦愁。","羡杀田家老翁媪，瓦盆浊酒火炉头。"]},{"t":"与西僧伦伯达","f":"七言绝句","c":["行云孤鹤万缘轻，遥见乡关眼便明。","不似遗山元老子，尘埃风雨过平生。"]},{"t":"送李参军","f":"曲","c":["五日过居庸，十日渡桑乾。","受降城北几千里，出塞入塞沙漫漫。","古来丈夫泪，不洒别离间；","今朝送君行，清泪留馀潸。","生女莫作王明君，一去紫台空佩环。","生男莫作班定远，万里驰书望玉关。","我知骥子坠地无齐燕，我知鸿鹄意气青云端。","草间尺鴳亦自乐，扶摇直上何劳抟！","一衣敝缊袍，一饱苜蓿盘。","岁时寿翁媪，团栾有馀欢。","就令一朝便得八州督，争似綵衣起舞春斓斑。","去年洛阳人，今年指天山。","地远马鞯破，霜重貂裘寒。","朔风浩浩来，客子惨在颜。","扼胡岭上一回首，未必君心如石顽。","君不见，桓山乌，乳哺不得须臾閒。","众雏一朝散，孤雌回颜声悲酸。","寒雁来时八九月，白头阿母望君还！"]},{"t":"乡郡杂诗","f":"七言绝句","c":["百年乔木郁苍苍，耆老风流赵与杨。","为向榆关使君道，郡中合有二贤堂。"]},{"t":"游天坛杂诗","f":"七言绝句","c":["道民初不忘天台，姓氏分明见密崖。","为问松台千载鹤，白云何处不归来？"]},{"t":"李仲华湍流高树图","f":"七言绝句","c":["小景风流恰入时，留题纸尾竟何辞。","不因脱兔投林了，何处而今更有诗。"]},{"t":"题张彦宝陵川西溪图","f":"七言古诗","c":["松林萧萧映灵宇，烁石流金不知暑。","太平散人江表来，自讶清凉造仙府。","不到西溪四十年，溪光机影想依然。","当时膝上王文度，五字诗成众口传。","忽见画图疑是梦，而今尘土浣华颠。"]},{"t":"汾亭古意图","f":"七言律诗","c":["尧氏羲黄去未远，日作日息天机全。","杜侯袖里姑汾笔，办与南华谈窅然。","废兴知经几今昔，淳朴别有一山川。","白云亭上秋风客，不比仙翁甲子年。"]},{"t":"寄杨弟正卿","f":"七言律诗","c":["马迹车尘漫白头，苍生初不待君忧。","且从少傅论中隐，尽要元规拥上流。","东阁官梅动诗兴，洞庭春色入新篘。","归程未觉西庵远，夜夜清伊绕石楼。"]},{"t":"句","f":"七言古诗","c":["高原水出山河改，战地风来草木腥。","花啼杜宇归来血，树挂苍龙蜕后鳞。","白骨又多兵死鬼，青山原有地行仙。","燕南赵北无金土，王后卢前总故人。","神功圣德三千牍，大定明昌五十年。"]},{"t":"句","f":"七言古诗","c":["七重宝树围金界，十色雯华拥画梁。"]},{"t":"句","f":"七言古诗","c":["英威未觉消沈尽，试向舂陵望郁葱。"]},{"t":"俳体雪香亭杂咏","f":"七言绝句","c":["罗绮深宫二十年，更持桃李向谁妍？","人生只合梁园死，金水河头好墓田。"]},{"t":"王子端内翰山水同屏山赋二诗 其一 前人","f":"七言绝句","c":["郑虔三绝旧知名，付与时人分重轻。","辽海东南天一柱，胸中谁比玉峥嵘。"]},{"t":"王子端内翰山水同屏山赋二诗 其二","f":"七言绝句","c":["万里承平一梦间，风流人物与江山。","眼明今日题诗处，却见明昌玉笋班。"]},{"t":"黄华峪十绝句 其二","f":"七言绝句","c":["树经冻雨半青黄，山入高秋老更苍。","且就同游尽佳客，不妨五日未重阳。"]},{"t":"黄华峪十绝句 其三","f":"七言绝句","c":["红叶黄花风露清，比来春色不多争。","秋山却也堪人恨，白与高欢作锦城。"]},{"t":"黄华峪十绝句 其七","f":"七言绝句","c":["万古飞流泻不供，枉教喷薄困鱼龙。","谪仙剩有银河句，不道香炉更一峰。"]},{"t":"黄华峪十绝句 其八","f":"七言绝句","c":["大汉何因有蚌胎，无穷冰雹落悬厓。","只愁驼背模糊锦，翻倒龙宫复此来。"]},{"t":"黄华峪十绝句 其十","f":"七言绝句","c":["乞得三泉住不成，风沙鞍马负平生。","故山定已移文了，又被黄华识姓名。"]},{"t":"墨竹扇头","f":"七言绝句","c":["嫩香新粉玉交加，小笔风流自一家。","只欠雪溪王处士，醉来肝肺出枯槎。"]},{"t":"黄钟・人月圆卜居外家东园","f":"曲","c":["重冈已隔红尘断，村落更年丰。","移居要就，窗中远岫，舍后长松。","十年种木，一年种谷，都付儿童。","老夫惟有，醒来明月，醉后清风。","玄都观里桃千树，花落水空流。","凭君莫问，清泾浊渭，去马来牛。","谢公扶病，羊昙挥涕，一醉都休。","古今几度，生存华屋，零落山丘。"]},{"t":"仙吕・后庭花破子","f":"曲","c":["玉树后庭前，瑶华妆镜边。","去年花不老，今年月又圆。","莫教偏，和花和月，大家长少年。","夜夜璧月圆，朝朝琼树新。","贵人三阁上，罗衣拂绣茵。","后庭人，和花和月，共分今夜春。"]},{"t":"中吕・喜春来春宴","f":"曲","c":["春盘宜剪三生菜，春燕斜簪七宝钗，春风春酝透人怀。","春宴排，齐唱喜春来。","梅残玉靥香犹在，柳破金梢眼未开，东风和气满楼台。","桃杏折，宜唱喜春来。","梅擎残雪芳心奈，柳倚东风望眼开，温柔樽俎小楼台。","红袖绕，低唱喜春来。","携将玉友寻花寨，看褪梅妆等杏腮，休随刘阮到天台。","仙洞窄，且唱喜春来。"]},{"t":"双调・骤雨打新荷","f":"曲","c":["绿叶阴浓，遍池塘水阁，偏趁凉多。","海榴初绽，妖艳喷香罗。","老燕携雏弄语，有高柳鸣蝉相和。","骤雨过，珍珠乱糁，打遍新荷。","人生有几，念良辰美景，一梦初过。","穷通前定，何用苦张罗？命友邀宾玩赏，对芳樽浅酌低歌。","且酩酊，任他两轮日月，来往如梭。"]}]};